-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODExb56dc543cbe1$doc_the_public_procurement_regulation_2064_2007__2008_public_procurement_rules_2064_pdf$CODExb56dc543cbe1$,$CODEx69eebffedaba$The Public Procurement Regulation, 2064 ( 2007)$CODEx69eebffedaba$,NULL,$CODEx7320e2b5d0b7$regulation$CODEx7320e2b5d0b7$,2064,2007,206,$CODExfec2116c3de2$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "1 \n \n \nThe Public Procurement Regulation, 2064 ( 2007) \nDate of publication in the Nepal Gazette  \n2064.5.3 ( 20 August 2007 ) \nAmendment", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "The Public Procurement (First Amendment)", "content": "Regulation, 2008 (2065)  \n24 November 2008 \n(2065.8.9)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "The Public Procurement (Second", "content": "Amendment) Regulation, 2008 (2065)  \n17 December 2008 \n(2065.9.2)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "The Public Procurement (Third", "content": "Amendment) Regulation, 2011 (2068)  \n20 June 2011 ( 2068.3.6)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "The Public Procurement (Fourth", "content": "Amendment) Regulation, 2073 ( 2019) \n19 December 2019 \n(2073.9.4)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "The Public Procurement (Fifth Amendment)", "content": "Regulation, 2017 (2073)  \n9 March 2017 \n(2073.11.26)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "The Public Procurement (Sixth", "content": "Amendment) Regulation, 2019 (2075)  \n13 May 2109 \n(2076.1.30)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "The Public Procurement (Seventh", "content": "Amendment) Regulation, 2019 (2076)  \n6 June 2019 ( 2076.2.23)", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "The Public Procurement (Eighth", "content": "Amendment) Regulation, 2019 (2076)  \n1 August 2019 \n(2076.4.16 ) \n \n2 \n \nIn exercise of the power conferred by Section 74 of the Public \nProcurement Act, 2063 ( 2007), the Government of Nepal has framed the \nfollowing Rules.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -1", "title": "Chapter -1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement : (1) These Rules may be cited as the", "content": "\"Public  Procurement Regulation,  2007 (2064).\"  \n(2) This Regulation shall commence forthwith .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definition s: Unless the subject or  the context otherwise requires , in", "content": "this Regulation, -  \n(a) \"Act\" means the Public Procurement Act, 2007 ( 2063).  \n(b) \"Multi-year contract\" means a contract of which term \nexceeds  one year.  \n(c) \"Sealed quotation\" means a description , also q uoting the  \nprice, which is submitted in a sealed envelope by a \nperson, firm, company or organization that is interested  \nto execute  any work s or provide  goods or other services \npursuant to  the notice of the public entity .  \n(d) \"Secretary\" means the secretary of a Ministry , and this \nterm also includes the chief secretary of the Government \nof Nepal and other  special class officer of the \nGovernment of Nepal who perform s the functions  \nequivalent to that of a secretary.  \n(e) \"Superior office\" means the office which is higher in \nlevel than the concerned office.  \n3 \n \n(f) \"Treasury Controller Office\" means the treasury \ncontroller office under the Office of the Financial \nComptroller General.  \n(g) \"Rate fixation committee\" means the committee referred \nto in Rule 148.  \n(h) \"Head of d epartment\" means an official who serves as the \nhead of a department or other office equivalent thereto  \nunder any Ministry . \n(i) \"Ministry\" means a Ministry of the Government of Nepal , \nand this term also includes the Office of the Prime \nMinister and Council of Ministers.  \n(j) \"Standing list\" means the list referred to in  Rule 18.  \n(k) \"Users' committee\" means a committee which is formed \nby the persons who are direct beneficiaries of a \nconstruction work from among themselves in order to \nbuild, operate and maintain any construction work.  \n(l) \"Management contract\" means the contract referred to in \nclause (f) of Schedule -4.  \n(m) \"Evaluation committee\" means the committee referred to \nin Rule 147.  \n(n) \"Bid price\" means an amount which is fixed upon the \nexamination of a bid.  \n(o) \"Sub-contractor\" means a construction entrepreneur, \nsupplier, consultant or service provider who, after \nexecuting a separate contract with the construction \nentrepreneur, supplier, consultant or service provider who \n4 \n \nhas entered into a procurement contract , carries out a ny \nwork under that procurement contract.  \n(p) \"Proprietary goods\" means any accessory equipment and \nspare parts manufactured by the manufacturer of any \ngoods, machin ery or equipment for the  operation or \nmaintenance  such goods, machine ry or equi pment.  \n(q) \"Contract price\" means the procurement price set forth  in \na procurement contract , and this term also includes the \nprice fixed from the measurement of the work carried out \nunder the variation  order where such order has been \nissued and the procurement price fixed from  the price \nadjustment  where such adjustment has been made,  under \nsuch a contract.  \n(r) \"Framework or unit rate contract\" means the contract \nreferred to in  clause (b) of Schedule -3.  \n(s) \"Force account\" means any construction work to be \nexecuted by a public entity  itself.  \n(t) \"Review committee\" means the committee formed \npursuant to sub-section (1) of Section 48 of the Act.  \n(u)1 “Medicinal goods”  means medicines, injections or \nvaccines, syringes, blood bags, reagents to be used in \nlaboratories, health related equipment to be used for the \nproduction of family planning hormonals or diagnosis \nand treatment of diseases.  \n(v) 2 “Electronic bid” means a bid submitted by a bidder by \nusing the electronic procurement system.  \n \n1 Inserted by the Fifth Amendment. \n2 Inserted by the Fifth Amendment. \n5 \n \n(w) 3 “Electronic procurement system” means the procurement \nsystem established, operated and managed by the Public \nProcurement Monitoring Office by using electronic \nmeans of communicatio n pursuant to Rule 146.  \n(x) 4 “Electronic means of communication” means the \nelectronic communication technology, system or medium \napplied by the Public Procurement Monitoring Office to \nestablish, operate and manage the electronic procurement \nsystem.  \n(y) 5 “Government fund” means the Federal Consolidated \nFund, Province Consolidated Fund or Local Consolidated \nFund, and this term also includes any other government \nfund established in accordance with the prevailing law.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -2", "title": "Chapter -2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Preparation to be made for procurement proceeding : In making", "content": "preparation for any procurement proceeding , a public entity  shall do \nas follows:  \n(a) To identify the procurement  need,  \n(b) To obtain  information of the procurement contract in \npractice in the market in order to resolve various \ntechnical matters pertaining to procurement and to \nascertain the availability of supplier s, \n \n3 Inserted by the Fifth Amendment. \n4 Inserted by the Fifth Amendment. \n5 Inserted by the Fifth Amendment. \n6 \n \n(c) If goods, construction work s or consultancy service s or \nother services of similar nature w ere procured in previous \nyears, to study such procurement  processes ,  \n(d) To ascertain the de scription , quantity and scope of the \nprocurement,  \n(e) To divide the procurement into more convenient slices   \nor includ e it in package s,  \n(f) To cause a procurement plan to be prepared,  \n(g) To prepare the cost estimate of procurement,  \n(h) To identify the financial source and amount of \nprocurement,  \n(i) To select the procurement method, and  \n(j) To ascertain, in the case of a procu rement other than the \nprocurement of a construction work of up to twenty  \nmillion 6 rupees, whether or not it is required to conduct \nthe bid qualification or pre -qualification actions . \n3A.7 Provisions relating to packaging and slicing : (1) A public entity shall, \nin packaging the procurement, do so without prejudice to the number \nof packages set forth in the procurement masterplan pursuant to clause \n(c) of sub -rule (2) of Rule 7.  \n  (2) In making preparation for dividing the procurement into \nmore convenient groups/slices or including it in packages, bids shall \nbe invited separately for any construction work of such nature as can \nbe completed severally to the extent of having maximum compe tition \nfor the same.  \n \n6 Amended by the Fourth Amendment. \n7 Inserted by the Sixth Amendment. \n7 \n \n  (3) Except where it is required to conduct in the same package \nbecause of being interrelated to each other, bids shall not be invited by \nmaking bigger packages in a manner to restrict and limit competition.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Procurement not to be made without order of the competent authority: No", "content": "person shall make or cause to be made any procurement without written \norder of the competent authority.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Procurement requisition to be received: (1) Prior to  commencing the", "content": "procurement proceeding of goods, the procurement unit of the concerned \npublic entity shall obtain procurement requisition from the divisions and \nsections and have the requisition approved by the competent authority.  \n(2) The procurement requisition referred to in sub-rule (1) shall \nstate the following matters:  \n(a) Description re lating to  the type, quality, quantity of the \ngoods, \n(b) The time when the goods are required, \n(c) The estimated value of the procurement, and  \n(d) The source of funding.  \n5A.8 Description of goods, construction works and services to be approved : (1) \nPrior to procuring any goods, construction work or service, the chief of \nthe public entity shall prepare, or cause to be prepared, the specifications, \nplans, maps, designs, special requirements or other details, referred to in \nSection 4 of the Act. \n  (2) The description prepared pursuant to sub -rule (1) has to \nbe approved by the authority referred to in Rule 14.  the specifications, \nplan, map, design, special requirements or other details  \n \n8 Inserted by the Fourth Amendment. \n8 \n \n  (3) Notwithstanding anything contained in sub -rule (2), the \nspecifications, plans, maps, designs, special requirements or other \ndetails of structures of complex and special nature such as tunnels, \nrailways, ropeways, cable -car ways and road s of special natures have \nto be approved by the head of department.  \n  (4) The description prepared pursuant to sub -rule (1) may be \namended in any of the following circumstances:  \n(a) If the construction work is of complex nature from \ngeologically so that it  cannot be foreseen at the \ntime of preparation of the description,  \n(b) If there arises a situation of natural calamity after \nthe preparation of the description,  \n(c) If the departmental norms are changed,  \n(d) If the pre -determined technology or system for \nconducting the construction work is changed,  \n(e) If there arises difficulty with its implementation \nbecause of the structure of being special and \ncomplex nature.  \n(5) Except where it is required to amend the description \nprepared pursuant to sub -rule (1) in any circumstance set forth in sub -\nrule (4), the chief of public entity shall have the duty to send an \nintimation for legal action pursuant to sub -section (2) of Section 5A. \nof the Act, and the o ne level higher authority shall have such a duty in \ncases where the chief himself or herself has approved the description \nreferred to in sub -rule (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Provision  of budget and construction site: (1) No p ublic entity  shall", "content": "commence the  procurement proceeding  unless and until the required \nbudget for the procurement  is provisioned . \n9 \n \n(2) Notwithstanding anything contained in sub-rule (1), \nprocurement proceeding  may be commenced  in the following \ncircumstances even if the budget has not been provision ed:  \n(a) In the case of a procurement to be made under a multi -\nyear contract, in order to carry out procurement \nproceeding for other years after the budget required for \nthe first year has been arranged , and  \n(b) Because of being it essential to make prelamination \npreparations for procurement, to carry out acts such  as \ninviting sealed quotation s or bid s, invit ing pre-\nqualificat ion application s, publish ing a notice for the  \npreparation of  a list of consultants, invit ing proposals \nfrom consultants or mak ing available the sealed quotation \nforms, bidding documents or pre -qualification documents \nor documents relating to proposal.  \n(3)9 No p ublic entity  shall make invitation to bids without \nmaking provision of the construction site , without ensuring the \nremoval of structures including trees, plants  required to be removed \nfrom the construction site, without ensuring the budget for the \ndistribution of compensation or damages if so required, and without \nhaving approved the report on environmental study  required to be \nconducted under the prevailing law .  \n(4)10 Notwithstanding anything contained in sub -rule (3), \nnothing shall bar the making of invitation to bids in cases where the \nenvironment study report is yet to be approved in the following \ncircumstance:  \n \n9 Amended by the Sixth Amendment. \n10 Inserted by the Sixth Amendment. \n10 \n \n(a) If it is to implement a project already approved at the time of \ncommencement of sub-rule (3), \n(b) If a decision is made by the Government of Nepal, Council \nof Ministers, to implement any special project. \n(5)11 In the case of a procurement to be made in accordance with \na multi -year contract, the public entity shall, in conducting the \nprocurement actions for the other year pursuant to clause (a) of sub -rule \n(2), commence the procurement actions only after ensuring the required \nbudget.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Master procurement plan to be prepared: (1) A public entity shall prepare", "content": "a master procurement plan in making procurement for a plan or project to \nbe operated for a period exceeding one year or in making an procurement \nof an amount exceeding one hundred million rupees a year. \n(2) The master procurement plan referred to in sub-rule (1) shall \ncontain, inter alia, the following matters: \n(a) The t ype, quantity and tentative estimated cost of \nprocurement,  \n(b) The procurement method,  \n(c) If, for the purpose of maximizing competition, procurement \nis to divided in slices or packages, provision relating thereto,  \n(d) A t entative number of contracts to be concluded for the  \ncompletion of  the whole procurement actions and major \nfunctions relating to such procurement actions,  \n(e) If pre -qualification action is to be carried out for \nprocurement, matters relating thereto,  \n(f) Tentative time -table of the procurement actions ,  \n \n11 Inserted by the Sixth Amendment. \n11 \n \n(g)  The matters so specified by the Public Procurement \nMonitoring Office from time to time as to be included in \nthe master procurement plan.  \n(3) The master procurement plan prepared pursuant to  this \nRule has to be approved 12by the secretary related to the concerned \nentity in the case of any public entity referred to in sub -clause (1) of \nclause (b) of Section 2 of the Act and by the authority provided for in \nthe procurement regulation or bye -laws of the concerned public entity \nin the case of other public entity .  \n(4) The co ncerned public entity  shall each year  update the \nmaster procurement plan approved pursuant to sub-rule (3).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Annual procurement plan to be prepared : (1) Where a public entity  is", "content": "to make procurement of an amount exceeding one million rupees a \nyear, it shall, in preparing estimated annual program s and budget for \nthe next fiscal year, prepare an annual procurement plan for \nprocurement to be made in the next fiscal year. While so pre paring a \nprocurement plan , it  shall be prepared based also on the master \nprocurement plan, if any, prepared pursuant to  Rule 7. \n(2) The public entity  shall mention  the following matters in \nthe annual  procurement plan referred to in s ub-rule (1):  \n(a) Description relating to the type  of procurement,  \n(b) Possible package s of procurement,  \n(c) Time schedule of the procurement actions ,  \n(d) Procurement method s,  \n(e) Types of contracts to be concluded for \nprocurement, and  \n \n12 Amended by the Third Amendment. \n12 \n \n(f) The matters so specified by the Public Procurement \nMonitoring Office from time to time  as to be \nincluded in the annual procurement plan.  \n(3) The time  schedule referred to in  clause (c) of sub-rule (2) \nshall contain the time period for carrying out the following acts: \n(a) To prepare specifications if goods are to be \nprocured,  \n(b) To prepare the cost estimate of procurement,  \n(c) To prepare sealed quotation form, documents \nrelating to pre -qualification proposal or to \ninvite a bid or proposal for consultancy \nservice,  \n(d) To publish a notice for invitation to sealed \nquotation, pre -qualification proposal, bid or \nrequest for proposal of consultancy service,  \n(e) To evaluate sealed quotation, pre -\nqualification proposal, bid or proposal for \nconsultancy service,  \n(f) To accept sealed quotation, pre -qualification \nproposal, bid or request for proposal for \nconsultancy service,  \n(g) To conclu de a contract,  \n(h) To commence the work, and  \n(i) To complete the work. \n(4) The chief of the public entity  shall send a copy of the \nannual procurement plan prepared  pursuant to  this Regulation , along \n13 \n \nwith the estimated annual program s and budget  for the n ext fiscal \nyear, to the superior  office and the Ministry of Finance.  \n(5) The chief of the public entity  shall, after receiving the \napproved program s and budget for the current fiscal year, revise \naccordingly the annual procurement plan prepared pursuant to this \nRule and approve it and send one copy each of such plan to the \nsuperior office, Treasur y Controller Office  and Public Procurement \nMonitoring Office.  \n(6) The superior office  shall monitor whether procurement \nactions  have been  completed within the stipulated time or not.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Matters to be considered in preparing the cost estimate : (1) A public", "content": "entity shall consider  the following matters in preparing the cost \nestimate of any procurement:  \n(a) Whether the whole procurement act may be carried \nout through a single contract or a separate contract \nis to be concluded for each work,  \n(b) Whether the procurement contract is to be renewed \nor not,  \n(c) Any other options to procurement, if any,  \n(d) Maximum time and cost that may be require d to \ncomplete the work under the procurement contract, \nand  \n(e) Such o ther matters so specified by the Pu blic \nProcurement Monitoring Office as to be considered  \nby a public entity  in preparing the cost estimate.  \n(2) While preparing the cost estimate, the public entity  shall \nprepare separate item s for costs pertaining to mobilization and \n14 \n \ndemobilization, insuran ce, facilities to be provided to the  consultant, \nquality testing, occupational health and safety, as  built drawing, \ncommission  for the performance security , including the bid security 13 \nor performance security , and include them in the cost estimate.  \n(3)14 In preparing the cost estimate pursuant to sub -rule (1), \nthe public entity shall prepare it based also on the description referred \nto in Rule 5A.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Cost estimate of construction works: (1) A public entity  shall prepare", "content": "the cost estimate of construction works  subject to Rule 9.  \n(2) In preparing the cost estimate of a ny construction work, \nthe cost estimate shall be prepared as per the norms concerning the \nconstruction work, archaeological excavation  and underground works \nsuch as tunnel digging, deep tube -well and petroleum exploration,  \nwhere such norms  are available,  and failing  such norms, the  required \nnorms shall be prepared and cause d to be approved by the \nGovernment of Nepal, Council of Ministers , and the cost estimate \nshall be prepared as per the approved norms .  \nProvided that if,  in the course of carrying out the work s \naccording to such no rms, a specific type of norm is required for a \nspecific work, the chief of the concerned public entity  may cause the \nrequired norms to be prepared by the technician of such an entity and \nif the entity does not have such a technician, by the concerned \ntechnician of another public entity  and may cause such norms to be \napproved by the head of d epartment. The norms so approved shall be \nsent to the Construction Business Development Council within a \nperiod of one year.  \n \n13 Amended by the Third Amendment. \n14 Inserted by the Fifth Amendment. \n15 \n \n(3) While preparing the cost estimate pursuant to this Rule, \nthe public entity  shall, upon studying whether the goods are available \nat the site or not,  fix the period of time to be required for the  \ncomplet ion of the construction work.  \n(4) The public entity  shall, in the course of  preparing the cost \nestimate, fix the rate and price of cement, iron rod, bricks, stone, soil, \ncorrugated sheet, bitumen, and emulsion, fuel, polythene pipe, G.I. \npipe, D.I. pipe, sanitary items, electrical goods, G.I. wire and similar \nother construction m aterials, the rent of machine and equipment or \nlabour wages on the basis of the rate fixed by the rate fixation \ncommittee.  \nProvided that if the rate fixed by  the r ate fixation committee is \nnot available, the rate shall be fixed on the basis of the rate fixed by \nthe concerned government office or  a government owned corporation , \nauthority , body  or other body of similar nature  situated  nearby the \nconstruction site or the rate, rent or wage s provided by the Chamber \nof Industry and Commerce.  \n(5) In cases where even the rate , price, rent or wage s referred \nto in sub-rule (4) be not available, such rate shall be fixed on the basis \nof the rate, rent or wages specified by the head of d epartment.  \n(6) The public entity  shall have the cost estimate including \nthe drawing and design of construction work prepared pursuant to this \nRule examined from a technician or a group of technicians one level \nhigher in rank than the technician who has prepared such cost estimate \nand if any error is found, they shall have such error corrected. If such \nan entity does not have such a higher  level technician, the  head of  \ndepartmen t shall make arrangement for the examination of such cost \nestimate.  \n16 \n \n(7) The cost estimate of a construction work  shall be \nprepared in the form  given in  Schedule -1.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Cost estimate of goods: (1) A public entity  shall,  in preparing the cost", "content": "estimate of goods, prepare it subject to Rule 9 and the specifications \nof the concerned goods.  \n(2) In preparing the cost estimate of goods pursuant to sub-\nrule (1), the following matters shall be taken into account:  \n(a) The a ctual cost incurred in the procurement of the \nsame nature ma de in the current or previous years \nby the concerned public entity  or other public \nentity of the district where such a public entity  is \nlocated,  \n(b) The rate prevailing at the local market,  \n(c) The rate prevailing at  another market and estimated \ncost of transportation of goods  to the place of their \ndeliver y,  \n(d) The rate issued by the Chamber of Industry and \nCommerce.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Cost estimate of consultancy service s: (1) A public entity  shall, in", "content": "preparing the cost estimate of a consultancy service , prepare it  subject \nto Rule 9.  \n(2) While preparing the cost estimate of a consultancy \nservice pursuant to sub-rule (1), the following matters shall be taken \ninto account:  \n(a) The norms  relating to the cost estim ate of \nconsultancy service s, if any,  prepared by the \nconcerned Ministry,  \n17 \n \n(b) The t erms of reference of the concerned \nconsultancy service,  \n(c) The a ctual cost incurred in the procurement of the \nsame nature made in the current or previous years \nby the concerned public entity  or other public \nentity.  \nProvided that in preparing the cost estimate  \non the basis of  this clause, the cost estimate shall \nbe prepared by adjusting the price at the rate of \nprevious years.  \n(3) In preparing the cost estimate referred to in  this Rule , the \npublic entity  shall specify the following costs: \n(a) Remuneration of the key human resources and \nother human resources , \n(b) Travel costs, costs for accommodation of human \nresources , office expense s, costs related to \nnecessary goods, equipment and service s, costs \nrelated to  translation  and publication  of report s and \nother documents,  \n(c) If the consultant has to  arrange  for any training, \nseminar or travel, the costs required for such work , \nand other costs. \n(4)15 The cost estimates of consultancy services and other \nservices shall be prepared in the form  referred to in  Schedule -1A.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Cost estimate of other services : (1) A public entity  shall prepare the", "content": "cost estimate of other services, subject to Rule 9.  \n \n15 Inserted by the Fourth Amendment. \n18 \n \n(2) In preparing the cost estimate of the rent of any motor \nvehicle, machinery , equipment  or goods to be hired, the chief of the \nconcerned public entity  shall form a committee comprising a \nmaximum of three skilled technicians having knowledge of such \nvehicle, equipment or goods. If such an entity does not have such \ntechnical human resources , th e superior office  of such an entity shall \nform such a committee . \n(3) The committee referred to in  sub-rule (2) shall, in \npreparing the cost estimate of the rent, prepare a tentative cost \nestimate by taking into account the following matters:  \n(a) Description, specifications, condition and life of the \nmotor vehicle, machinery, equipment or goods to be \nhired,  \n(b) Prevailing market rate,  \n(c) Period of hiring,  \n(d) Price and consumption of fuel, and  \n(e) Such other matters as the committee thinks appropriate.  \n(4) The public entity  shall, in preparing the cost estimate of \ntransportation , prepare a tentative cost estimate on the basis of the \nrate fixed by the rate fixation committee in the case of a district level \npublic entity , on the basis of the departmental rate in the case of a \ncentral level public entity , and on the basis of the prevailing market \nrate in the case where there is no even such a departmental rate.   \n(5) The public entity  shall, in preparing the cost estimate of \nmaintenance of any goods, cause such cost estimate to be prepared by \nan employee of such an entity who is  expert or skilled in such matter, \nif so available, and by an individual, firm, company or organization  \nexecuting such a work if no such employee is available. \n19 \n \n(6) The public entity shall, in preparing the cost estimate  related \nto house rent and service co ntract, prepare a tentative cost estimate \naccording to the  prevailing market rate and the norms relating thereto \nissued, if any, by the Public Procurement Monitoring Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Approval of cost estimate: (1) A cost estimate prepared pursuant to Rules", "content": "10, 11 and 13 has to be approved by the following authority: \n(a)16 The c ost estimate that does not exceed ten million  \nrupees, by the gazetted third-class chief of office,  \n(b) 17 The c ost estimate that does not exceed fifty million \nrupees, by the gazetted second-class chief of office, \n(c) 18 The cost estimate that does not exceed one hundred \nmillion rupees, by the gazetted first-class chief of \noffice, \n(d) 19 The cost estimate that exceeds one hundred  million \nrupees, by the head of department.  \n(2) The cost estimate prepared pursuant to Rule 12  has to  be \napproved by the following authority: \n(a)20 The cost estimate that does not exceed one million \nrupees, by the gazetted third-class chief of office,  \n(b) 21 The cost estimate that does not exceed two million \nfive hundred thousand rupees, by the gazetted second-\nclass chief of office, \n \n16 Amended by the Fourth Amendment. \n17 Amended by the Fourth Amendment. \n18 Amended by the Fourth Amendment. \n19 Amended by the Fourth Amendment. \n20 Amended by the Fourth Amendment. \n21 Amended by the Fourth Amendment. \n20 \n \n(c) 22 The cost estimate that does not exceed five million \nrupees, by the gazetted first-class chief of office, \n(d) 23 The cost estimate that exceeds five million rupees, by \nthe head of department.  \n(3)24 If the chief of the public entity  himself or herself cannot  \napprove the cost estimate pursuant to this Rule or the description referred \nto in Rule 5A., he or she shall cause such a cost estimate or description  to \nbe approved by one level higher authority. \n(4) Notwithstanding anything contained elsewhere in this Ru le, \nthe secretary or administrative chief of a constitutional organ or body, \nMinistry, secretariat and other office of similar nature may approve the \ncost estimate of any amount whatsoever for the procurement  to be made \nfor his or her office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Cost estimate to be updated: (1) If the procurement is not made as per the", "content": "cost estimate approved pursuant to Rule 14, the public entity shall update \nsuch a cost estimate in each fiscal year in pursuance of the process \nreferred to in this Regulation.  \n(2) The public entity  shall not make an invitation to sealed \nquotations and bid s or proposal s for a consultancy service without \nupdating the cost estimate pursuant to this Rule.  \n16.25 Functions of procurement division, section or u nit: (1) A public entity \nshall establish a separate procurement division, section or unit , as \nrequired, on the basis of the procurement workload and nature of work. \n  (2) In establishing the procurement division, section or unit \nreferred to in sub -rule (1), a procurement official shall be so designated \n \n22 Amended by the Fourth Amendment. \n23 Amended by the Fourth Amendment. \n24 Amended by the Sixth Amendment. \n25 Amended by the Fourth Amendment. \n21 \n \nthat he or she bears the responsibilities of the chief of such a division, \nsection or unit. \n  (3) The procurement official referred to in sub -rule (2)  shall \nperform the following functions, in addition to the fun ctions referred to in \nsub-section (3) of Section 7 of the Act: \n(a) To prepare and update the master procurement plan \nand annual procurement plan, \n(b) To coordinate the functions related to procurement \nactions, \n(c) To collect the procurement requisition s and submit \nthem to the competent authority for approval,  \n(d) To function as the coordinator of the committee \nopening bids or proposals, \n(e) To maintain records of the procurement actions \npursuant to Rule 149, \n(f) To maintain records of time extension, perfo rmance \nsecurity/guarantee and letters of credit referred to in \nSchedule-2.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "17", "title": "Goods manufactured in Nepal to be procured : A public entity  shall, in", "content": "making procur ement by selecting any method set forth  in this \nRegulation, procure the Nepali goods even though the price of the \ngoods manufactured in Nepal is higher by up to fifteen  percent 26 than \nthe foreign goods.  \n \n26 Amended by the Fourth Amendment. \n22 \n \n18.27 Provision s relating to p reparation of standing list: (1) A person, \norganization, supplier, construction entrepreneur, consultant, non -\ngovernmental organization or service provider  that wishes to get \nregistered or updated in the standing list pursuant to Section 6A. of \nthe Act shall make an application in the form referred to in Schedule -\n2A., accompanied by the copies of the following documents, to the \nconcerned public entity:  \n   (a) The organization or firm registration certificate,  \n(b) The permanent account number or value added tax \nregistration certificate,   \n(c) The tax clearance certificate, and  \n(d) Business license, as required.  \n(2) The public entity shall make necessary inquiries in to the \napplication received pursuant to sub -section (1), register it and give \nthe receipt referred to in Schedule 2B.  \n(3) The public entity shall maintain records of separate standing \nlists referred to in Section 6A. of the Act in the form referred to in \nSchedule-2C. and update such records each fiscal year. \n(4) The standing list shall be published semi -annually by \nposting it on the notice board s of the District Administration Office  and \nthe Treasury Controller Office situated in the district or by putting it on \nthe web site of the concerned public entity. \n(5) Notwithstanding anything contained in this Rule, any  bidder \nor proponent who is not listed in the standing list shall not be deprived of \nparticipating in sealed quotation s, bids or proposals invited by the public \nentity. \n \n27 Amended by the Fourth Amendment. \n23", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "Procurement to be made from those who have obtained permanent", "content": "account number and value added tax registration certificate: (1) A public \nentity shall procure only from the individual s, firm s, organization s or \ncompanies that have obtained the p ermanent account number and value \nadded tax registration certificate from the Inland Revenue Office.  \n(2) Notwithstanding anything contained in sub-rule (1), \nprocurement may , in the following circumstance,  be made also from an \nindividual, firm, organization or company that has not obtained the value \nadded tax registration certificate: \n(a) In procuring goods or executing construction works \nof an amount less than twenty thousand rupees,28 \n(b)29 In procuring any goods, consultancy services or other \nservices on which value added tax is not leviable,  \n(c)30 …..  \n(d) 31 ….. \n(e) 32 ….. \n(f) 33 …..  \n(g) In renting a house, and  \n(h) In executing  a construction work with the  \nparticipation of users' committee or  beneficiary \ncommunity.  \n(3) Notwithstanding anything contained elsewhere in this \nRule, if there does not exist any firm or seller having obtained the \n \n28 Amended by the Fourth Amendment. \n29 Amended by the Third Amendment. \n30 Deleted by the Third Amendment. \n31 Deleted by the Third Amendment. \n32 Deleted by the Third Amendment. \n33 Deleted by the Third Amendment. \n24 \n \nvalue added tax registration certificate from the concerned Inland \nRevenue Office in a ny district specified as the remote area by the \nGovernment of Nepal, procurement of up to one million rupees may \nbe made from a supplier included in such list of suppliers available in \nthe district  as prepared by the following committee for that district:  \n(a) Chief, Treasury Controller Office   -Chairper son \n(b) Representative (officer level), District \nAdministration Office     - Member  \n(c) A technician of the District Technical Office \ndesignated by the chairperson    -Member  \n(d) Representative, District Chamber of Industry and \nCommerce       -Member  \n(e) An o fficer level employee designated by the \nchairperson      -Member -Secretary  \n(4) The Treasury Controller Office shall perform the \nfunctions of the secretariat of the committee formed pursuant to s ub-\nrule (3).  \n(5) The Treasury Controller Office shall send the list \nprepared pursuant to sub-rule (3) to the concerned Inland Revenue \nOffice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Selection of procurement contract : (1) A public entity  shall, upon the", "content": "selection  of the procurement method with regard to any procurement \nactions , select a  procurement contract by which the procurement is to \nbe made , out of the contracts referred to in Rule 21  if goods or other \nservices are to be procured, in Rule 22 if a construction work is to be \nprocured  and in Rule 23 if a consult ancy service is to be procured.  \n25 \n \n(2) In selecting a procurement contract pursuant to s ub-rule \n(1), it shall be selected having reg ard to the following matters:  \n(a) The type and quantity of procurement,  \n(b) Whether  there is a possibility that the procurement  \nof the same nature  will be made again ,  \n(c) Allocation  of risk s between the public entity  and \nthe supplier, construction entrepreneur or \nconsultant and other party, and  \n(d) Method of supervising the contract.  \n(3)34 In selecting the procurement contract pursuant to sub -rule \n(1), it shall be selected in accord ance with the procurement contract \nset forth in the standard bidding documents issued by the Public \nProcurement Monitoring Office.  \nProvided that where the standard bidding documents have not \nbeen issued by the Public Procurement Monitoring Office, the public \nentity may prepare and use the te nder documents along with the \nprocurement contract required for it , with the consent of the Public \nProcurement Monitoring Office.  \n(4) 35 After an invitation to bids has been made upon selecting \nthe tender documents and procurement contract pursuant to this Rule, \nthe standard procurement contract so selected is not subject to \nalteration except as otherwise provided in this Regulation.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Procurement contract of goods or other services : (1) A public entity", "content": "may procure goods or other services by making  any contract out of \nthe contracts referred to in Schedule -3.  \n \n34 Inserted by the Fourth Amendment. \n35 Inserted by the Fourth Amendment. \n26 \n \n(2) In entering into the contract referred to in s ub-rule (1) , it  \nshall be entered into  based on the technical specifications and period \nset forth in the bidding documents.  \n(3) The p rocurement contract shall be governed by the \nprovisions of this Regulation to the extent provided for in this \nRegulation and by the prevai ling law on the s ale of goods contract \nwith regard to  the matters not provided  for in this Regulation.  \n(4) The procurement contract of goods or the conditions of \ndelivery of goods under this Rule shall be prepared in accordance \nwith the international commercial terms (I ncoterms ). \n(5)  In making payment under th e contract  referred to in this \nRule, it shall be made generally upon the  submission of documents \nshowing the supply of goods made by the supplier  through the letter \nof credit or the medium set forth in the bidding documents .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Procurement contract for construction works: A public entity  may, for", "content": "the execut ion of  any construction work, enter into any one  contract \nout of the contracts referred to  in Schedule -4.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Procurement contract for consulta ncy services : A public entity  may,", "content": "for the  procure ment of  a consultancy service, enter into  any one  \ncontract out of the contract s referred to  in Schedule -5.  \n24.36 Conditions may be specified : If it is required to specify any other \nadditional conditions  in the bidding documents or documents relating \nto proposal, in addition to the conditions set forth  in this Chapter with \nregard to any procurement contract, additional conditions may be \nspecified so that there is no substantial deviation from the conditions \nof the procurement contract set forth in  the bidding documents or \ndocuments relating to proposal.  \n \n36 Amended by the Fourth Amendment. \n27", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -4", "title": "Chapter -4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "25", "title": "Criteria on qualification of bidders supplying goods: (1) A public", "content": "entity may, in specifying the criteria on qualification s of bidders or \nproponent s of a pre -qualification proposal who participate in the \nprocurement actions  related to the  supply of goods, specify such \ncriteria  having regard to  any or all of the following matters , as \nrequired : \n(a) Technical capacity,  \n(b) Manufacturing records,  \n(c) Technical specifications of goods,  \n(d) Economic and financial capability , \n(e) If the goods are to be installed, competency of the  \ntechnician to be involved in the installation,  \n(f) Guarantee to the effect that the goods to be \nsupplied will smoothly opera te for  a specific \nperiod,  \n(g) Provision of maintenance of goods,  \n(h) Availability of services and spare parts,  \n(i) In the case of a supplier supplying goods including \nwith installation  thereof , his or her skill, efficiency, \nexperience and reliability.  \n(2) In requiring  the documents that prove the qualification \nand technical capacity of a bidder or proponent pursuant to this Rule, \nthe public entity  may require any or all of the following documents , \naccording to the nature, quantity, importance or use of the goods:  \n28 \n \n(a) The nature , quantity, contract price and  date of the \ngoods supplied by the bidder to any government \nentity or private organization during the period of \nlast three years and the name an d address of such a \ngovernment entity or private organization,  \n(b) If the goods to be procured are of complex  or \nexceptional nature, documents as to the test of the \nproduction capacity of the bidder or pre -qualifi ed \nproponent  conducted by the concerned public \nentity itself or , on its behalf , by the competent \nauthority of the country of incorporation of such a  \nbidder or proponent,  \n(c) The certificate issued by the competent  quality \ncontrol authority or recognized body as to  the \nspecifications and quality of the goods  to be \nprocured, after inspecting such goods,  \n(d) Such s amples, supplementary details or \nphotographs as may be required to prove the \nauthenticity of the goods to be supplied,  \n(e) Proportion of the work relating to supply intended \nto be made through a sub -contractor.  \n(3) If a bidder or  prequalif ied proponent himself  or herself \ndoes not manufacture or produce the goods to be supplied, such a \nbidder or proponent shall submit the document proving that  the \nmanufactu rer of such goods has duly and exclusively authorized him \nor her  to submit the bid or pre -qualification proposal , supply and  \ninstall the goods.  \n29 \n \n(4) A bidder or pre -qualifi ed proponent who does not carry \non trade, business within Nepal shall submit the document proving \nthat, if he or she obtains the procurement contract,  his or her agent or \nauthorized seller who is capable of discharging the liabilit ies relating \nto the maintenance of the goods supplied pursuant to such a contract, \nprovision of  after-sales service and making reserve  of and supply  of \nnecessary spare -parts shall be present in Nepal .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Criteria as to  qualification of construction entrepreneur s: (1) A public", "content": "entity may, in specifying the criteria as to  the qualification of  the \nbidder or pre -qualifi cation  proponent participating in the procurement \nactions  of a construction work costing more than twenty million \nrupees,37 specify such criteria having regard to any or all of the \nfollowing matters , as required :  \n(a) General experience in the execution of works solely as a \nprime contractor or of works under a management \ncontract or as a partner of a joint venture or as a sub-\ncontractor,  \n(b) A minim um average annual turnover of construction \nworks of or above the threshold referred to in the bidding \ndocuments or prequalification documents , having \ncompleted solely or including the work s carried out as a \npartner  of a joint venture.  \nProvided that in the case where a national open \nbidding is invited, the maximum average turnover of any \nthree years out of ten years shall be taken as the basis.  \n(c) A s pecial experience upon having executed  monthly or  \nyearly a construction work equivalent  to the minimum \n \n37 Amended by the Fourth Amendment. \n30 \n \namount set forth in the bidding documents or \nprequalification documents solely or by concluding a \nmanagement contract or as a partner of joint venture or  a \nsub-contractor , and having completed successfully the \nprocurement contract s of the n ature, complexity and \nconstruction technology similar to the proposed \nprocurement contract in such a number as specified in \nsuch documents,  \n(d) Economic and financial capacity as to the availability of \nliquidity, credit facility and other financial source \n(excluding the advance payment under any procurement \ncontract) which may provide such cash -flow as may be \nnecessary to complete the proposed construct work or \nother construction work which the concerned bidder or \nprequalifi ed proponent has been executing or committed \nto execute or the accessibility to the source of such \nproperty in cases where there is no payment of money or \ndelay in payment of money required to commence the \nconstruction work referred to in  the procurement \ncontract, \n(e) Skilled human resources  as specified  in the bidding \ndocuments or  prequalification  documents,  \n(f) Main equipment , machineries  as specified  in the bidding \ndocuments or  prequalification documents in running \ncondition which are owned by the bidder o r pre -qualifi ed \nproponent  himself  or herself or which will be so available \nby way of  rent, lease, contract or other commercial means \nthat they  can be used freely during the period of the \nprocurement contrac t.  \n31 \n \n(2) In computing the amount referred to in clauses (b) and (c) \nof sub-rule(1) in the case of a national construction entrepreneur, only \nthe amount to be set after deducting the amount for value added tax \nshall be computed , and such  amount shall be adjusted acc ording to the \nupdated price index of the Nepal Rastra Bank.  \n(3) In requiring the document s that prove the technical \ncapacity  of a construction entrepreneur pursuant to this Rule, the \npublic entity  may require  the bidder or pre -qualifi ed proponent to \nsubmit any or all of the following documents, according to the nature \nof the construction work:  \n(a) Description  of the price, da te and site of the construction \nworks completed by him  or her during the period of last \nten years,  \n(b) Proportion  of the work which he or she intends to  get \nexecuted  through a sub -contractor,  \n(c) Description of the technical human resources ,38 \nequipment and plant s referred to in clause (f) of sub -rule \n(1)39 available with him  or her to complete the proposed \nwork.  \n(d)40 The description referred to in clause (n3) of sub -section \n(2) of Section 13 of the Act in order to prove the bidder’s \ntechnical capacity referred to in (n4) of sub -section (2) of \nthe said Section to complete the proposed construction \nwork.  \n \n38 Inserted by the Fourth Amendment. \n39 Inserted by the Sixth Amendment. \n40 Inserted by the Fourth Amendment. \n32 \n \n(4)41 Notwithstanding anything contained in sub -section (1), \nqualification shall be specified pursuant to sub -section (5) of Section \n10 of the Act for the construction work of such other structure as \nspecified by the concerned public entity, including structures of \ncomplex or special nature such as a power -house, turbine, bridge, \ntunnel way, railway, ropeway, cable car way, multi -storied building or \nroad, the cost estimate of which does not exceed twenty million \nrupees.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Criteria as to  qualification of proponent s of consultancy service s: (1)", "content": "A public entity  may, in specifying the criteria as to  the qualification \nof the proponent participating in the procurement actions  relating to a \nconsultancy service, specify such criteria having regard to any or all \nof the following matters:  \n(a) If the proponent being an individual, his  or her work \nexperience , and if the proponent is a firm or organization, \nits required institutional work experience,  \n(b) The required academic qualification  of the key \nemployees of the proponent,  and their work experience in \nthe works of similar nature,  \n(c) Method, procedure of performance of work, \nresponsiveness to the terms of r eference, technology \ntransfer and time  schedule , \n(d) Managerial capacity of the proponent,  \n(e) Financial capacity of the proponent,  \n(f) Involvement of native human resources  if the proposal \nhas been invited international ly, \n \n41 Inserted by the Fourth Amendment. \n33 \n \n(g) Such o ther matters as specified in the bidding \ndocuments .42  \n(2) In requiring the  documents that prove the technical \ncapacity of a proponent pursuant to this Rule, a public entity  may \nrequire any or all of the following documents , according to the nature \nof the proposed consultancy service:  \n(a) Description specifying the public or private organization \nto which  the consultancy service identical to the proposed \nconsultancy service ha s been provided during the period \nof last ten years,43 the amount and date  thereof , \n(b)  Description as to qualification of the key staff proposed \nfor the completion of the proposed work,  \n(c) Description of his or her managerial staff and average \nannual human resources in  the last three years, and  \n(d) Portion of the proposed consultancy service which he or \nshe intend s to get provided through a sub -contractor.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "Criteria as to  qualification of joint venture : (1) Bidders may, for the", "content": "purpose of participating in any procurement actions , form a joint \nventure  and submit a bid . \nProvided that a bidder may submit only one bid either as a \npartner of the joint venture or as an individual.  \n(2) A public entity  may spe cify the minimum share of the \npartners in the joint venture referred to in  sub-rule (1) and the \nminimum qualification of the principal partner and of the other \npartners  in the bidding documents.  \n \n42 Amended by the Third Amendment. \n43 Amended by the Third Amendment. \n34 \n \n(3) The public entity  shall, in specifying the qualification  \npursuant to  sub-rule (2), specify such qualification having regard to \nthe following matters with regard to  a partner in such a venture:  \n(a) His or her average annual  turnover,  \n(b) His or her special  experience and the main work \nperformed by him  or her,  \n(c) Cash-flow available with him  or her to conduct  the \nconstruction work,  \n(d) His or her capacity  related to human resources , and  \n(e) His or her capacity related to machineries  or \nequipment .  \n(4) In order to ascertain whether a joint venture has fulfilled  \nthe criteria as to  the minimum qualification specified in the bidding \ndocuments or not, the qualification of all the partners of such a joint \nventure shall be calculated.  \n(5) The public entity  shall specify the individual \nqualification of a partner of a joint venture having regard to the \nfollowing matters:  \n (a) His or her general experience in the concerned work,  \n(b) Adequacy of the resources required to complete the work \nbeing executed  or to be executed  by him  or her as per \nanother contract,  \n(c) Financial capacity, and  \n(d) Past procurement related litigation and result s thereof.  \n(6) If a joint venture is selected for a procurement contract, \nthe concerned public entity  shall require  the joint venture to get so \nregistered with the permanent account number and value-added tax in \n35 \n \nthe Inland Revenue Office that such a joint venture  has joint liability \nand its partners have personal liability.  \n(7) If a joint venture has to submit  also a bid security  while \nsubmitting a bid, such a bid security has to be  so issued in the name of \nall the  partners of the joint venture referred to in s ub-rule (1)  that all \nthe partners have the liability.  \n(7a) 44 In cases where a contract is so obtained upon being \ninvolved in the bidding process that the construction work is to be \nexecuted through a joint venture, all the members of the joint venture \nshall c omplete the construction work in accordance with the contract . \nThe liability of such a work may not be assigned to any one member \nor some members  of the joint venture  or anyone else.  \n(8) Other conditions relating to  the joint venture shall be as \nspecified in the bidding documents.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Documents setting out e conomic and financial capacity may be", "content": "required : (1) In requiring the documents that prove the bidder’s \neconomic and financial capacity in the bidding documents,  the public \nentity may require any or all of the following documents , according to \nthe nature of the construction work :  \n(a) His or her bank statement,  \n(b) Financial statement s of his  or her business transaction s,  \n(c) Balance sheet showing the statement s of his  or her assets, \nliabilities and profit and loss,  \n(d) Other matters showing his or her economic and financial \nstatus, and  \n(e) Other matters specified in the bidding documents.  \n \n44 Inserted by the Sixth Amendment. \n36 \n \n(2) In requiring the  balance sheet referred to in  clause (c) of \nsub-rule (1), balance sheet s of the past two to five fiscal years may be \nrequired,  according to the nature of the work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Provision s relating to  execution of  work by sub-contractor : (1) If a", "content": "public entity  is to invite bid s providing that the work may be executed  \nthrough a sub -contractor as well, it shal l specify the following matters \nin the bidding documents:  \n(a) That he  or she may cause the work to be executed by  a \nsub-contractor,  \n(b)45 That a m aximum of twenty -five percent of the work may \nbe executed through a sub -contractor  and description of \nthe nature of such work,  \n(c) The criteria as to the q ualification of the sub -contractor, \nas required.  \n(2) Where the criteria as to  qualification are specified \npursuant to sub-rule (1), the bidder shall , prior to making the \nprocurement contract, submit the document demonstrat ing the criteria \nas to the qualification of the sub -contractor.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -5", "title": "Chapter -5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "31", "title": "Procurement to be made through bidding : (1) 46 A public entity  shall", "content": "procure  through bidding  any construction works, goods or services  \nwhatsoever  of which cost estimate exceeds two  million rupees.  \n(2) In the c ircumstances set forth in Section 15 of the Act, \ngoods, construction works or services shall be procured by  making \ninvitation to  international open bidding.  \n \n45 Amended by the Fourth Amendment. \n46 Amended by the Fourth Amendment. \n37 \n \n31A. 47 Procedure of procurement through lump sum price rate  method : (1) If \na public entity needs to procure any construction work which is of \nsuch a nature as not requiring any qualification and the cost estimate  \nof which  does not exceed twenty million rupees , it may procure such \nworks through competition on the basis of the lump sum rate method \nthrough a national bidding, upon publishing the cost estimate.  \n  (2) In submitting a bid pursuant to sub -rule (1), a bidder \nshall submit the bid offering the lump sum rate which is less or more \nby a certain percent than the total c ost estimate.  \n  (3) The method referred to in sub -section (1) may not be \nused in the procurement actions requiring the multi -year contract.  \n32B.  48 Procedure for procurement to be made at the rate specified by the \nproducer or authorized seller ( catalogue shopping method ): (1) A \npublic entity may procure any heavy equipment, motor vehicles, tools, \nmachineries, equipment, medical devices required for health services \nsuch as X -ray and MRI or similar other mechanical goods through \ncompetition upon gi ving a written notice of seven days in minimum to \nfifteen days in maximum to the companies which produce or \ndistribute the goods of similar standards or their authorized sellers.  \n  (2) Upon receipt of the notice pursuant to sub -rule (1), the \nmanufacturing company or its authorized seller who wishes to sell \nsuch goods shall register an application with such a public entity, \nattaching therewith the description (catalogue or brochure) containing \nthe official specification, quality, price and facilities of the product.  \n  Provided that the bid security shall not be required for such \nregistration of the application.  \n \n47 Inserted by the Fourth Amendment. \n48 Inserted by the Fourth Amendment. \n38 \n \n  (3) A list of manufacturing companies of the products of \nsimilar specifications and quality or their authorized sellers shall be \nprepared having re gard to the descriptions ( catalogues  or brochures)  \ncontaining the specification, quality, price and facilities submitted by \nthe manufacturing companies or their authorized sellers who have \nbeen registered pursuant to sub -section (2).  \n  (4) An invitation shall, specifying the quantity of the goods \nto be pr ocured on the basis of the list referred to in sub -rule (3), be \nmade to financial proposals, along with an offer to make discount in \nthe price or addition to the facilities out of the price and facilities \nspecified by the manufacturers or authorized seller s. \n  (5) Upon receipt of the proposals referred to in sub -rule (4), \nthe lowest evaluated substantively responsive proponent shall be \nselected upon making evaluation pursuant to this Regulation on the \nbasis of, inter alia, the offered discount in the price and addition to the \nfacilities.  \n  (6) The procurement contract shall be made with the \nproponent selected pursuant to sub -rule (5), against the performance \nsecurity pursuant to Rule 110.  \n  (7) The method referred to in sub -rule (1) shall not be used \nin the procurement actions requiring the multi -year contract.  \n31C. Procedure for procurement to be made through limited tendering \nmethod: (1) If a public entity needs to procure any goods, construct ion \nwork, consultancy service or other service which  are or will be \navailable  limitedly , it may make such procurement by inviting bids or \nproposals through a fifteen -day notice on invitation to bids after \nascertaining the situation that the number of available suppliers, \nconstruction entrepreneurs, consultants or servic e provides of such \nnature is three or below, so that there is competition between such \n39 \n \nsuppliers, construction entrepreneurs, consultants or service providers \nonly. \n  (2) The method referred to in sub -rule (1) shall not be used \nin the procurement actions r equiring the multi -year contract.  \n  (3) In making procurement through the limited tendering \nmethod, the public entity shall obtain prior approval of one level \nhigher authority.  \n31D. 49 Procedure for procurement to be made through buy back method : If \nthere exists a situation that  it w ould not be cost effective , after the \nexpiry of the period of their guarantee or warrantee specified by their \nmanufacturers,  to repair, maintain and bring into use any motor \nvehicles, machineries, equipment, devices, chemi cals, fertilizers, \npesticides or other goods of similar nature owned by a public entity \nand they would not yield results conforming to the standards specified \nby such manufacturing companies or cannot be reused or purposeful, \nand that it would not be appro priate to keep storing them or even to \nauction them from the point of view of public health or environment, \nthe public entity may ascertain such a situation and return the old \ngoods to the concerned manufacturer , authorized seller or supplier and \nobtain in  exchange the new goods of similar nature from the same \nmanufacturer, authorized seller or supplier.  \n  (2) In making an exchange pursuant to sub -section (1), \nprocurement shall be made by making a procurement contract after \nobtaining a proposal of valuation of the old goods from the \nmanufacturer, authorized seller or supplier of such goods  after \ndeducting the valuated amount of the old goods from the specified \nselling price of the new goods.  \n \n49 Inserted by the Fourth Amendment. \n40 \n \n  (3) The quality of the new goods to be procured pursuant  to \nthis Rule has to be certified by the recognized institution.  \n  (4) In making the procurement contract pursuant to sub -rule \n(2), it has to specify whether or not the new goods to be procured can \nbe re-exchanged by using this method after their life -cycle. \n  (5) In making procurement pursuant to sub -rule (1), the \npublic entity shall so procure only after preparing a list of the old \ngoods and new goods available in the market and obtaining the \napproval of the head of department.  \n  (6) The method referred to in sub -rule (1) shall not be used \nin the procurement actions requiring the multi -year contract.  \n31E. 50 Procurement to be made through competition between native bidders \nonly: (1) In inviting single stage open bids pursuant to sub -section (2) \nof Section 11 of the Act,  a construction work the cost estimate of \nwhich is above twenty million rupees but  not exceeding  two thousand \nmillion  rupees 51 has to be procured upon having competition between \nnative bidders only through the national open bidding, except in the \ncircumstances referred to in Section 15 of the Act.  \n  (2) In making procurement pursuant to sub -rule (1), the \nnotice on invitation to bids and bidding documents have to specify \nthat bids have to be submitted by having kept the techni cal and \nfinancial proposals in two separate envelopes to be sealed, with each \nenvelope clearly stating which proposal it contains, and then by \nsealing both proposals in another separate outer envelope.  \n  (3) The bidding documents to be prepared pursuant to  sub-\nrule (2)  shall, for the technical proposal, specify the qualification \n \n50 Inserted by the Fourth Amendment. \n51 Amended by the Eighth Amendment. \n41 \n \ncriteria establishing the technical and economic and financial capacity \nreferred to in Rules 25, 26, 28 and 29.  \n  (4) The technical proposals referred to in sub -rule (3) shall \nbe opened in accordance with the process referred to in Section 32 of \nthe Act, and the substantive responsive bid shall be determined by \nmaking examination pursuant to Rules 59, 60, 62 and 63.  \n  (5) The bids that meet all the qualifying criteria referred to i n \nsub-rule (4) shall be considered to be the substantively responsive \nbids, and all such successful bidders shall be notified giving a period \nof at least seven days of the venue, date and time for opening \nfinancial proposals, asking them to appear at that date and time.  \n  (6)52 The financial proposals of the bidders who are not \nsuccessful on the basis of the qualifying criteria upon evaluation of \ntheir technical proposals pursuant to sub -rule (4) shall be returned to \nthe concerned bidders.  \n  Provided that th e financial proposal of any bidder who submits \nthe bid through the electronic procurement system shall not be \nreturned.  \n  (7) The lowest evaluat ed substantively responsive bid shall \nbe selected by opening the financial proposals of the successful \nbidders p ursuant to sub -rule (4) in accordance with the process \nreferred to in Rule 79 and making their financial and special \nevaluation pursuant to Rules 61, 64 and 65.  \n31F.53 Preference to be given to domestic bidders : (1) Domestic preference \nshall be given to the domestic firms, organizations or companies  that \n \n52 Amended by the Sixth Amendment. \n53 Amended by the Sixth Amendment. \n42 \n \nparticipate solely or in joint venture with domestic firms, \norganizations or companies in the case of an international bidding.  \n  (2) In giving preference pursuant to sub -rule (1), the \nproposal of a domes tic firm, organization or company whose bid price  \nexceeds by up to five percent of the bid price offered by a foreign \nfirm, organization or company that offers the lowest price  may be \naccepted.  \n31G. 54 Procedure for procurement by making invitation to financ ial \nproposals of construction works : (1) If it needs to procure such \nconstruction work pursuant to sub -section (9) of Section 59 of the Act \nupon termination of the procurement contract pursuant to sub -section \n(7) of the said Section, such procurement may be made by making \ninvitation to fina ncial proposals from the bidders selected pursuant to \nSection 25 of the Act, on giving a period of fifteen days to that end.  \n  (2) If the procurement is to be made by giving the period \nreferred to in sub -rule (1), it shall be specified that only sealed \nfinancial proposals are to be submitted.  \n  (3) In preparing the bidding documents for the purpose of \nprocurement pursuant to sub -rule (1) , the design as per the \nrequirement or cost estimate for the remaining work, after deducting \nthe works already completed i n conformity with the design or cost \nestimate at the termination of the procurement contract, has to be \nrevised and approved pursuant to Rule 5A.  \n  (4) The lowest evaluated substantively responsive bid shall \nbe selected by opening the financial proposals r eferred to in sub -rule \n(1) in accordance with the process referred to in Rule 79 and making \n \n54 Amended by the Sixth Amendment. \n43 \n \ntheir financial and special evaluation pursuant to Section 25 of the Act \nand Rules 61, 64 and 65.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Matters to be specified in pre-qualification documents : If a public", "content": "entity is to make  invitation to  bids upon determining the pre-\nqualification, it shall prepare pre -qualification documents prior to \ninviting bid s. Such pre -qualification documents shall contain the \nfollowing matters:  \n(a) The q ualification requ ired for the proposed work , and in \nthe case of a joint venture, the qualification of its \npartners,  \n(b) The d ocuments and information to be submitted by a \nproponent  to establish  his or her qualification and \neligibility,  \n(c) If procurement  needs to be made by making separate lot s \nor package s of the goods or construction work s, such a \nlot or package,  \n(d) The method of preparing a proposal,  \n(e) The process of evaluating pre -qualification proposal s,  \n(f) The main conditions of the procurement contract,  \n(g) Other matters so specified from time to time by the \nPublic Procurement Monitoring Office as to be included \nin the pre -qualification documents, and  \n(h) The manner , place, deadline  and time  for submitting the \npre-qualification proposal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Pre-qualification criteria to be approved : Prior to making invitation to", "content": "pre-qualification proposal s, the public entity  shall get the pre -\n44 \n \nqualification criteria specified pursuant to Rules 25 and 26 to be \napproved by  the head of d epartment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "34", "title": "Pre-qualification documents to be provided : (1) 55 The public entity", "content": "shall provide  the pre-qualification documents to an y interested  person , \nfirm, organization or company by collecting the  fees as  follow s, on \nthe basis of the cost s incurred in the prepar ation of  such documents : \n(a) Five thousand rupees for above twenty million rupees but \nnot exceeding one hundred million rupees,  \n(b) Ten thousand rupees for above one hundred  million \nrupees but  not exceeding  two hundred fifty million \nrupees,  \n(c) Fifteen thousand rupees for any amount whatsoever \nabove two hundred fifty million rupees.  \n(2) The documents referred to in s ub-rule (1) shall bear the \nsignature of the chief of the public entity  or the employee designated \nby him  or her and the seal of the office. The pre -qualification \ndocuments may be provided  by the concerned public entity  or two or \nmore other entities specified by such an entity .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Selection of qualified applicant s: (1) The evaluat ion committee shall", "content": "make necessary examination as to whether an applicant for pre -\nqualification has met each qualif ying criteri on specified  in the pre -\nqualification documents or not. In so examining, any applicant who \nhas met all the qualifying criteria shall be deemed to have been \nselected in the qualification examination , and an y applicant who has \nnot met all the qualifying criteria shall b e deemed not to have been \nselected.  \n \n55 Amended by the Fourth Amendment. \n45 \n \n(2) The applicant s for pre -qualification selected from the \nexamination referred to in  sub-rule (1) shall be deemed to be qualified \nto submit bid s for the related procurement  proceeding .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Report to be submitted : (1) The evaluation committee shall,  within", "content": "fifteen days of the date on which it opened the proposals ,56 prepare \nand submit a report together with the detailed analysis of the \nexamination made pursuant to Rule 35 to the public entity .  \n(2) The evaluation committee shall specify the following \nmatters in the report referred to in s ub-rule (1):  \n(a) Name and address of the applicant,  \n(b) Document that establish  each criterion of the \nqualification of the applicant,  \n(c) Table, if so required,  \n(d) If the proposal  has been  submitted as a joint \nventure, whether the documents relating to the \njoint venture are complete or not and the share and \nliability of each partn er of such a joint venture,  \n(e) If procurement needs to be made by making \nseparate lots or packages of the goods or \nconstruction work, the process adopted to examine \nsuch a lot and package and the applicant s selected \nfor participati on in the procurement  proceeding  of \nsuch a lot and package.  \n(f) The r eason for selecting or not selecting the \napplicant.  \n \n56 Amended by the Sixth Amendment. \n46", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Matters to be specified in bidding documents : The public entity  may,", "content": "in addition to the matters referred to in Section 13 of the Act, specify \nthe following matters , as required,  in the bidding documents:  \n(a) Plan, drawing of the proposed work,  \n(b) Bill of quantities,  \n(c) Quantity of goods,  \n(d) Incidental work s to be done by the bidder,  \n(e) Time for supplying the goods, completing the \nconstruction work,  \n(f) Provision concerning warranty and maintenance,  \n(g) Type and quantity of necessary training and \nsupervision to be provided by the bidder,  \n(h) Requirement th at the goods or spare -parts to be \nsupplied must be new and original,  \n(i) Source of fund s required for the proposed \nprocurement , \n(j)57 Such other matters as specified by the Public \nProcurement Monitoring Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Prohibition of d iscrimination : (1) Except in the c ircumstance s set", "content": "forth in clause (h) of sub-section (2) of Section 13  and sub -section (8) \nof Section 14 58 of the Act, no p ublic entity  shall discriminate among \nthe bidder s in procurement proceeding  on the basis of nationality.  \n(2) In cases where a bidder is unable to obtain any document \nrequired as per the bidding documents, the concerned public entity  \n \n57 Inserted by the Fourth Amendment. \n58 Inserted by the Fourth Amendment. \n47 \n \nshall recognize  other document submitted by him  or her which is \nequivalent to such a document.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Details of agent to be set out : (1) In cases where a foreign bidder has", "content": "appointed his  or her agent in Nepal in the course of submission of the  \nbid, he  or she shall s et out  the following details in respect of such an \nagent:  \n (a) Name and address of the agent,  \n(b) Figure of the commission the agent is entitled to, \ntype of currency and the mode of payment,  \n(c) Any other condition related to the agent,  \n(d) If he or she is  a local agent, the certified copy of \nhis or her permanent account number registration \ncertificate and a letter showing  his or her \nacceptance to become the agent. \n(2) The agent shall, in submitting a  bid on behalf of the \nforeign bidder , clearly set out the matters set forth  in clauses (b) and \n(c) of sub-rule (1).  \n(3)  If the foreign bidder fails to clearly set out the matters \nset forth  in sub-rule (1) or if he or she has submitted a bid setting out \nthat he  or she has no local agent but the contra ry is subsequently \nproved  or if he or she has quoted less amount of commission to be \ngiven to the agent  but it is subsequently proved that the agent has \nreceived more commission, the public entity  shall take action  to \nblacklist such a bidder pursuant  to Rule 141.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "40", "title": "Criteria and document s relating to eligibility of b idder to be", "content": "mentioned : (1) The public entity  shall mention in the bidding \ndocuments the criteria as to eligibility of the bidder and cop ies of the \ndocuments to be submitted by the bidder to prove such eligibility.  \n48 \n \n(2) The documents set forth in sub-rule (1) shall be as follows: \n(a) Firm, organization or company registration certificate,  \n(b) Business registration license,  \nExplanation:59 For the purpose of this clause, the term \n\"business registration license\" means the certificate or \nlicense obtained by a n entrepreneur pursuant to the \nprevailing law if such a certificate or license is so \nrequired under such law to carry on his or her business.  \n(c) Value added tax registration certificate and permanent \naccount number (PAN) registration certificate,  \n(d)60 Tax clearance certificate or the certified document \nobtained from the concerned entity showing the filing \nof income returns for up to  such period as specified \nby the public entity  or proof or evidence showing \nextension of the time -limit for the filing of income \nreturns, \n(e) A written declaration made by the bidder to the effect \nthat he  or she is not ineligible to participate in the \nprocurement proceeding, he or she has not any conflict \nof interest in the proposed procurement proceeding, and \nhe or she has not  been sentenced for a ny offence \nrelated to the  concerned profession or business , \n(f)61 Such o ther documents as the public entity  considers \nnecessary, without being contrary to the Act, this \nRegulation and standard bidding documents. \n \n59 Amended by the Fourth Amendment. \n60 Amended by the Fourth Amendment. \n61 Amended by the Sixth Amendment. \n49 \n \n(2a) 62 Notwithstanding anything contained in sub -rule (2), a \nnon-resident bidder is not required to submit the documents referred \nto in clauses (c) and (d) of that sub -rule. \n(3) If the bidding documents omit to specify or do not clearly \nspecify the documents referred to in s ub-rule (2) or require \namendment in some respect, the public entity  may specify , clarify or \namend such documents by publishing a notice in a national daily \nnewspaper and , in the case of an international bidding , in an \ninternational media , within the period for submission of bids.   \nProvided that  in so publishing a notice,  if the bidde rs require \nadditional time for submission of bids , the deadline for submission of \nbids shall also be extended . \n(4) No bid of the bidder who fails to submit the document s \nreferred to in s ub-rules (1) and (2)  shall be entertained.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Language of bid: (1) Except as otherwise provided  for in the Act and", "content": "this Regulation, the pre-qualification documents, bidding documents, \ndocuments relating to request for proposal, notice  on invitation to pre -\nqualification, bid s or proposal s and procurement contract sha ll be \nprepared in the Nepali language  as far as possible  and in the English \nlanguage,  if it is not so possible . \n(2) A bidder may submit any document s or materials relating \nto procurement written  or printed in both Nepali and/or  English \nlanguage s to the public entity . \nProvided that the  relevant  portion of such document s or printed \nmaterials shall have been translated into the English language by the \nauthorized body of the concerned country , and in the event of any \n \n62 Inserted by the Third Amendment. \n50 \n \ndivergency between such document s or prin ted materials and  such \ntranslated portion, the translated portion shall prevail.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Matters to be specified in technical specifications of goods: In", "content": "specifying the technical specifications of goods in the bidding \ndocuments, the public entity  shall, as required,  specify the following \nmatters:  \n(a) Plan, drawing and design of the proposed work,  \n(b) Bill of quantities,  \n(c) Relevant physical and chemical characteristics and \nanticipated performance characteristics of the \ngoods,  \n(d) Technical configuration,  \n(e) Whether the spare parts and specified  services \nwhich are required during the life of the goods will \nbe available or not,  \n(f) Descriptive booklet s or sample s of the goods to be \nsubmitted together with the bid,  \n(g) Details of the guarantee of anticipated performance \nand quality,  \n(h) Provision concerning warranty and maintenance,  \n(i) If the goods may cause any environmental impact, \nsuch an impact and the measures to be taken to \nmitigate such an impact,  \n(j) The criteria and method to be applied to examine  \nwhether the goods supplied conform to  the \nspecifications set forth in the bidding documents or \nnot, and  \n51 \n \n(k) Such o ther necessary matters as specified by the \npublic entity .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Matters to be specified in technical specifications of", "content": "construction works: In specifying the technical specifications of \na construction work in the bidding documents, the public entity  \nshall, as required,  specify the following matters:  \n(a) Scope and objective of the proposed construction \nwork,  \n(b) Physical nature and conditio n of the construction \nsite, \n(c) Description of work s such as the design, \nconstruction, erection of equipment, production  \nand installation of the proposed construction work,  \n(d) Bill of quantities containing the estimated quantity \nof each unit item of the construction work,  \n(e) If the construction work cause s environmental \nimpact, description of, and the measures to be \ntaken to mitigate , such an impact,  \n(f) If the work also invo lves mechanical, sanitary and \nplumbing and electricity installation works, special \ntechnical specifications thereof,  \n(g) Detailed description of the equipment and spare \nparts to be supplied,  \n(h) Description relating to expected performance or  \nguarantee of  the quality,  \n(i) Inspection and test to be carried out at various \nstages of the construction work,  \n52 \n \n(j) Completion test  of work ,  \n(k) Technical document s to be provided by the \nconstruction entrepreneur upon completion of the \nconstruction work,  as built drawings, equipment \noperating manual s, as required,  \n(l) Inspection and performance test to be carried out \nby the public entity  for acceptance of the \nconstru ction work,  \n(m) Schedule of time for commencing and completing  \nthe construction work, and  \n(n) Such o ther necessary matters as specified by the \nconcerned public entity .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Matters to be specified in specifications of other services : In", "content": "specifying the technical specifications of other services in the bidding \ndocuments, the public entity shall, as required, specify the following \nmatters:  \n(a) The purpose and scope of the service,  \n(b) Expected  performance, the  work to be discharged \nand serv ices to be rendered by the service provider,  \n(c) Descriptive booklet or sample to be provided by \nthe bidder together with the bid,  \n(d) Conditions to be complied with by the service \nprovider,  \n(e) Criteria and method  for the  evaluat ion of  the \nservices provided by the service provider,  \n(f) Quality testing and inspection of the work or \nservice,  \n53 \n \n(g) Description as to  the guarantee of performance and \nquality,  \n(h) Type and quantity of training to be provided and \nsupervision to be made by the service provider, and \n(i) Such o ther necessary matters as specified by the \npublic entity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Documents to be included in bidding documents: A Public entity  shall", "content": "have to include the following documents in the bidding documents \naccording to necessity by taking into account the nature of the goods, \nconstruction work and other services to be procured: \n(a) Instruction to bidder and bid form,  \n(b) Format of the bid security,  \n(c) Format of the performance security,  \n(d) Format of the advance payment security,  \n(e) Conditions and sample of procurement contract,  \n(f) Specifications and drawings, \n(g) Time schedule for commencement and completion of \nthe work, currency of payment, the source from which \nand place 63where materials may be available, and  \n(h)64 Description referred to in clause (n3) of sub -section \n(2) of Section 13 of the Act, \n(i) 65 The matter that the concerned bidder shall be \nresponsible for the validity of documents submitted \nwith the bid, \n \n63 Amended by the Fourth Amendment. \n64 Inserted by the Fourth Amendment. \n65 Amended by the Fourth Amendment. \n54 \n \n(j)66 Such other documents as the public entity \nconsiders necessary, without being contrary to the \nAct, this Regulation and standard bidding \ndocuments.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Instruction to prepare and submit bids: (1) ……67 A public entity  may,", "content": "in providing instructions in the bidding documents for preparing and \nsubmitting the bid, provide instructions in respect of the following \nmatters:  \n(a) The language in which the bid is to be prepared,  \n(b) Manner of expressing the price in accordance  with \nthe international commercial terms (I ncoterms ) \nused in international trade,  \n(c) Necessary information as to joint venture,  \n(d) A list of the documents to be submitted along with \nthe bid by the bidder,  \n(e) Sample of goods and the number of samples to be \nsubmitted by the bidder to the concerned public \nentity,  \n(f) In the case of procurement of goods, whether there \nrequires to be specified the list of stocked  spare \nparts of such goods recommended by the \nmanufacturer and the quantity of stock of each \nspare part  with him or her , their per unit price and \nwhether the price of these spare parts will escalate \nor not after the expiry of the contract,  \n \n66 Amended by the Sixth Amendment. \n67 Deleted by the Second Amendment. \n55 \n \n(g) Requirement that the bidder sh ould state in his  or \nher bid the manufacturer of the goods to be \nsupplied, country of manufacture, brand, model \nand catalogue  number  thereof , \n(h) The name, pos t and address of the contact \nemployee designated by the public entity  to clarify \nany matter on procurement proceeding  if the bidder \nwants to inquire the public entity about it.  \n(i) If the bidder has to provide training to the \nemployees of the public entity  or transfer \ntechnology to such an entity as per the procurement \ncontract, matters relating thereto,  \n(i1) 68 Matter that technical capacity will not be counted \npursuant to clause (n4) of sub -section (2) of \nSection 13 of the Act,  \n(j) Statement that the public entity  reserves the right \nto accept or reject the submitted bid s, and  \n(k)69 Such other documents as the public entity \nconsiders necessary, without being cont rary to the \nAct, this Regulation and standard bidding \ndocuments.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Bidding documents to be approved : After the preparation of bidding", "content": "documents, document s relating to invitation to proposal s, the chief of \nthe concerned Public entity  shall approve such documents  prior to the \ninvitation to bids .70 \n \n68 Inserted by the Fourth Amendment. \n69 Amended by the Sixth Amendment. \n70 Inserted by the Fourth Amendment. \n56", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Fees for bidding documents : (1) A  person , firm, organization or", "content": "company  wishing to purchase bidding documents shall obtain the \nbidding documents signed by the chief of the concerned public entity  \nor an employee designated by him  or her and bearing  the seal of the \noffice from that entity or other two or more entities specified by it, \nupon payment of the following fee s: \n(a)71 Three thousand rupees for above two million \nrupees but not exceeding twenty million r upees, \n(b) Five thousand rupees for above twenty million \nrupees but not exceeding one hundred million \nrupees,  \n(c) Ten thousand rupees for one hundred million \nrupees but not exceeding  two hundred fifty million \nrupees,  \n(d) Twenty thousand rupees for any amount \nwhatsoever exceeding  two hundred fifty million \nrupees.  \n(2) If any person, firm, company or organization request s in \nwriting , by paying the fees  referred to in  sub-rule (1) and applicable \nfees for postage or courier , to send the bidding documents or \ndocuments relating to request for proposal, th e concerned public  \nentity shall send the bidding document s to such a person, firm, \ncompany or organization through post or courier.  \nProvided that if such a  person , firm, company or organization \ndoes not receive in time the bidding document s so sent,  the public \nentity shall not be responsible for it.  \n \n71 Amended by the Fourth Amendment. \n57", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Cost estimate to be specified in notice of invitation to bids: The cost", "content": "estimate of a construction work of not exceeding  twenty million \nrupees 72shall be specified in the notice of invitation to bid s. \n49A. 73 Matters to be specified in notice of invitation to bids : The public \nentity shall also specify the following matters, in addition to the \nmatters set forth in Section 14 of the Act, in the notice of invitation to \nbids: \n(a) Information as to national or international bidding,  \n(b) Information as to prequalification, with or without \nqualification  bid, \n(c) Information as to the method of procurement for \nwhich invitation to bids has been made,  \n(d) Information as to the manner of submission of \nelectronic bids,  \n(e) Amount of the cost estimate pursua nt to sub -rule \n(1) of Rule 31 A. \n(f) In the case of the limited tendering referred to in \nRule 31C., notice to be given to such limited \nbidder,  \n(g) In the case of the bidding referred to in sub -section \n(8) of Section 14 of the Act, the matter that only \ndomestic bidders can participate,  \n(h) In the case of the bidding referred to in sub -section \n(11) of Section 14 of the Act, the matter that \npreference will be given to joint ventures with \ndomestic construction entrepreneurs,  \n \n72 Amended by the Fourth Amendment. \n73 Inserted by the Fourth Amendment. \n58 \n \n(i) 74The matter that a new firm, company or \norganization opened and owned fully or partially \nby a person, firm, organization or director of a \ncompany wh o is already blacklisted pursuant to the \nAct or another firm, organization or company \nbeing held in the name of either himself or herself \nor persons including him or her cannot submit bids,  \n(j) Such other matters as the public entity considers \nnecessary.  \n50.75 …...", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Visit of site of works : (1) A bidder may, in order to obtain necessary", "content": "information for preparing the bid or entering into a  procurement \ncontract, himself  or herself visit or cause his  or her employee  or agent \nto visit the site of construction works at his  or her own expense and at \nhis or her responsibility for the possible risk.  \n(2) If the public entity  has to grant permission for the visit of \nthe site of construction works pursuant to  sub-rule (1), it shall grant \nsuch a permission.  \n(3) In order to provide actual inf ormation about the site of \nconstruction works, the public entity  may arrange a visit of the site of \nconstruction works for the bidders prior to the meeting to be held \npursuant to Rule 52.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "52", "title": "Pre-bid meeting : (1) A public entity  may, in order to provide  the", "content": "bidders with  information relating to the bidding documents, technical \nspecifications, site of construction works or similar other  matters, \norganize a meeting of bidders  in advance of  at least ten days of the \ndeadline for submi ssion of bids in the case of a notice on invitation to \n \n74 Amended by the Sixth Amendment. \n75 Repealed by the Third Amendment. \n59 \n \nnational bidding  and of at least fifteen days of such  deadline in the \ncase of a notice on invitation to international bidding.  \n  76Provided that in cases where a notice on re -invitation to  bids \npursuant to sub -sections (4a) and (4b) of Section 14  of the Act has \nbeen published and a pre -bid meeting has not yet been held, such a \nmeeting may,  in order to provide the bidders with further information \nas to the re -bidding, be organized in advanc e of at least five days in \nthe case of the national bidding and of at least seven days in the case \nof the international bidding.  \n(2) A bidder may  ask or make any  question or query on the  \nprocurement proceeding  to the public entity  at the meeting  referred to \nin sub -rule (1),  and such an entity shall make available as promptly as \npossible the answer of such a question or query without identifying  \nthe source of questioners  and the minute s of the meeting to all \nbidders .  \n(3) If  any modification to any technical or commercial \naspects of the bidding documents  becomes necessary as a result of \nthe meeting organized pursuant to sub -rule (1) , the public entity  shall, \nwithin five days of such a meeting,  modify the documents accordingly  \nand send a notice of such modification  to all the bidders who have \npurchased the bidding documents.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "Bid security : (1) The pub lic entity shall specify in the  notice on", "content": "invitation to bids  certain amount which is within a minimum of two to \nthree percent of the amount of approved cost estimate and applicable \nto all bidders according to the nature of procurement as the amount \nbid security to be  furnished  by a bidder along with the bid.  Such an \n \n76 Inserted by the Fourth Amendment. \n60 \n \namount shall be in form of a cash deposit or of a bid security equal to \nthat amount issued by a commercial bank or financial institution .77 \n  Provided that in cases where an invitation to bids is made \nwithout specifying the amount of cost estimate or specifying on ly the \nunit rate, the public entity may specify a lump sum amount for the bid \nsecurity in the bidding documents or prequalification documents and \nnotice on 78invitation to bids.  \n  (2) The validity period of the bid security referred to in  sub-\nrule (1) shall be for a minimum of  thirty days  beyond the validity \nperiod of the bid.  \n(3) If any bidder requests the public entity  inviting bid s to \nclarify whether the bid security issued by a particular commercial \nbank or financial institution is accep table to it  or not, such a public \nentity shall forthwith answer that request.  \n(4) The bid security issued by a foreign bank must be counter  \nguaranteed by a commercial bank within Nepal.  \n(5) The public entity  shall enter into the procurement \ncontract within  the validity period of the bid. If, for any reason, the \nprocurement contract cannot be entered into  within that time, the \npublic entity  shall send a letter to all the duly qualified  bidders to \nextend the validity period of bid s.  \n(5a) 79 The public entity shall send a letter to extend the validify \nperiod of bids pursuant to sub -rule (5) only if there exists  sufficient \nground justifying the extension of the validity period of bids upon \nmaking an analysis of the reason for extending such a period. In cases \nwhere the extension of the validity period of bids in the absence of \n \n77 Amended by the Sixth Amendment. \n78 Inserted by the Fourth Amendment. \n79 Inserted by the Sixth Amendment. \n61 \n \nsuch ground and reason for extending the validity period of bids  \nresults in any loss or damage because of failure to evaluate the bids in \ntime or to make a decision in tim e on the evaluation submitted, the \nemployee involved in such an act and officials of the evaluation \ncommittee shall be responsible for such loss or damage.   \n(6) The b idders may decide whether or not to extend the \nvalidity period as per the letter referred  to in s ub-rule (5). The bid \nsecurity of a bidder who does not extend the validity period of the bid \nshall not be liable to forfeit ure. Those bidders who extend the validity \nperiod of the bids shall submit the bid security by also getting the \nvalidity period  accordingly extended by the concerned bank. If a \nbidder fails to submit the bid security by so extending its validity \nperiod, the bidder  shall not be deemed to have extended the validity \nperiod of the bid. \n(6a) 80 A bidder who extends the val idity period of the bid \npursuant to sub -rule (6) shall not mention any additional condition \nwhich is contrary to the provisions  set forth in the bidding documents.  \n(7) In cases where the bid security of a bidder is forfeited, \nthe concerned public entity  shall make a claim within the validity \nperiod of the bid security before the bank issuing such a security for \npayment to the entity of the amount of the bid security furnished by \nsuch a bidder.  \n(8) Except for a bid security liable to forfeiture under the Act \nor this Regulation, the public entity  shall retur n the bid security to the \nconcerned bidder within three days of the conclusion of the \nprocurement contract.  \n \n80 Inserted by the Sixth Amendment. \n62", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Validity period of bid : A public entity  shall, in specifying  the validity", "content": "period of a bid or proposal of consultancy service s in the bidding \ndocuments or document s relating to request for proposal, specify t he \nperiod as follows:  \n(a) Ninety days f or a bid or proposal of consultancy \nservice with the cost estimate of up to on  one \nhundred million  rupees, \n(b) One hundred and twenty days f or a bid or proposal \nof a consultancy service with the cost estimate \nwhatsoever exceeding one hundred million rupees. \n54A. 81……..", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Necessary copies of bid to be submitted : In submitting a pre -", "content": "qualification proposal, bid or proposal for a consultancy service, a \nbidder or proponent shall submit such number of copies  thereof  as \nspecified in the pre -qualification document, bidding documents or \ndocuments relating to request for pro posal.  \n  82Provided that no bidder or proponent shall be deprived of \ncompetition for the reason th at he or she has failed to submit such \ncopies of the bid or proposal as required.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Register to be maintained and receipt to be given: (1) A public entity", "content": "shall separately maintain the records of sale and registration of the \npre-qualification document s, bidding documents or proposal s for \nconsultancy service.  \n(2) If a bidder or proponent personally or  through his or her \nagent tenders to submit a pre-qualification proposal, bid  or proposal \n \n81 Repealed by the Sixth Amendment. \n82 Inserted by the Fourth Amendment. \n63 \n \nfor a consultancy service, the public entity  shall receive it and give \nhim or her a receipt specif ying the  date and time.  \n(3) The public entity  shall mention the registration number \nregistered in the regist er pursuant to sub-rule ( 1) in the outer envelop e \nof the bid received pursuant to sub-rule (2).  \n(4) After the expiry of the time for sale and registration of \nbids, the chief of the concerned public entity  or officer employee \ndesignated by him  or her shall sign and close the register  referred to \nin sub-rule (1) .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Safety of bids: (1) The public entity  shall keep the bid s or the", "content": "proposal s for the consultancy service received pursuant to  this \nRegulation  safely so that they cannot be opened by any one prior to \nthe time for opening the bids.  \n(2) The public entity  shall keep the characteristics of the \nsample submitted along with the bid in such a confidential and safe \nmanner that it cannot be made public prior to opening the bids. \n58.83 Withdrawal or modification of bids: (1) In the case of an electronic \nbid or proposal, such a bid or proposal may be withdrawn or modified \nthrough electronic means of communication until the deadline for \nsubmission of such a bid or proposal.  \n  (2) If a bidder or proponent  who submits a bid or proposal \nother than an electronic bid or proposal referred to in sub -rule (1) \nwishes to withdraw or modify the bid or proposal submitted by him  or \nher, he  or she shall , in advance of twenty four  hours of the expiry of \nthe deadline specified for submission of bids or proposals,  submit an \napplication  for withdrawal or modification  thereof to the concerned \n \n83 Amended by the Fourth Amendment. \n64 \n \npublic entity  in a sealed envelope  by specify ing the following matters \nin the outer part of envelop e: \n(a) Subject  of the bid or proposal,  \n(b) Name and address of the public entity  or authority \ninviting bid s or proposal s,  \n(c) Matter that the bid or proposal for consultancy service is \namended or a request is made for withdrawal, and  \n(d) Matter t hat it has to  be opened only on the day and at the \ntime for opening bid s or proposal s. \n(3)84 Except where the bid already registered has to be \nmodified as a result of modification  made by the public entity itself, \nthe application referred to in sub -rule (2) cannot be made more than \nonce. \n(4) The application referred to in sub -rule (2) and the bid or \nproposal once modified  cannot be withdrawn.  \n(5) If a bidder or proponent is to withdraw or  modify the bid \nor proposal submitted by him or her, the bidder or proponent may \nwithdraw or modify  the bid or proposal only through the same \nmedium as th at of submission of the  bid or pro posal, and no \napplication submitted through different  medium  shall be entertained.  \n(6) If sealed envelop es referred to in  sub-rule (1) are \nreceived, the concerned public entity  shall keep such envelop es safely \npursuant to Rule 57.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "Opening of bids: (1) 85 The chief of public entity shall form a", "content": "committee under convenorship of the procurement official referred to \nin Rule 16 and consisting of at least two members to open the bids or \n \n84 Amended by the Sixth Amendment. \n85 Amended by the Fourth Amendment. \n65 \n \nproposals registered with the public entity, and cause such bids or \nproposals to be opened in presence of the bidders or their representatives \nat the pre-determined time.   \nProvided that nothing shall bar the opening of bids or proposals for \nthe sole reason that a bidder or his or her representative is not present.  \n(2) The public entity  shall, prior to opening bid s pursuant to \nsub-rule open(1), separate the envelop es of the bid s received after the \nexpiry of the deadline, the envelopes containing application s made for \nmodification or withdrawal of bid s and the envelopes of the bid s duly \nregistered and return unopened the bid s received after the expiry of the \ndeadline. In so returning, a report  of the procurement proceeding setting \nout, inter alia, the content, date and time of the same shall be prepared. \n(3) The public entity shall, after returning the bids pursuant to \nsub-rule (2), open the envelop e of every bid which is requested by the \nbidder for withdrawal and read  out the name of such a bidder and then \nopen all envelop es submitted for modification of bid s and read out the \ncontent inside such envelopes.  \n(4) The public entity shall, after reading out the content referred \nto in sub-rule (3), open every submitted bid one by one , and read out the \nfollowing contents of such a bid, prepare a record (Muchulka) thereof and \ncause such a record (Muchulka) to be signed by the concerned bidder or \nhis or her representative who is present:  \n(a) Name and address of the bidder,  \n(b)86 Quoted price of the bid,  \n(c) If any discount is offered to be given in the bid, \nstatement thereof,  \n \n86 Amended by the Fourth Amendment. \n66 \n \n(d) If any alternative to technical specifications is offered, \nthe quoted price thereof,  \n(e) Whether the bid security is accompanied or not, \n(f) If there is discrepancy between figure s and words, \ndetails of such discrepancy,  \n(g) 87 Whether the letter of bid and price schedule contains \nthe signature of the bidder or his or her representative \nor not,  \n(h) In the case of correction or obliteration of the bidding \ndocuments, the amount and statement written after \nsuch obliteration,  \n(i)88 Whether the  place of correction or obliteration \ncontains the signature of the bidder or his  or her \nrepresentative or not, \n(j) In the case of any remarks mentioned by the bidder in \nthe letter of bid , the content thereof , and the \ndescription of the rate, if any, invited, and  \n(k) Other necessary matters which the public entity \nconsiders appropriate.  \n(5) At the time of opening bid s pursuant to this Rule, no \ndecision may be made to accept or reject a bid. \n(6)89 In opening bids or proposals pursuant  to sub-rule (1), in the \ncase of the bids or proposals referred to in Rules 31E. and 31F.,  the outer \nenvelopes of the bids or proposals shall be opened  pursuant to Section \n \n87 Amended by the Fourth Amendment. \n88 Amended by the Fourth Amendment. \n89 Inserted by the Fourth Amendment. \n67 \n \n32 of the Act , financial proposals shall be segregated unopened and \nsafely retained pursuant to Rule 57.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Examination of completeness of bids: The evaluation committee shall,", "content": "in examining the completeness of a bid, examin e the following \nmatters , in addition to the matters set forth in sub -section (3) of \nSection 23 of the Act : \n(a) Whether the bidder is involved individually or as a \npartner of a joint venture in more than one bid s or \nnot,  \n(b) Whether the bidder is disqualified for participation \nin procurement proceed ing pursuant to sub-\nsections (2) and (3) of Section 63 of the Act or not,  \n(c) Whether the bid is submitted in the bidding \ndocuments sold by the concerned public entity  or \nsuch other bod y as designated by it or not,  \n(d) Whether the concerned  person, firm, organization \nor company has filled in and submitted the same \nbidding documents purchased by  himself or herself  \nor not.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Evaluation of bids: (1) Where, in an international bidding, the bidding", "content": "documents provide that the bid price may be expressed in various \ncurrencies, the evaluation and comparison of bid s shall be made by \nconverting the price of such bids into a single price according the \nexchange rate and currency as specified in the same document s.  \n(2) In evaluating and comparing a bi d, comparison shall be \nmade after fixing the quoted price by excluding the value added tax.  \n(3) Except as provided  for in the prevailing and this \nRegulation, information relating to the examination of bid s, the \n68 \n \ninformation asked or received from the bidde r in the course of such an \nexamination and the information relating to evaluation and \ncomparison shall not be provided to any bidder or any other person \nnot involved officially in the decision making process.  \n(4) The evaluation committee shall evaluate the bid s \nincluded for evaluation pursuant to sub-section (1) of Section 25 of \nthe Act in accordance with the criteria and method s set forth in the \nbidding documents of such a bid.  \n(5) While evaluating a bid pursuant to sub-rule (4), the \ntechnical, commercial and financial aspect s of the bid shall be \nevaluated.  \n(6) Bids having minor deviations  without any material \ndeviation from and serious effect on the scope, quality, \ncharacteristics,  conditions, performance or any other requirements set \nout in the bidding documents and acceptable to the public entity  shall \nbe deemed to be substantially responsive bids , and if, in evaluating \nsuch bid s, the cost  is affected in any way,  the evaluated price of the \nbid shall be drawn by ascertaining the price of such effect on an equal \nbasis and then by adjusting the same to the quoted price of the bid.  \n(7) The evaluated price of a bid drawn pursuant to sub-rules \n(6) and Rules 62, 63 and 64 shall be used only for the purpose of \ncomparing the bid and shall not be included in the price of \nprocurement contract.  \n(8) If any discrepancy as to price or any other matter is found \nin the original copy and the dupli cate copy of a bid, the price or \nmatter set out in the original copy shall be valid.  \n(9) The evaluation committee shall,  while fixing the price of \nminor deviation pursuant to sub-rule (6), fix on the basis of the cost \n69 \n \nestimate of the concerned work or pre vailing market price or interest \nrate. Where such cost estimate, prevailing market price  or interest rate \nis not definite, the price shall be determined on the basis of average \nprice of the same item stated in another substantially responsive bid.  \n(10) A bidder shall not be consulted in respect of the \njustification of the price to be determined pursuant to this Rule.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Evaluation of technical aspect of bids: (1) The evaluation committee", "content": "shall, while evaluating the technical aspect of a bid pursuant to sub-\nrule (5) of Rule 61, evaluate the following matters:  \n(a) Scope of the supply of goods, construction work or \nother service,  \n(b) Technical specifications an d operating and \nperformance characteristics of key goods, \nconstruction work or other service, and  \n(c) Warranty period.  \n(2) If, in evaluating a bid pursuant to sub-rule (1), any \ndiscrepancy is found  between the matters set out in the bidding \ndocuments and  the matter stated by the bidder in the bid, the \nevaluation committee shall note such a discrepancy as well.  \n(3) The price of the discrepancy referred to in s ub-rule (2) \nshall be fixed by computing in accordance with the criteria and \nmethod set out in the bidding documents.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Evaluation of financial  aspect of bids: (1) After evaluating the", "content": "technical aspect of a bid pursuant to Rule 62, t he evaluation \ncommitt ee shall, while evaluating the financial  aspect of such a bid \npursuant to sub-rule (5) of Rule 61 , evaluate the following matters:  \n70 \n \n(a) Period for the supply or completion of goods, \nconstruction work or other service,  \n(b) Conditions of payment,  \n(c) Liquidated damages to be paid by the bidder for \nnot completing the work in time and the bonus to  \nwhich the bidder is  entitled for completing the \nwork before time,  \n(d) Bidder’s liability towards warranty,  \n(e) Liability to be fulfilled by the bidder,  \n(f) If the bidder has added any other conditions to the \nproposed procurement contract, such conditions .  \n(2) If, in evaluating pursuant to sub-rule (1), a \ndiscrepancy is found between the matter stated in the biddi ng \ndocuments and the matter stated by the bidder in the bid, the \nevaluation committee shall note such discrepancy as well.  \n(3) The evaluation committee shall , while determining  \nprice of the discrepancy referred to in s ub-rule (2), fix the price \nof discrep ancy by computing as per the criteria and method set \nout in the bidding documents.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Evaluation of financial aspect of bids: (1) After the evaluation of", "content": "technical and commercial aspects of a bid pursuant to Rules 62 and \n63, financial asp ect of such a bid shall be evaluated.  \n(2) In evaluating  the financial aspect pursuant to s ub-rule \n(1), the evaluated price of the bid shall be fixed by determining the \nprice of the necessary matters out of the matters of tech nical and \nfinancial aspects, a nd of the following matters as well , as required,  in \n71 \n \naccordance with t he criteria and method specified in the bidding \ndocuments:  \n(a) Inland transport cost,  \n(b) Technical  characteristics.  \n(3) In evaluating the technical  characteristics  pursuant to \nclause (b) of s ub-rule (2), the evaluation committee shall evaluate \nonly the minimum rate, capacity or output where a bid is submitted  \nquoting the rate, capacity or output hi gher than the rate, capacity or  \noutput relating to procurement set forth in the bi dding documents.  \n(4) Where the bidding documents provide that preference \nshall be given to domestic goods and local construction entrepreneur s, \nthe evaluation committee shall, in evaluating the financial aspect s of a \nbid, fix the evaluated bid price by com puting the amount of  \npreference to be given to the domestic goods and local construction \nentrepreneur s and then adding such amount to the quoted price of a \nforeign bidder.  \n(5) The evaluation committee shall, in evaluatin g a bid, not \nconsider the spare par ts recommended by the bidder .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "Special evaluation of bids of construction w orks: (1) The evaluation", "content": "committee shall, in evaluating a bid of a construction work, evaluate \nthe following matters in addition to the matter s set out in Rules 62, 63 \nand 64: \n(a) Whether the work plan, performance schedule and \nmobilization time of the construction work conform to  \nthe bidding documents or not,  \n(b) Whether the per unit rate quoted by the bidder for the \nitem contained in the bill of quantities is reliable or not,   \n72 \n \n(c) Whether the quoted price is imbalanced or  not for the \nfollowing reasons:   \n(1) the bidder has  quoted unusual high rate for an item \nof the work to be executed  at the initial stage of the \nprocurement contract, or  \n(2) the bidder has  quoted unusual high rate for an y \nitem of the b ill of quantity believed by him or her \nto have been underestimated . \n(d)90 Whether the bidder has technical capacity to complete the \nconstruction work in conformity with the description \nreferred to in clause (n3) of sub -section (2) of Section 13 \nof the Act  or not.  \n(2) The evaluation committee shall examin e whether  or not  \nthe bidder has quoted low price in the circumstance referred to in \nclause (c) of sub -rule (1) or  has quoted  in such a manner that  he or she \ncannot complete the work satisfactorily or has quoted low price \nwhether or not upon wrongly understanding the scope  or technical \nspecifications of the construction work or has quoted high rate for the \nwork to be executed  at the preliminar y stage (front loading)  or 91in the \ncircumstance referred to in clause (c) of sub -rule (1) . Where low price \nhas been so quoted, the evaluation committee shall seek clarification \nalong with a rate analysis from such a bidder.  \n(3) The evaluation committee may recommend the public \nentity for acceptance of the  bid by taking from such a bidder \nadditional performance security equivalent to an amount of eight \npercent of his or her quoted bid price if the c larification sought \n \n90 Inserted by the Fourth Amendment. \n91 Inserted by the Sixth Amendment. \n73 \n \npursuant to s ub-rule (2) is found to be satisfactory and for rejection of \nsuch a bid if the clarification is not found to be satisfactory.  \n(4) The additional performa nce security taken pursuant to \nsub-rule (3) shall be returned after the payment of final bill s. \n(4a) 92 In evaluating the bids pursuant to Section 25 of the Act, \nthe evalua tion committee shall not count for additional work the \nbidder's technical and financial capacity  which is in use in any public \nentity or project to the extent it is necessary for such an entity or \nproject as set out in the bidding documents.  \n(4b) 93 For the purpose of sub -rule (4a) , the bidder shall obtain \nfrom a public entity or project a description as to the extent the \nbidder's financial and technical capacity out of the financial and \ntechnical capacity which is already in use in the public entity or \nproject required for such a public entity or project  and submit it along \nwith the bidding documents.  \n(4c) 94 The matter that a bidder can obtain a tender of only such \namount that does not exceed the amount to be set by a maximum of \nseven times of the average  annual turnover of the annual turnover of \nconstruction works in any three fiscal years with maximum turnover \nmade by the bidder shall be taken as a criterion for the bidder's \nqualification and evaluation. In so calculating the annual turnover of \nthree fis cal years, such calculation shall be made from within the \nimmediately preceding ten fiscal years.  \n(4d) 95 In calculating the amount to be set by seven times of the \namount of annual turnover pursuant so sub -rule (4c), it shall be \n \n92 Inserted by the Eighth Amendment. \n93 Inserted by the Eighth Amendment. \n94 Inserted by the Eighth Amendment. \n95 Inserted by the Eighth Amendment. \n74 \n \nascertained only upon subtracting the amount of annual liability for \nthe running contract.  \n(4e) 96 For the purpose of this Rule, the bidder shall make a self -\ndeclaration as to the financial and technical capacity  and submit its \ndescription together with the bidding documents. If  the description so \nsubmitted is found to be false, the bid submitted by the bidder shall be \nexcluded from the evaluation process and action shall be taken in \naccordance with the prevailing law.  \n(4f) 97 The assets  has to be more than the net liabilities of the \nbidder in the balance sheet of the last fiscal year, and the credit line \nfacility has to be available in such form as determined by the Public \nProcurement Monitoring Office.  \n(4g) 98 Notwithstanding anything contained in sub -rules (4a), \n(4b), (4c), (4d),  (4e) and (4f) , the bids in the process of evaluation \nprior to the commencement of this Rule shall be subject to the \nprovisions in force prior to the commencement of this Rule.  \n(5)99 ….. \n(6)100 ….. \n(7)101 ….. \n(8)102 ….. \n65A. 103 Special provision relating to evaluation : (1) The evaluation \ncommittee shall, in evaluating the proposals, ascertain whether a case \n \n96 Inserted by the Eighth Amendment. \n97 Inserted by the Eighth Amendment. \n98 Inserted by the Eighth Amendment. \n99 Deleted by the Seventh Amendment. \n100 Deleted by the Seventh Amendment. \n101 Deleted by the Seventh Amendment. \n102 Deleted by the Seventh Amendment. \n103 Amended by the Seventh Amendment. \n75 \n \non offence of corruption has been filed against any bidder, sealed \nquotation proponent, consultant, service provider, supplier, \nconstruction entrepreneur or other person, firm, organization or \ndirector of a company who submits a proposal singly or in joint \nventure, and if it appears that such a case has been filed, the \ncommittee shall w rite to the Government of Nepal, through the \nconcerned body.  \n  (2) If an intimation is received  pursuant to sub -rule (1), the \nGovernment of Nepal may give direction to exclude from the \nevaluation process the proposal submitted singly or in joint venture by \nsuch a bidder, sealed quotation proponent, consultant, service \nprovider, supplier, construction entrepreneur or other person, firm, \norganization or director  of a company . \n  (3) If direction is received pursuant to sub -rule (2), the \nevaluation committee shall exclude such a proposal from the \nevaluation process and evaluate t he remaining proposals.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "66", "title": "Report to be s ubmitted : The evaluation committee shall prepare a", "content": "report setting out  the detailed analysis of the examination and \nevaluation conducted  pursuant to Rules 60, 61, 62, 63, 64 and 65 and \nthe following matters , and shall submit the report to the public entity  \nwithin such period as specified by the chief of public entity, subject to \nRule 54A. : \n(a) Name and address of the bidder,  \n(b) Total quo ted price of the bidders and currency,  \n(c) If an error has been corrected pursuant to s ub-sections (8) \nand (9) of Section 23 of the Act, the total quoted price \nfixed after the correction of such error and the currency,  \n76 \n \n(d) If the  record (Muchulka ) prepared for the opening of a \nfinancial proposal mentions that the  bidder has offered to \nprovide any discount, the matter that the evaluation \ncommittee has adjusted the amount so offered for \ndiscount,  \n(e) Currency used for the comparison of bids pursuant to \nclause (f) of s ub-section (2) of Section 13 of the Act and \nthe amount fixed on the basis of  the exch ange rate of the  \ndate specified , \n(f) Grounds found from th e examination made pursuant to \nsub-sections (2), (3), (4), and (6) of Section 23 of the Act,  \n(g) Criteria and method  for the evaluation of the lowest \nevaluated substantia lly responsive bid pursuant to s ub-\nsection (8) of Section 25 of the Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "Authority to approve the b id: (1) The following authority shall have", "content": "the power to approve the bid of the following amount :  \n(a)104 For an amount not exceeding thirty million r upees, \ngazetted third class  chief of the office,  \n(b) 105 For an amount not exceeding  seventy million rupees, \ngazetted second class chief of the office,  \n(c) 106 For an amount not exceeding  one hundred fifty million \nrupees, gazetted first class chief of the office,  \n(d) 107 For an amount exceeding  one hundred fifty million \nrupees, the head of department.  \n \n104 Amended by the Fourth Amendment. \n105 Amended by the Fourth Amendment. \n106 Amended by the Fourth Amendment. \n107 Amended by the Fourth Amendment. \n77 \n \n(1a) 108 If the chief of any public entity is not allowed to approve \nthe bid pursuant to sub -rule (1), he or she shall cause it to be approved \nby one level higher authority.  \n(2) Notwithstan ding anything contained in sub -rule (1), the \nsecretary or administrative chief of a  constitutional organ or body, \nMinistr y, secretariat and other office  of similar  nature may approve a \nbid of any amount w hatsoever for procurement to be made  for his or \nher office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "68", "title": "Sample of g oods: (1) A bidder who is unsuccessful in the evaluation", "content": "of bid may , not later than seven days from the date of conclusion of \nthe procureme nt contract,  make a request in writing to the concerned \npublic entity  for returning the sample of the goods sub mitted by him \nor her. \n(2) Where a request is made pursuant to s ub-rule (1), the \npublic entity  shall return to the bidder the sample  of such goods  if it is \nnot destroyed during its testing, subject to the condition  that all the \nexpenses including its transportation and packaging expenses shall be \nborne by the bidder himself or herself.  \n(3) The public entity shall safely keep the sample of goods \nsubmitted by the bidder whose bid has been accepted , upon getting it \ncertified by the bid evaluation committee , for the purpose of \ncomparing it with the goods to be supplied.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -6", "title": "Chapter -6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "69", "title": "Terms of reference to be p repared : The p ublic entity  shall, in order to", "content": "procure  a consultancy service, prepare the terms of reference \ncontaining , inter alia,  the following matter s: \n \n108 Inserted by the Third Amendment. \n78 \n \n(a) Background  and objective of the work  to be \nperformed by the consultant,  \n(b) Scope of work of the consultant and the work to be \nperformed by him or her,  \n(c) Details of the study and basic data concerning the \nassignment , if any, available,  \n(d) If the consultant is required to transfer any \nknowledge or skill to the public entity , details \nthereof ,  \n(e) If training is to be provided, the number of the \nemployees to be trained,  \n(f) Functions and qua lifications of the key human \nresource  of the consult ant and the estimated time \nrequired for th e work to be performed by him or \nher, \n(f1) 109 Matter that the key human resource of the \nconsultant  as proposed  cannot be changed for any \nreason other than the reason that, following the \ncontract, he or she becomes so sick that he or she \ncannot work or meets an accidence or dies or \ncannot perform  such work for other reasonable \nreason,  \n(f2) 110 Matter that in the case where any consultant, in the \ncapacity of the key human resource, is involved as \nwhole timer in accordance with the contract, the \nbio-data of the same person cannot be so used in \n \n109 Inserted by the Sixth Amendment. \n110 Inserted by the Sixth Amendment. \n79 \n \nthe process of procurement of other consultancy \nservice that it overlaps with the schedule of work \nunder the contract, until the work under the \ncontract is completed,   \n(g) Time for the commencement and completion of the \nwork by the consultant,  \n(h) Details of the information, physical facilities and \nequipment to be provided by public entity  to the \nconsultant, and  \n(i) Details of the report, data, drawing and survey \nreport etc. to be submitted by the consultant.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Short list to be prepared by inviting open expression of intent: (1) A", "content": "public entity shall, in order t o procure a consultancy service  the cost \nof which exceeds two million 111 rupees, invite expression of intent  by \npublishing a notice pursuant to Section 30 of the Act.  \n(2) If a consultancy service of an amount exceeding  hundred  \nmillion 112 rupees is to be procured, generally an international \nexpression of intent  shall be invited.  \n(2a) 113 If a consultancy service the cost estimate of which  \nexceeds  two million rupees but not exceeding  hundred million rupees \nis to be procured in the circumstance other th an that referred to in \nSection 15 of the Act, expressi on of intent  shall be invited upon \nhaving co mpetition only between domestic proponents expressing \nsuch intent . \n \n111 Amended by the Fourth Amendment. \n112 Amended by the Fourth Amendment. \n113 Inserted by the Fourth Amendment. \n80 \n \n(3) The notice inviting expression of intent  pursuant to s ub-\nrules (1) and (2) shall set out the following matters:  \n(a) Name and address of the public entity ,  \n(b) General description  of the proposed work or  \nproject,  \n(c) Source of fun ding for the proposed work ,  \n(d) Qualifications of the  intent  expressing  proponent ,  \n(e) In the case of the intent  expressing proponent \nbeing a firm or company,  \n(1) Description ,  organization and \nemployees of the firm or company,  \n(2) If two or more firms or companies are \nto provide the consultancy servic e as a \ngroup, organization or joint venture, \nthe name, address, description of such \nfirms or companies,  and the  name of \nlead firm or company , \n(3) Description of the work of similar \nnature completed in the  last seven  \nyears 114 and their location,  \n(4) Bio-data of the key human resource  to \nbe involved in the proposed work,  \n(f) In the case of an ind ividual consultant, \ndescription  of the work of similar nature \n \n114  Amended by the Fourth Amendment. \n81 \n \ncompleted  in the  last four years 115 and their \nlocation and his or her bio-data,  \n(g) Estimated time required for the completion \nof the proposed work,  \n(h) Matter that proposal s relating to \nprocurement of consultancy service shall be \ninvited only from the short -listed persons , \nfirms, organization s or companies ,  \n(i) Documents to be submitted by the intent  \nexpressing proponent,  \n(j) Instruction s to prepare the expression of \nintent and deadline and place for the \nsubmission of expression of intent , and  \n(k) Address for contact  with the public entity  \nand contact person.  \n(4) The public entity  shall, in inviting international \nexpression of intent , obtain approval from one level higher authority.  \n(5)116 The public entity  shall select a consultant capable of \nproviding such consultancy service aft er evaluating, inter alia , the \nqualification, experience and capacity of those who have submitted \nexpression of intent  pursuant to this Rule , and also ascertaining the \ncriteria for evaluation of their qualification, experience and capacity .  \n \nProvided that no accepted criteria for  evaluation may be \nchanged and evaluation be made after the submission of the \nexpression of intent . \n \n115  Amended by the Fourth Amendment. \n116 Amended by the Fourth Amendment. \n82 \n \n(6) The public entity  shall, while selecting an international \nexpression of intent , select a firm  or company from various countries , \nbackground  and a local ….. 117 firm or company.  \n(7) The name of a reputed  consultant who has not submitted \nexpression of intent  pursuant to the notice referred to in s ub-rule (1) \nmay be  included in the short -list upon making contact with him or \nher. \n(8) If, in selecting intent expressing proponents pursuant to \nthis Rule or including the name pursuant to s ub-rule (7) , at least three \nintent expressing proponents cannot be selected, the public entity  \nshall invite expression of intent by re-publishing a notice.  \n(9) If at least three intent  expressing proponents cannot  be \nselected even after publishing the notice for the second time, the  list \nmay be prepared including only the intent  expres sing proponents who \nhave been selected.  \n(10) The public entity  shall give information as to  the list \nprepared pursuant to this Rule to all the proponents who have \nsubmitted expression of intent. \n(11) 118  If, in the case of procurement of a consultancy \nservice pursuant to sub -rule (2), a foreign intent  expressing proponent \nmakes a joint venture with a domestic consultant person, firm or \ncompany, preference may be given to such a foreign proponent.  \nProvided  that, in so maintaining  a joint venture , the joint \nventure  cannot be  so maintained as to be overlapping.  \n \n117 Deleted by the Fourth Amendment. \n118 Inserted by the Fourth Amendment. \n83 \n \n(12) 119 In evaluating the capacity pursuant to sub -rule (5), it \nshall be so evaluated on the basis of the turnover that it does not \nexceed one hundred fifty percent of the total cost estimate of the \nconsultancy service.  \n(13) 120 In selecting the intent expressing pr oponent pursuant to \nsub-rule (5), such selection shall be so made that the work is \ncompleted within the period referred to in Rule 54A.  \n(14) 121 If, with respect to the selection of the intent expressing \nproponent pursuant to this Rule, any intent expressing proponent \nrequest s the public entity for the marks obtained by him or her and the \nreason why he or she could not be  included in such selection, it shall, \nnot later than five days, give the intent expressing proponent \ninformation as to the marks obtained by  him or her and the reason \nwhy he or she  could not be selected.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "71", "title": "Invitation to p roposal s: (1) Once a short list has been prepared", "content": "pursuant to Rule 70, the p ublic entity  shall invite proposal s from the \nintent expressing proponents included in that list by sending them the \ndocuments relating to proposal by post, courier or in person or \nthrough electronic communication means, giving  the time of at least \nfifteen days in the case of procurement of which cost estimate does \nnot exceed two million rupees and at least thirty days in the case of \nprocurement of which cost estimate exceeds the said amount. 122 No \nfee shall be charged for the documents relating to proposal  to be so \nsent.  \n \n119 Inserted by the Fourth Amendment. \n120 Inserted by the Fourth Amendment. \n121 Inserted by the Fourth Amendment. \n122 Amended by the Fourth Amendment. \n84 \n \n(2) The public entity  shall set out  the following matters , in \naddition to the matters referred to in Section 31 of the Act , in the \ndocuments relating to proposal:  \n(a) Request for proposal,  \n(b) Matter that the key human resource  proposed by \nthe proponen t must have certified that his or her \nrecent bio -data is true and complete,  \n(c) Matter that the financial proposal shall be opened \nonly after evaluating the technical proposal , \n(d) Pass marks to be secured by the propo nent in the \ntechnical proposal,  \n(e) Whether the proponent can propose his or her separate \nwork plan and human resource  for the concerned work or \nnot,  \n(f) Whether the proponent can make comment s on the terms \nof reference or not, and  \n(g) Source of funding required  for carrying out the proposed \nwork.  \n(3) The public entity  shall state the weightage marks  for evaluation \nof proposal s in the d ocuments relating to proposal.  \n(4) While stating  the weightage marks  pursuant to s ub-rule (3),  it \nshall be stated as follows:  \n(a) If the proposal is to be selected on the basis of  the quality \nand cost  method, weightage marks  shall be so determined \naccording to the nature and complexity of the work that \nthe total weightage marks of the technical and financial \nproposal is one hundred and out of such total weightage \n85 \n \nmarks, the total weightage marks of the technical \nproposal is in the range of seventy to ninety and the that \nof the financial proposal is in the range of ten to thirty,  \n(b) If the proposal is to be selected on the basis of the quality \nmethod, fixed budget method and the least cost method, \nthe total weightage marks of the technical proposal shall \nbe so determined as to be one hundred.  \n(5) While inviting proposal s to select a cons ultant by the fixed \nbudget method, the availabl e budget shall be  mentioned in the proposal.  \n(6) While mentioning  the weightage marks for the selection of a \nconsultant in the documents relating to proposal, the public entity  shall so \nmention appropriate marks , according to the nature  and complexity of the \nwork, that the marks do not exceed the following marks:  \n(a) Proponent's experience of \nspecific work  \nUp to twenty -five \npercent 123 of the total \nmarks \n(b) Method of performance and \nresponsiveness to the terms of \nreference  \nTwenty to thirty -five \npercent 124of the total \nmarks \n(c) Qualification and experience of \nkey human resource  \nThirty to sixty percent of \nthe total marks  \n(d) Transfer of technology or \ntraining  \nUp to ten percent of the \ntotal marks  \n(e) Participation of domestic Up to ten percent of the \n \n123 Amended by the Fourth Amendment. \n124 Amended by the Fourth Amendment. \n86 \n \nhuman resource  total marks  \n Total Total marks 100  \n(7) The weightage marks set forth in clause (e) of s ub-rule \n(6) shall not be applicable to a domestic  proposal.  \n(8) All the evaluation criteria set forth in s ub-rule (6) shall \nbe divided into three sub -criteria and the marks therefor shall also be \ndetermined.  \n(9) In mentioning the weightage marks pursuant  to s ub-rule \n(3), the pass marks shall also be mentioned .  \n(10) 125 In mentioning the weightage marks for the selection of a \nconsultant in the documents relating to proposal of procurement of a \nconsultancy service, it shall be so mentioned the human resource that \nis work in hand in any consultant person, firm or company shall not \nbe calculated to that extent in the evaluation of the latest proposal.  \n(11) 126 In evaluating proposals pursuant to this Rule, such an \nevaluation shall be made only on the basi s of the distribution made \npursuant to sub -rule (8) and weightage marks for the same.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "72", "title": "Consultancy s ervice may be procured  by inviting p roposal s from", "content": "consultants in the standing l ist: (1) A public entity  may procure a \nconsultan cy service the cost of which is  less than two million \nrupees 127 by inviting written technical and financial proposal s from \nthe consultants included in the  standi ng list referred to in Section 6A. \nof the Act .128  \n \n125 Inserted by the Fourth Amendment. \n126 Inserted by the Fourth Amendment. \n127 Amended by the Fifth Amendment. \n128 Amended by the Fourth Amendment. \n87 \n \n(2) While inviting proposal s pursuant to s ub-rule (1), \ntechnical and financial proposal s shall be invited in separate \nenvelop es, by sending the documents relating to proposal to six, as far \nas possible, and at least  three consultants.  \n(3) The method for evaluation of the proposal s referred to in \nsub-rule (2) shall be selected according to the  quality and cost \nmethod.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "73", "title": "Matters to be specified in instructions to prepare p roposal s: The", "content": "public entity  shall specify the following matters in the instructions to \nbe given to prepare proposal s pursuant to clause (c) of s ub-section (2) \nof Section 31 of the Act:  \n(a) Format of technical and financial proposal s,  \n(b) Method of preparing and submitting technical and \nfinancial proposal s,  \n(c) Number of the stages at which the work is to be \ncompleted and whether additional work  can be assigned \nor not,  \n(d) If the proponent needs to obtain any information as to  the \ndocuments relating to proposal, the manner  of obtaining \nsuch information,  \n(e) Matter of whether the consultant can sub -contract a ny \nportion of the proposed work or not,  \n(f) Information as to the notice, service  or equipment to be \nprovided by the public entity ,  \n(g) Matter whether a pre-proposal meeting  of proponents  will \nbe held  or not,  \n(h) Validity period of the proposal,  \n88 \n \n(i) Matter that if the public entity  consider s that the award to \nthe consultancy firm or person  or organization affiliated \nwith it of any work relating to the sup ply of goods, \nconstruction work , other service  or consultancy service to \nbe created under the proposed procurement action may \nconstitute a conflict of interest with the proposed \nconsultancy service, such a work can not be awarded to \nsuch a proponent or person ,  \n(j) Information about the tax to b e paid by the proponent and \nhis or her human resource and other competent body to \nbe contacted by the proponent if he or she wants to obtain \nfurther information as to tax or a ny other matters,  \n(k) Language of the proposal,  \n(l) Procedure for modification of the  documents relating to \nthe proposal by the public entity ,  \n(m) Method of submitting proposal s,  \n(n) Method of opening proposal s,  \n(o) Condition relating to  confidentiali ty.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "Method of selecting p roposal : (1) A public entity  may procure a", "content": "consultancy service for the followi ng work  by selecting the quality \nmethod:  \n(a) A work of such nature that expected work from the \nconsultant  cannot be clearly ascertained  like economic or \nsectoral study of the country, multi -sector feasibility  \nstudy, design of a mechanism for  managing and \ndisposing hazardous wast es, design of urban master plan, \nfinancial sector reform  and in respect of which t he public \nentity expects a research proposal from the consultant,  \n89 \n \n(b) A work of a type that requires higher  expertise and that \ncauses serious and long -term impact s in the future, such \nas feasibility study or structural engineering design of \nlarge dams or m ajor infrastructure building or policy \nstudies of national importance, management study of \nlarge governmental bodies,  \n(c) A work  of a type the service charge  of which depends \nupon the quality of work or that may be performed \nsubstantially in different way s by each ind ividual or \norganization and cost of the competitive proposal of \nwhich cannot be compared, such as management \nconsultancy or sectoral and policy studies.  \n(2) Approval of the head of department  shall be \nobtained  to select the quality method pursuant to s ub-rule (1).  \n(3) The least cost method may be selected for the work \nwhich has already been well practiced, is of regular nature and \nrequires  low cost, such as auditing, general engineering design \nand procurement agen t.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Manner of opening p roposal s: (1) A public entity  shall, while opening", "content": "proposal s pursuant to Section 32 of the Act, open them in the \npresence of proponent s or their representative s.  \nProvided that it shall not bar the opening of a proposal for the \nreason that the proponent or his or  her representative is not present.  \n(2) Prior to opening proposals pursuant to s ub-rule (1), the \npublic entity  shall segregate  the envelop es of the proposal s received \nafter the deadline and those  of the proposal s duly registered , and shall  \nreturn unopened the proposal s received after the deadline to the \n90 \n \nconcerned proponents. The public entity  shall mention the matter of \nsuch return, date and time in the report of procurement action.  \n(3) After returning the proposal s pursuant to sub -rule (2), the \npublic entity  shall open  the outer envelop e of every proposal duly \nregistered respectively , and the  envelop e of technical proposal \ncontained in that envelop e and read out the following matters and then \nprepare a  record  (Muchulka ) thereof:  \n(a) Name and address of the proponent,  \n(b) Whether the proposal is signed by the proponent or not,  \n(c) In the event of any correction or  overwriting  in the \ndocuments relating to proposal, whether the proponent or \nhis or her representative has signed such correction and \noverwriting or not,  \n(d) Such o ther necessary matters that the public entity deems \nappropriate .  \n(4) The public entity  shall cause the  record  (Muchulka ) \nreferred to in s ub-rule (3) to be  signed by the proponent or his \nor her agent present.  \n(5) The public entity  shall send as soon as possible the \ntechnic al proposals opened pursuant to s ub-rule (4) to the \nevaluation committee.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "Manner of e valuatin g technical p roposal s: (1) While evaluating a", "content": "technical proposal, each member of the evaluation committee shall \nseparately evaluate  it in accordance with the criteria set forth in s ub-\nrule (6) of Rule 71 and fix the marks obtained by the  proponent.  \n91 \n \n(1a) 129 The evaluation committee may form a three -\nmember sub -committee consisting of concerned experts to render \nassistance in the evaluation of technical proposals.  \n(2) After fixing the marks pursuant to s ub-rule (1), t he \nevaluation committee shall find out the average marks obtained by \nsuch a proposal , upon  computing the marks given by each member of \nthe committee.  \n(3) Upon the evaluation under s ub-rules (1) and (2), the \nevaluation committee shall prepare a list of the  proponents who have \nobtained the pass marks referred to in s ub-rule (9) of Rule 71.  \n(4) The list referred to in s ub-rule (3) shall be prepared in \ndescending order starting from the proponent securing the highest \nmarks, respectively .  \n(5) The evaluation committee shall not open the financial \nproposal s until the evaluation of the technical proposal s is completed.  \n(6) The financial proposal s of only the proponent s included \nin the list referred to in s ub-rule (3) shall be opened pursuant to Rule \n79. \n(7) The proposal s of the proponent s who are not included in  \nthe list referred to in s ub-rule (3) shall be returned unopened to the \nconcerned proponent s.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "77", "title": "Evaluation report to be p repared : (1) The evaluation committee shall,", "content": "upon completing the evaluation referred to in Rule 76, prepare a \nreport as to the quality of each  proposal.  \n(2) The report referred to in s ub-rule (1) shall set out, inter \nalia, the following matters:   \n \n129 Inserted by the Fourth Amendment. \n92 \n \n(a) Name and ad dress of the proponent,  \n(b) Whether it has been signed by the proponent or his \nor her authorized representative or not,  \n(c) Whether the documents establishing that  the \nproponent is qualified under law to submit the \nproposal have been  submitted or not,  \n(d) Where the joint venture agreement is requir ed, \nwhether such an agreement has been  submitted or \nnot,  \n(e) Whether or not the proposal is complete in \nconformity with  the instruction s to proponent s \ngiven in the documents relating to proposal, and  \n(f) Relative strength s, weakness es and the result of \nevaluation of each proposal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "78", "title": "Notice to be given to the p roponent s selected from e valuat ion of", "content": "technical proposal s: (1) A public entity  shall give  a notice containing \nthe place, date and time for opening financial proposal s to the \nproponent s included in  the list referred to in s ub-rule (3) of Rule 76 to \nappear at that  place and time . \n(2) In giving a notice to the proponent s to appear pursuant to \nsub-rule (1), a period of at least seven days shall be given in the case \nof a domestic  proposal and of at least fifteen days , in the  case of an \ninternational proposal.  \n(3) The financial proposal of the proponent failing to obtain \nthe pass  marks shall be returned to him or her, accompanied by  a \nnotice setting out the reason why his or her technical proposal has not \nbeen selected.  \n93 \n \n(4)130 In selecting proponents pursuant to this Regulation, if \nany proponent requests the public entity for the provision of the marks \nobtained by him or her and the reason why he or she could not be \nselected, it shall provide the marks obtained by him or her  and the \nreason for not being selected to the proponent not later than five days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "79", "title": "To open f inancial proposals: (1) The evaluation committee shall open", "content": "the envelop es of financial proposal s in the presence of the proponent s \nor their representatives . \nProvided that nothing shall bar the opening of financial \nproposal s for the reason that any proponent or his or her \nrepresentative  is not present .  \n(2) After opening the envelop e of the financial proposal \npursuant to s ub-rule (1), the eva luation committee shall read out the \nname of the proponent, the marks obtained in the technical proposal \nand the  service charge proposed by him or her in the financi al \nproposal and prepare the  record  (Muchulka ) as follows:   \n(a) Name and address of the proponent,  \n(b) Proposed service charge,  \n(c) If any offer is made to discount the proposed \nservice charge, details t hereof,  \n(d) Description of the discrepancies, if any, between \nfigures and words,  \n(e) Whether  the financial proposal has been signed by \nthe proponent or his or her representative  or not,  \n(f) If any matter or content of the financial proposal is  \noverwritten, whether the overwriting  has been \n \n130 Inserted by the Fourth Amendment. \n94 \n \nsigned by the proponent or his or her representative \nor not and the amount and content overwritten ,  \n(g) Such o ther necessary matters as the public entity \nconsiders appropriate .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "80", "title": "Evaluation of financial p roposal s: (1) Except as otherwise mentioned", "content": "in the documents relating to proposal , for the purpose of evaluation of \na financial proposal, the service charges  of the consultant specified in \nthe proposal shall be deemed to  include  reimbursable expense s such \nas tax , other than value added tax,  leviable on  the consultant pursuant \nto the prevailing law, consultant's travel, translation of the concerned \ndocuments, report printing or overhead cost.  \n(2) If, in evaluating the financial proposal of each proponent, \nthe evaluation committee finds any arithmetical error in the proposal, \nthe public entity  may correct such an error , and if, in so correcting the \nerror, there is any discrepancy between  the unit rate and the total \namount, the unit rate shall prevail and the total amount shall be \ncorrected as per the same rate. Where the error is so corrected, \ninformation thereof shall be given to the concerned proponent.  \n(3) If any discrepancy is found between the  number and \nwords in the  amount quoted by the proponent in the financial \nproposal,  the amount quoted in words shall prevail.  \n(4) If the  record (Muchulka ) of opening financial proposal \nsets out  that the proponent has offered to provide any discount to the \nproposed quoted price, the evaluation commi ttee shall adjust the \namount proposed to be so discounted.  \n(5) After the evaluation referred to in s ub-rules (2), (3) and \n(4), a list of the fixed quoted price of every proponent  shall be \nprepared.  \n95", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "81", "title": "Selection of p roponent : (1) If the quality and cost method is applied to", "content": "select a proposal, the evaluation committee shal l select the successful  \nproponent by evaluating the tec hnical and financial proposals as \nfollows:  \n(a) The obtained net marks of the technical proposal  of the \nproponent to be evaluated  shall be the quotient to be \nfound out by dividing by one hundred  the product \nobtained from multiplying the score of the technical \nproposal by the weightage marks allocated fo r the \ntechnical proposal . \n(b) The obtained net m arks of the  financial proposal shall be \nthe quotient marks to be found out by dividing by the \nquoted price of the proponent to be evaluated the product \nobtained from multiplying the lowest quoted price out of  \nthe proposal s successful from the evaluation of the \ntechnical proposal s by the weightage marks assigned for \nthe financial proposal.  \n(c) A proponent  who obtains the highest marks in making \njoint evaluation after adding the net score of the technical \nand financial proposals shall be considered to be \nsuccessful and he or she shall be selected.  \nExample :  \n(1) Total weightage marks allocated for the technical \nproposal =80  \nMarks obtained in the technical proposal by \nproponent s A, B  and C who have obtained the \nspecified pass marks:  \nA = 90 \n96 \n \nB = 85  \nC = 80  \nMethod of computing the marks to be obtained in  \nthe technical proposal on the basis of the said \nmarks:  \nA = 90 x 80  = 72 \n  100 \nB = 85 x 80  = 68 \n  100 \nC = 80 x 80  = 64 \n  100 \n(2) The weightage of marks allocated for the financial \nproposal=20  \nThe amount quoted in the financial proposal by \nthe bid ders A, B and C  who have passed the \ntechnical proposal:  \nA = 4,50, 000.00  \nB = 4, 30 000.00  \nC= 4,20 000.00  \nTherefore, the lowest quoted amount = 4, 20, \n000.00  \nThe method for computing the marks to be \nobtained by the financial proposal on the basis of \nthe said marks:  \nA = 4,20, 000 x 20  = 18.66  \n4, 50,000  \nB = 4,20, 000 x 20  = 19.53  \n97 \n \n4, 30,000  \nC = 4,20, 000 x 20  = 20.00  \n4, 20,000      \n(3) Details of the total marks to be obtained from the \njoint evaluation of the technical and financial \nproposals:  \nProponent  \n(4)  \nNet \nscore of \nthe \ntechnical \nproposal  \nNet \nscore of \nthe \nfinancial \nproposal  \nTotal \nmarks \nRemarks  \nA 72 18.66 90.66 Proponent \n'A' who \nhas \nscored the \nhighest \nmarks \nshall be \nselected.  \nB 68 19.53 87.53  \nC 64 20.00 84  \n(2) If the quality  method is applied to select the  proposal, the \nevaluation committee shall select only the proponent who has \nobtained the highest marks in the technical prop osal pursuant to \nclause (b) of s ub-section (1) of Section 35 of the Act.  \n(3) If the fixed budget method is applied to select  the \nproposal, the evaluation committee shall cancel the proposal with cost \nexceeding the ceiling of such bu dget pursu ant to clause (c) of s ub-\nsection (1) of Section 35 of the Act and select the proposal of the \n98 \n \nproponent who has scored the highest marks in the technical proposal \nsubject to  such ceiling.  \n(4) If the least co st method is applied to select the  proposal, \nthe evaluation committee shall select the proposal with the lowest cost \nout of the proponents who have scored minimum marks specified for \nbeing successful in the technical prop osal pursuant to clause (d) of \nsub-section (1) of Section 35 of the Act.  \n(5) If it is required to negotiate  with the proponent selecte d \npursuant to this Rule, the pubic entity shall, not later than seven days \nof the selection of the proposal ,131 give a notice containing the date, \ntime and place to such a proponent for holding negotiations.  \n(6)132 In inviting the proponent for negotiation pursuant to sub -\nrule (5), the time -limit of seven days shall be given in the case of a \nnational proposal and that of fifteen days shall be given in the case of \nan international proposal.  \n(7)133 The proponent who makes contract pursuant to Section  \n38 of the Act shall submit professional liability insurance covering the \ntotal price of the contract and payable unconditionally to the public \nentity, not later than three days of the signature of the contract.  \n(8)134 If the proponent who makes contract pur suant to this \nRegulation fails to submit the professional liability insurance within \nthe time -limit referred to in sub -rule (7), the public entity shall \nterminate such a procurement contract and make recommendation to \nthe concerned body for blacklisting su ch a proponent.  \n \n131 Inserted by the Fourth Amendment. \n132 Inserted by the Fourth Amendment. \n133 Inserted by the Fourth Amendment. \n134 Inserted by the Fourth Amendment. \n99 \n \n81A. 135 Authority to approve proposal relating to consultancy service : (1) 136 \nThe following authority shall have the power to approve the following \nproposal relating to consultancy service:  \n(a) For an amount not exceeding  one million rupees, gazetted \nthird class chief of the office,  \n(b)  For an amount not exceeding  five million rupees, \ngazetted second class chief of the office,  \n(c)  For an amount not exceeding  thirty  million rupees, \ngazetted first class chief of the office,  \n(d)  For an amount exceeding  thirty million rupees, the head \nof department.  \n(2) If the chief of any public entity is not allowed to approve \nthe proposal relating to consultancy service  pursuant to sub -rule (1), \nhe or she shall cause it to be approved by one level higher authority.  \n(3) Notwithstanding anything contained in sub -rule (1), the \nsecretary or administrative chief of a constitutional organ or body, \nMinistry, secretariat and other office of similar nature may approve \nthe proposal of any amount whatsoe ver for procurement to be made \nfor his or her office.  \n82.137 Procurement through direct negotiation : (1) If it is required to acquire \na service only for such matters as a training, workshop and seminar \nwhich are useful and necessary for the public entity , such service  may \nbe so procured through  direct negotiation  by the chief of the public \nentity himself or herself in the case of a service the cost of which does \nnot exceed five hundred thousand r upees, and with the appro val of \n \n135 Inserted by the Third Amendment. \n136 Amended by the Fourth Amendment. \n137 Amended by the Sixth Amendment. \n100 \n \none level higher authority  in the case of a service the cost of which \nexceeds such an amount but not exceed two million rupees  that it is \nnot contrary to Section 37 of  the Act.  \n  (2) In the case where it is required to procure a consultancy \nservice  the cost of which does not exceed  two million rupees with the \napproval of one level higher authority for the work referred to in sub -\nrule (1), procurement shall be made by ob taining at least three \nproposals and holding direct negotiations with the proponent whose \nproposal is the most useful and offers the lowest price, for the purpose \nof ascertaining, inter alia , the quality and price.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "83", "title": "Other m ethod: A consultant may be appointed on the basis of", "content": "expertise and 138 qualifica tion in the following circumstance:  \n(a) If expertise  of high standard  is required to carry out a \nwork, or  \n(b) If the consultancy service is required for a short period or \nif there is less time to appoint a  consultant, or  \n(c) If only a few consultants are qualified to complete the \nrequired work,  \n(d) If appointment of consultant takes long time but t here is \ninadequate time for it.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -7", "title": "Chapter -7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "84", "title": "Provisions Relating to sealed q uotation s: (1) 139 The public entity may,", "content": "as per the approved program and procurement plan, procure goods, \nconstruction work or  any service  the cost estimate of which does not \n \n138 Amended by the Fourth Amendment. \n139 Amended by the Fourth Amendment. \n101 \n \nexceed two million r upees by inviting  sealed quotation s pu rsuant to \nSection 40 of the Act . \n  (1a) 140 Notwithstanding anything contained elsewhere in this \nRegulation, procurement of X-ray, ECG, medicinal goods, medical \nequipment  used for diagnosis and treatment of a disease, the cost of \nwhich does not exceed  five million rupees may be made by inviting \nsealed quotations.  \n(2) The public entity  shall specify the following matters , in \naddition to the matters set out in s ub-sectio n (2 ) of Section 14 of the \nAct, in the sealed quotation form : \n(a) Details of the goods to  be supplied, construction \nwork to be completed or the service to be provided,  \n(b) Qualification of the sealed quotation bidder  (except \nin the case of procurement of construction  work),  \n(c) Performance security, if so required,  \n(d) Validity period of the sealed quotation,  \n(e) Statement that the sealed quotation form shall be \nduly signed by the sealed quotation bidder ,  \n(f) Method of evaluation of the sealed quotation,  \n(g) Warranty related liability in the case of goods and \nliability covering the defect liability  period  in the \ncase of a construction work.  \n(3) Once the form is prepared  pursuant to s ub-rule (2), the \npublic entity  shall, in order to invite sealed quotation s, publish a \nnotice pursuan t to s ub-section (3) of Section 40 of the Act , and such a \nnotice shall  contain the following matters:  \n \n140 Inserted by the Fourth Amendment. \n102 \n \n(a) Place where the sealed quotation form is available and  \nthe charge applicable for it,  \n(b) If security is required, the type, amount and period \nthereof,  \n(c) Manner for sending the sealed quotation,  \n(d) Name and address of the office to which or the official to \nwhom the sealed quotation shall be se nt,  \n(e) Last date and time  for submission of the sealed quotation,  \n(f) Date, place and time for  opening the sealed quotation,  \n(g) Other necessary matters.  \n(3a) 141 If, upon publication of a notice pursuant to sub -rule (3), \nless than three sealed quotations are submitted or no sealed quotation \nis submitted, a notice shall be published for the second time pursuant \nto that sub -rule, without mentioning any matter with respect thereto.  \n(3b) 142 If, even upon publication of a notice for the second tie \npursuant to sub -rue (3a), a required number of sealed quotations are \nnot submitted, nothing shall bar the approving of a sealed quotation, \nout of the submitted sealed quotations.  \n(4) A person, firm, organization or company wishing to \nsubmit a  sealed quotation shall purchase the quotation form from the \nconcerned public entity  upon payment of one thousand rupees 143 and \nsubmit the sealed quotation in the same form.  \n(5) The quotation form referred to in s ub-rule (4) has to  bear \nthe signature of the chief of the concerned public entity  or employee \ndesignated by him or her and the seal of the office.  \n \n141 Inserted by the Third Amendment. \n142 Inserted by the Third Amendment. \n143 Amended by the Fourth Amendment. \n103 \n \n(6)144 In requiring the security for the sealed quotation, the \npublic entity shall, subject to the ceiling of two to three percen t \namount of the approved cost estimate, specify a certain amount and \nset out the amount of security in the notice inviting sealed quotations. \nA person , firm, organization or company who submits  the sealed \nquotation shall submit , along with the sealed quota tion, such security \nin cash or in the form of such a bank guarantee with the validity \nperiod of seventy -five days  as issued by a commercial bank  \n(7) The validity period of the  sealed quotati on shall be of \nforty-five days.  \n(8) The public entity  shall open the sealed quotation form s \nimmediately after the expiry of the deadline for submission of  sealed \nquotation s at the place specified in the notice inviting sealed \nquotation s in the presence of the sealed q uotation bidders  or their \nrepresentatives , as far as possible.  \n(9) The evaluation committee shall examine and  evaluate the \nsealed quotation s. \n(9a) 145 Only in the case where a minimum of three sealed \nquotations, out of the sealed quotations submi tted pursuant to the \nnotice for the first time, become substantially responsive, the \nevaluation committee shall select the quotation with the lowest quoted \nprice for acceptance.  \n(10) The public entity  shall, within fifteen days of the date of \nthe opening of sealed quotations pursuant to sub -rule (8), accept th e \nsealed quotation pursuant to s ub-section (5) of Section 40 of the Act \nand give a notice thereof to all sealed quotation  bidders . \n \n144 Amended by the Third Amendment. \n145 Inserted by the Sixth Amendment. \n104 \n \n(11) The public entity  shall, within seven days of the \nacceptance of the sealed quotation pursuant to sub -rule (10 )146, give a \nnotice to the c oncerned sealed quotation bidder to appear to sign the \nprocurement contract.  \n(12) 147 The sealed quotation bidder receiving the notice referred \nto in  sub-rule (11 ) shall sign the  procurement contract within seven \ndays of the date of receipt of such a notice, upon furnishing the \nperformance security referred to in Rule 110 .  \n(13) The security furnished by the sealed qu otation bidder  \npursuant to s ub-rule (6) shall be forfeited in  any of  the following \ncircumstances:  \n(a) If the selected sealed quotation bidder does not sign the \nprocurement contract,  \n(b) If he or she fails to furnish  the performance security \nspecified in the sealed quotation form within the time for \nsigning the  procurement contract,  \n(c) If he or she does an act contrary to the conduct referred \nto in Section 62 of the Act.  \n(14) Other procedure s relating to  the sealed quotation s shall \nbe as pe r the provision s set out  in Chapter -5.148", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "85", "title": "Provision s relating to  direct p rocurement : (1) 149 In making", "content": "procurement pursuant to clause (a) of sub -section (1) of Section 41 of \nthe Act, direct procurement may be made not exceeding the following \nceiling, subject to sub -rule (4):  \n \n146 Amended by the Third Amendment. \n147 Amended by the Fourth Amendment. \n148 Amended by the Sixth Amendment. \n149 Amended by the Third Amendment. \n105 \n \n(a)150 Construction work , goods or consultancy service the cost \nestimate of which does not exceed five hundred thousand \nrupees, \n(b) …….. 151 \n(1a) 152 Notwithstanding anything contained elsewhere in this \nRegulation, medicinal goods the price of which does not exceed two \nmillion rupees or goods the price of which does not exceed one \nmillion five hundred thousand rupees which have been manufactured \nin Nepa l may be directly purchased at the selling price specified by \nthe manufacturer of such goods by publishing a notice in a newspaper \nof national circulation. In so making direct procurement, goods with \nNepal Standard Marks shall be procured to the extent ava ilable.  \nProvided that if there is only one pharmaceutical company \nprequalified by the World Health Organization to manufacture any \npharmaceutical product , such a pharmaceutical product may be \nprocured through direct negotiation, irrespective of the amount of \nsuch product.  \n(1b) 153 Notwithstanding anything contained in sub -rules (1) and \n(1a), no procurement exceeding the ceiling set out in those sub -rules \nmay be made directly from the same person, firm, company or \norganization at one time or several time s in one fiscal year.  \n(1c) 154 Notwithstanding anything contained elsewhere in this \nRegulation, direct procurement of up to five million rupees may be \nmade for hospitality and hotel accommodation for any very important \nperson or important person of the govern ment of a foreign country or \n \n150 Amended by the Fourth Amendment. \n151 Deleted by the Fourth Amendment. \n152 Amended by the Fourth Amendment. \n153 Amended by the Sixth Amendment. \n154 Inserted by the Fourth Amendment. \n106 \n \nof an international inter -governmental organization who  is  paying a \nvisit to  Nepal at the invitation of the Government of Nepal.  \n(1d) 155 Notwithstanding anything contained elsewhere in this \nRegulation, direct procurement of up t o twenty -five thousand \nAmerican Dollars may be made for the maintenance of the building or \napartment of a Nepalese embassy or mission situated abroad.  \n(2) The procurement referred to in s ub-rule (1) may be made \nby making a framework or unit rate contract . \n(3) In cases where only one supplier has the right to supply  \nproprietary goods  or pharmaceutical products  156 pursuant to clause \n(c) of sub -section (1) of Section 41 of the Act, such goods or products \nmay be procured from  such a  supplier or through  his or her authorized \nseller or authorized agent.  \n(3a) 157 Notwithstanding anything contained in sub -rule (3), if \nthere is only one manufacturer of such goods as required for any \npublic entity in Nepal and there is no other appropriate alternative, the \nchief of the public entity making procurement may, upon recording \nthe same matter, make direct procurement from the manufacturer.  \n(3b) 158 In making d irect procurement from a manufacturer \npursuant to sub -rules (1a) and (1b) , it shall be made from the \nmanufacturer who has fulfilled the following conditions:  \n(a) Such a manufacturer has published a list of retail and \ndealer selling price of his or her product in a newspaper \nof national circulation,  \n \n155 Inserted by the Fourth Amendment. \n156 Inserted by the Fourth Amendment. \n157 Inserted by the Third Amendment. \n158 Inserted by the Third Amendment. \n107 \n \n(b) Such a manufacturer give s the same discount to the \nprocuring public entity as is given to the local dealer.  \n(3c) 159 In the event of procurement being made pursuant to sub -\nrule (3a), the Public Procurement Monitoring Office may examine or \ncause to be examined the cost of production by the industry related to \nsuch proc urement. If the cost is found unusual upon making such \nexamination, such an industry may be blacklisted.  \n(3d) 160 Notwithstanding anything contained elsewhere in this \nRegulation, a public entity may make direct procurement of such \ngoods the price of which doe s not exceed two million five hundred \nrupees as manufactured by any cottage industry which is so specified \nby the Government of Nepal by notification in the Nepal Gazette as to \nbe a domestic cottage industry, upon making a procurement contract \nwith such a cottage industry.  \n(4)161 The public entity shall, in making direct procurement \nexceeding one hundred thousand rupees ,162 make procurement by \ninviting  written  quotations or proposals from at least three suppliers, \nconstruction entrepreneurs, consultants or service providers included \nin the standing list.  \n(5) In making direct procurement of p roprietary goods \nreferred to in clause (d) of s ub-section (1) of Section 41 of the Act , \nsuch procurement  may be made up to thirty percent price of the \nprevious contract price.  \n \n159 Inserted by the Third Amendment. \n160 Inserted by the Fourth Amendment. \n161 Amended by the Third Amendment. \n162 Amended by the Fourth Amendment. \n108 \n \n(5a) 163 If any public entity is to procure any goods or service \nproduced or distributed by another public entity, it may directly \nprocure such goods or service at the selling price specified by the \ncompetent authority of the public entity producing or distributing such \ngoods or service.  \n(5b) 164 If any public entity is to procure any goods from any \ninternational inter -governmental organization or government of a \nforeign country or any public entity of such a country, it may direc tly \nprocure such goods at the selling price specified by such an \norganization, government or entity.  \n(5c) 165 Notwithstanding anything contained elsewhere in this \nRule, if any public entity is to make procurement pursuant to sub -\nrules (5a) and (5b), it  does n ot need to require any security.  \n(6) In the case of a direct procurement made in the \ncircumstances referred to in the other clauses than the circumstances \nreferred to in clauses (a) and (e) of sub -section (1) of Section 41 of \nthe Act, t he public entity  shall publicly publish a notice thereof, \nsetting out the name of the supplier, construction entrepreneur, \nconsultant or service provider , together with the nature  of, reason and \nbasis for, such procurement .  \n(7) Approval of one level higher authorit y shall be obtained \nto make procurement in the circumstance referred to in clause (d) of \nsub-section (1) of Section 41 of the Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "86", "title": "Matters to be ascertained before making direct p rocurement : (1) A", "content": "public entity  shall ascertain the following matters be fore making \ndirect procurement:  \n \n163 Inserted by the fourth Amendment. \n164 Inserted by the fourth Amendment. \n165 Inserted by the fourth Amendment. \n109 \n \n(a) Whether the goods to be procured are in stock  in the \nstorage or not,  \n(b) Whether the proposed construction entrepreneur, \nsupplier, consultant or service provi der possesses the \nqualification  required to perform the work under the \nprocurement contract or not,  \n(c) Whether the proposal submitted by the proposed \nconstruction entrepreneur, supplier, consultant or service \nprovider as per the invitation  of the public entity  \nconforms to  the specific ations and technical quality \ndetermined by such an entity or not, and  \n(d) Whether the price proposed by the proposed construction \nentrepreneur, supplier, consultant or other service \nprovider is reasonable  or not.  \n(2) In order to ascertain whether the pri ce referred to in \nclause (d) of s ub-rule (1) is reasonable  or not, the public entity  may, \nafter making rate analysis on the basis of market st udy, previous \nprocurement price and  the cost estimate, negotiate  with the \nconstruction entrepreneur, supplier, con sultant or other service \nprovider.  \n(3) The procurement contract under s ub-section (3) of \nSection 41 may also be  concluded through correspondence .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "87", "title": "Design may be procured through c ompetition : In procuring a design", "content": "of such matter  as architectural or urban planning, the public entity  \nshall prepare a document together with detailed description relating to \nsuch design and may procure a n appropriate design by having  \ncompetition as per such documen t. \n110 \n \n87A. 166 Other provisions relating to procurement : In making procurement \npursuant to clause (b) of sub -section (1) of Section 67 of the Act, the \nmatters not set forth in the procurement guidelines of the donor party  \nreferred to in the agreement concluded b etween the Government of \nNepal and the donor party shall be governed by the Act and this \nRegulation.  \n  (2) For the purpose of clause (c) of sub -section (1) of Section \n67 of the Act, the details of the public entities doing business \ntransaction in competiti on with the private sector shall be as referred \nto in Scheule -5A. \n  (3) In making procedures pursuant to sub -section (3) of \nSection 67 of the Act, such procedures shall be so made as not to be  \ninconsistent with the fundamental principles relating to public \nprocurement.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -8", "title": "Chapter -8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "88", "title": "Preparation and approval of cost estimate : (1) The chief of every", "content": "public entity  which is required to arrange for  ration shall, not later \nthan the last day of the month of Bhadra (mid -August) of each year, \nprepare a cost estimate as per th e ration quota approved for his or her \noffice, on the basis of the consumer price index of the concerned \nsector to be published by the Nepal Rastra Bank, the price index \npublished by the governmental body responsible for fixing the price \nof agricultural pr oducts, road facilities, local market rate, the \nprocurement contract rate of the previous year and the guidelines, if \nany, issued by the Public Procurement Monitoring Office.  \n \n166 Inserted by the Fourth Amendment. \n111 \n \n(2) The cost  estimate prepared pursuant to s ub-rule (1) shall \nbe submitted to th e following committee for approval:  \n(a) Chief District Officer  - Chairperson  \n(b) Chief, Treasury Controller Office or officer \nrepresentative of that Office  \n- Member  \n(c) Chief, District Agricultural Development \nOffice  \n-Member  \n(d) Representative, District Chamber of \nCommerce and Industry  \n-Member  \n(e) Chief of the public entity to arrange  for \nration  \n-Member -\nsecretary  \n (3) The committee referred to in sub -rule (2) shall, i n \napproving the cost estimate pursuant to this Rule , approve it in the \nformat set out in  Schedule -6, taking into account the matte rs referred \nto in s ub-rule (1).  \n(4) The public entity  shall send a notice of the approval of \nthe cost estimate pursuant to s ub-rule (3) to the superior office, \nRegional Administration Office and  Public Procurement Monitoring \nOffice, within seven days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "89", "title": "To arrange for p rocurement of ration: (1) A public entity  which is", "content": "required  to arrange for  ration may procure ration by inviting  sealed \nquotation s or bids pursuant to the Act and this Regulation, subject to \nthe condition that the new supplier shall supply ration from the firs t \nday of the month of Magh (mid -January) each year.  \n112 \n \n(2) While inviting sealed quotation s or bid s to be invited \npursuant to s ub-rule ( 1), the public entity  shall specif y, inter alia, the \nfollowing matters:   \n(a) Type and quality of ration, Sida, feed and fodder,  \n(b) Daily required q uantity,  \n(c) Matter that price increment shall not be given during the \ncontract period, and  \n(d) Mater that contract can be concluded  only with the \nNepalese citizen .  \n(3) Ration arran gements for a security e ntity shall  be made \nas provided hereunder:  \n(a) Sealed quotation form s or b idding documents may be \nsold by the concerned security e ntity, Distric t \nAdministration Office and Treasury Controller Office as \nwell, and the notice for invitation  to sealed quotation s or \nbids shall set out that such quotation forms or bids  can be \nsubmitte d to the concerned security e ntity. The sealed \nquotation form s or bidding documents shall al so specify \nthe time and place for  opening such sealed quotati ons or \nbids. \n(b) Prior to inviting sealed quotation s or bid s, the security \nentity to arrange for ration shall send at least twenty  \ncopies 167 of the sealed quotation form s or bidding \ndocuments  relating to ration arrangement  each to the \nentities referred to in clause (a) for sal e and in the case of \nshortfall of such form s or documents, the concerned \n \n167 Amended by the Third Amendment. \n113 \n \nsecurity e ntity shall send such form s or documents to \nsuch entities as per their request.  \n(c) The entities  referred to in  clause (a) shall sell the forms \nand bidding documents received pursuant to clause (b) to \nthe interested seal ed quotation bidders  or bidders and \nsend the records thereof to the concerned security e ntity.  \n(d) A sealed quotation bidder or bidder who buys  such sealed \nquotation form s or bidding documents may, after duly \nfilling such form s or documents and sealing the m, so \nsend or deliver to the concerned security entity \npersonally or through his or her representative  or through \npostal or courier service as to reach within the time \nspecified in the notice inviting such sealed quotation s or \nbids.  \n(e) The security e ntity shall re ceive the sealed quotation \nforms or bids  received pursuant to clause (d) and \nmaintain records thereof.  \n(f) The concerned security e ntity shall , immediately after the \nlast date and time for submission of sealed quotations or \nbids, open the sealed  quotation s or bid s received by its \noffice at the time specified in the sealed quotation forms \nor bidding documents.  \nExplanation : Fo r the purpose of this clause, \"security \nentity\" means the Nepal Army, Nepal Police, Armed \nPolice Force or an y entity specified by the Government \nof Nepal.  \n114 \n \n(4) The concerned public entity  shall prepare a comparative \nchart of the sealed quotation s or bid s opened pursuant to this Rule , in \nthe format referred to in Schedule -7.  \n(5) The public entity  shall examine an d evaluate the sealed \nquotation s or bids referred to in sub-rule (4) in accordance with  the \nAct and this Regulation and accept the sealed quotation or bid quoting \nthe lowest rate , and then conclude the contract with such a lowest rate \nprovider.  \n(6) If a se aled quotation bidder or bidder who submits  the \nsealed quotation or bid pursuant to this Rule is found to have \nmentioned more than one hundred percent rate of the prevailing \nmarket rate in two or more items of goods, the evaluation committee \nmay recommend for cancellation of such sealed quotati on or bid.  \n(7) The chief of the public entity shall , not later than  seven \ndays of conclusion of the procurement contract pursuant to this Rule, \nprepare a report together with the comparative chart referred t o in \nsub-rule (4) and give information to the superior office and the Public \nProcurement Monitoring Office . \n(8) If, in buying food grain s by the supplier to arrange for \nration as per the procurement contract, the local market f aces shortage \nof food grain s, the concerned C hief District Officer shall, in contact \nwith the agencies concerned with food , cause to be made available the \nnecessary permit for managing ration by purchasing from other \ndistricts.  \n(9) If an arrangement for rati on, Sida cannot be  made or loss \nor damage is caused to the G overnment due to delay of any kind, the \nchief of the concerned public entity  shall be responsible for such loss \nor damage.  \n115 \n \n(10) The public entity  to arrange  for ration shall arrange ration \nin accordance with the pr ovisions contained in this C hapter , and with \nthe provision s of the Act and this Regulation in the case of the other \nmatters than those contained in this Chapter.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "90", "title": "Direction to be c omplied with : If a procurement contract for ration", "content": "arrangement  could not be concluded or where such contract, even if \nconcluded, is violated or where the public entity  has terminated  the \nprocurement contract pursuant to the Act or thi s Regulation, the chief \nof such an entity  shall commence new procurement process not later \nthan fifteen days ,168 and write to the superior office for direction and \nprovide ration as d irected by the superior office, until the new process \nis completed . 169", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "91", "title": "Power to make inspection : (1) The chief of p ublic entity  may, as", "content": "required, make inspection as to whether the supplier has supplied \nration of the quality specified in  the contract or not , and if the ration \nsupplied is not found to be of the qualit y specified in the contract, he \nor she may initiate action to terminate  the contract.  \n(2) Where the  contract is terminated pursuant to s ub-rule (1) \nor for any other rea son, the supplier shall pay the public entity  the \noutstanding advance money, if any, due to the public entity , together \nwith an annual interest at the rate of ten percent thereon effective \nfrom the date on which the advance was taken. If the supplier does not \npay such an amount within thirty days of such termination of the \ncontract, that amo unt shall be recovered from him or her as \ngovernmental dues.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "92", "title": "Security to be taken for a dvance : (1) If a public entity  making", "content": "arrangement  for ration is to give advance to the supplier after \n \n168 Inserted by the Fourth Amendment. \n169 Inserted by the Fourth Amendment. \n116 \n \nconcluding the procurement contract, it may give an advance up to \ntwenty-five percent of the quoted price  against a bank guarant ee \ncovering such advance amount which is  issued by a commercial bank \nand has the validity period of at least seven months.  \n(2) If the sanctioned  budget amount is insufficient to give \nadvance pursuant to s ub-rule (1), the concerned public entity  shall \nrequest the concerned Treasury Controller Office to sanction  \nadditional amount , and, if so requested,  that Office too shall sanction  \nadditional amoun t subject to the approved budget.  \n(3) The public entity  shall recover by the end of the current \nfiscal year the whole advance amount  given pursuant to s ub-rule (1) \nby deducting an amount at the rate of fifty percent from every month's \nbill of the supplier.   \n(4) Once the advance amount given to the supplier for the \nfirst time has been recovered, the public entity  may again give  an \nadvance amount of twenty -five percent of the quoted pri ce in the \nmonth of Shrawan (mid -August) of the new fiscal year against a \nsecurity having validity period at least of  seven months and shall \nrecover the advance amount so given by the end of the mo nth of \nPoush (mid -January) of the same fiscal year by deduct ing such an \namount pursuant to s ub-rule (3).  \n(5) The supplier shall stock in his or her warehouse  the \nration equivalent to the amount of advance given pursuant to s ub-rules \n(1) and (4) .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "93", "title": "Other arrangement may be made for r ation : If the concerned central", "content": "office directs  the public entity  to arrange for ration to provide cash \ninstead of ration , such an entity may provide  such amount in cash as \nto be calculated on the basis of the rate of the approved cost estimate \npursuant to Rule 88 and  the approved number of position s. \n117", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -9", "title": "Chapter -9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "94", "title": "Provision on renting a house, l and: (1) If a public entity  is required  to", "content": "rent a house or land, it shall invite for rent proposal s by publishing a  \nnotice of at least fifteen days  in a newspaper of national circulation in \nthe case of a central level public entity  located within the Kathmandu \nValley, and by posting a notice of at least seven day s on the notice \nboard of such an entity and of the following offices in the case of a \nregional or district level public entity :  \n(a) District Administration Office,  \n(b) District Coordination  Committee, and \n(c) Treasury Controller Office.  \n(2) The public entity shall set out the following matters in \nthe notice referred to in s ub-rule (1):  \n(a) Name and address of the concerned public entity , \n(b) Area or location where  the house , land is required,  \n(c) Nature, area and other necessary details of the house , \nland sought to be rented,  \n(d) Information that the house , land shall be rented only at \nthe rate fixed by the committee referred to in s ub-rule (4),  \n(e) Procedures to be followed by the house , land owner  to \nsubmit a proposal and minimum details matters to be \nsubmitted  with the proposal,  \n(f) Place for submitting the proposal a nd the last date for its  \nsubmission,  \n118 \n \n(g) Conditions for payment of the house, land rent and \ndeduction of tax, and  \n(h) Such o ther matters  as the public entity  considers \nappropriate .  \n(3) The public entity  shall open the proposals on providing \nhouse, land on rent  submitted within the  period  referred to in s ub-rule \n(1) and submit them to the committee referred to in s ub-rule (4).  \n(4) There shall be a house rent fixation c ommittee as follows  \nin each district to fix the rent of the house , land to be ren ted by a \npublic entity : \n(a) Chief District Officer  - Chairperson  \n(b) Chief, Treasury Controller Office  -Member  \n(c)170 Technician designated by the District \nCoordination Committee  \n-Member  \n(d) Chief of the public entity renting \nhouse, land  \n-Member  \n(e) Employee of the District \nAdministration Office designated by \nthe Chief District Officer (officer level \nso far as available)  \n-Member - \nSecretary  \n \n(5) The procedure relating to  meeting s of the committee \nreferred to in s ub-rule (4) shall be as determined by the committee \nitself.  \n \n170 Amended by the Sixth Amendment. \n119 \n \n(6) The committee referred to in s ub-rule (4) shal l fix the \nrent of house, land by evaluating the proposal submitted pursuant to \nsub-rule (3) on the following basis:  \n(a) Location of the house , land and the road facility,  \n(b) Structure and area of the house , land, \n(c) Physical facilities,  \n(d) Premises of the house , land ,  \n(e) The amount of re nt proposed by the owner of \nhouse, land, and  \n(f) The prevailing rate of house rent. \n(7) Once the rent of the house , land is fixed pursuant to sub -\nrule (6), the house rent fixation committee shall give information \nthereof  in writing  to the concerned public entity .  \n(8) After receiving the information referred to in s ub-rule \n(7), the concerned public entity  shall rent  the house , land by \nconcluding a contract with the concerned house, land owner.  \n(9) The contract referred to in s ub-rule (8) may be renewed \nwith the consent of the house, land owner and the p ublic entity .  \n(10) If it is required to increase  the rate of rent of house , land, \na prop osal shall be submitted to the c ommittee referred to in s ub-rule \n(4) for fixation of hous e, land rent after obtaining the approval of the \nMinistry of Finance . \n(11) 171 If a public entity is required to rent a house, land for an \nannual rent amount not exceeding one million five hundred rupees \nwithin the Kathmandu Valley and that not exceeding  five hundred \nthousand rupees outside the Kathmandu Valley, the entity may rent \n \n171 Amended by the Fifth Amendment. \n120 \n \nthe house, land by negotiating directly with the house, land owner as \nto services, facilities and amount of rent, upon selecting the \nappropriate proposal, out of the proposals recei ved pursuant to the \nnotice referred to in sub -rule (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "95", "title": "Procedures relating to service c ontract : (1) If a public entity  is", "content": "required to take services on service contract to operate its day -to-day \nworks such as office security, transportation of letters, sanitation, \noperation and supervision of telephone, electricity and water supply  \nsystem, animal health and agricultural dissemination, maintenance \nand care  of g arden, typing or computer type and driving, it may take \nsuch services by concluding a contract with an y person, firm, \norganization or company.  \n(2) In contracting the  service s referred to in s ub-rule (1), the \nrequirements, type, duration, qua lity, service operation method,  \ntentative expense to be incurred and the terms of reference of such \nservice  shall be prepared and  caused to be  approve d by the chief of \nthe public entity .  \n(3) The public entity  may, by way o f negotiation, procure a \nservice the service fee of which does not exceed five hundred \nthousand r upees.172 In the case of the service  the service fee of which \nexceeds  that amount , the public entity  may invite proposals by \npublishing a notice of fifteen days in a newspaper of national \ncirculation if it is an entity located in the Kathmandu Valley or a \ncentral level public entity , and by publishing a notice of fifteen days  \nin a local newspaper if it is  a r egional or district level entity , and by \nposting such a notice on the notice board of the entity and of the \nfollowing offices : \n(a) District Administration Office,  \n \n172 Amended by the Fourth Amendment. \n121 \n \n(b)173 District Coordination Committee, and  \n(c) Treasury Controller Office.  \n(4) The public entity  shall specify the following matters in  \nthe notice referred to in s ub-rule (3):  \n(a) Name and address of the concerned public entity ,  \n(b) Nature, quantity, conditions of service and other \nnecessary matters,  \n(c) Place and duration of the service  to be provided,  \n(d) Minimum documents and details to be submitted by the \nproponent along with the proposal,  \n(e) The place and last date for submission of  the proposal,  \n(f) Conditions of payment of service fees and the matter of \ntax deduction, a nd  \n(g) Other necessary matters.  \n(5) The public entity  shall open the proposals received within \nthe deadline pursuant to Rule 59 and evaluate the proposal s of the \nproponent s.  \n(6) While evaluating the proposals pursuant to sub -rule (5), \nthe public entity  shall accept the proposal of the proponent who has \noffered the lowest service charge by fulfilling the terms of reference \nreferred to in sub -rule (2) and conclude the service contact agreement.  \n(7) If a p roponent whose proposal is accepted pursuant to \nsub-rule (6) does not appear to conclude the service contract, a service \ncontract may be concluded with the proponent offering the next \nlowest service charge.  \n \n173 Amended by the Sixth Amendment. \n122 \n \n(8) The public entity  shall monitor, from time to time , the \nservice rendered by the service provider. In so monitoring , if the \nservice is not found to be satisfactory or is not consist ent with the \ncontract, such e ntity shall give a notice  to the service provider to \nupgrade the level of service and if the level of service is not upgraded \neven afte r providing such a notice, another service contract is to be \narranged by cance lling the service contract.  \n(9)174 Notwithstanding anything contained elsewhere in this \nRule, if it is required to perform the work to be performed by class -\nless posts through ser vice contract by making contract with a person \nor organization specifying the minimum remuneration pursuant to the \nCivil Service Act,  1992 (2049), the matter shall be governed by the \nprovisions of that Act  accordingly .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "96", "title": "Procedure s for repair and maintenance of g oods: (1) If any goods", "content": "existing in the public entity  require  repair or maintenance , the user of \nsuch goods shall give written information  thereof to the chief of that  \nentity. Upon receipt of such information, he or she shall  have a cost  \nestimate prepared pursuant to s ub-rule (5) of Rule 13 and approve the \nsame. \n(2) Once the cost es timate is prepared pursuant to s ub-rule \n(1), the public entity  shall have the goods repaired by its workshop or \nrepair center where it has such a workshop or repair center. If in so \nhaving goods repaired or maintained, any goods, equipment or spare \nparts need to be altered, such goods, equipment or spare parts shall be \nobtained from stock, where there is such a stock, and where there is \nno such a stock, be procure d by application of the process set out in  \nthe Act and this Regulation.  \n \n174 Inserted by the First Amendment. \n123 \n \n(3) In the event of procurement of equipment or spare parts \npursuant to s ub-rule (2), the public entity  shall cause such goods or \nequipment to be  delivered  to store an d keep records of the equipment \nor spare parts the per unit price of which exceeds five thousand \nrupees, and get it certified by the concerned technician that such spare \nparts have been  replaced for t he old equipment or spare parts, and \ndeliver  the old goo ds to store.   \n(4) A public entity  which does not have its own workshop  or \nrepair center shall have repair and maintenance of  the goods by \napplication of the process set out in  the Act and this Regulation.  \n(5) Notwithstanding anything contained elsewhere in this \nRule, a public entity  which has its  own workshop or repair center may \napprove the cost after the repair and maintenance, by maintaining \nrecords of  repair work in the job card.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "97", "title": "Procedures of carrying out work through users' committee or", "content": "beneficiary c ommunity : (1) 175 Notwithstanding anything contained \nelsewhere in this Regulation, a construction work or service related \nthereto the cost estimate  of which does not exceed ten million rupees \nmay be caused to be executed by  or obtained from a users' com mittee \nor beneficiary community consisting only of the inhabitants residing \nin that place and from the community using such service.   \n  (1a) 176 The cost estimate not exceeding ten million rupees 177 as \nreferred to in sub-rule (1) shall include value added tax, overhead \ncontingency amount and amount of portion of  public participation.  \n(2) For the purpose of s ub-rule (1), a public entity  may invite  \nproposal s by publishing a public notice setting out  the nature, quantity \n \n175 Amended by the Sixth Amendment. \n176 Inserted by the Third Amendment \n177 Inserted by  \n124 \n \nof the concerned work o r service, required amount, amount to b e \nborne by the users' committee or beneficiary community and other \nnecessary matters or such committee or community its elf may submit \na proposal or application.  \n(3) Upon receipt of the proposal or appli cation referred to in \nsub-rule (2) , the concerned public entity  and such users' committee or \nbeneficiary community shall conclude a procurement contract in \nrespect of such work or services , upon discussing, negotiating or \nvisiting the construction site, as required . Such a contract shall  \ncontain the following matters:  \n(a) Nature, quantity , cost estimate  of the cons truction \nwork or services,  the amount that the users' \ncommittee will bear or has to bear, period for  \ncompletion o f the work or services,  \n(a1) 178 In the case of a work the cost estimate of which \nexceeds six million rupees,  contribution to be made \nby the users' committee or beneficiary community \nto each work unit,  \n(b) Matter that the public entity  shall carry out the \nwork of preparing and approving the design and \ncost estimate of the concerned work, providing \ntechnical advice, carrying out measurement, final \nacceptance and providing other necessary technical \nassistance, s upervision and quality cont rol, \n(c) Matter that th e construction work or service shall \nbe completed or made available with the  \n \n178 Inserted by the Fifth Amendment. \n125 \n \nparticipation of the public entity  and the users' \ncommittee or beneficiary community,  \n(d) Statement that the users' committee or beneficiary \ncommunity shall  operate or repair  and maintain  the \ncompleted construction work,  \n(e) Advance a mount to be made by the public entity  to \nthe users' committee or beneficiary community,  \n(f) Conditions and mode of payment for the complet ed \nconstruction work or service , and  \n(g) Other necessary matters.  \n(4) In awarding t he construction work or service  to the users' \ncommittee or beneficiary community, payment shall be made only \nafter deducting value added tax, overhead contingency amount and \namount of portion of public partici pation specified in  the cost -\nestimate referred to in clause (b) of s ub-rule (3).  \n(5) Once the procurement contract is concluded pursuant  to \nsub-rule (3), the public entity  may give earlier advance payment not \nexceeding  one third amount of the contract amo unt to such a \ncommittee or community. The public entity  shall settle the advance so \ngiven before payment of the final installment . \n(6) The users' committee or beneficiary community shall \nhave the technical evaluation  of the work , bill s, receipt s and other \ndocument s proving the expenditure of the work of each installment \nendorsed by its meeting and submit  the same  to the concerned public \nentity.  \n126 \n \n(7)179 The users' committee or beneficiary community shall post \na notice in  the public place of the expenditure made by it in each \ninstalment, and have social audit of the acts and actions performed by \nit within such period and in accordance with such process as specified \nby the Public Procurement Monitoring Office.  \n(8) If the public entity  is unable to provide  technical \nassistance to the users' committee or beneficiary community for the \nconcerned work, the committee or community itself may appoint \ntechnical human resource required for the  work. The remuneration \nrequired to be paid to the technician so appointed shall be paid from \nthe contingency deducted by the public entity . Provided that such \nremuneration shall not exceed  three percent of the cost estimate.  \n(9) Heavy machines such as a loader, excavator, roller, \ndozer, grader, bitumen distributor  and bitumen boiler cannot be used \nin the construction work to be executed  by the users' committee or \nbeneficiary  community.  \n180Provided that if the work is so mentioned when the cost \nestimate was prepared as to be  work of complex nature requiring the \nuse of heavy machines, such machines may be used with the consent \nof the public entity, on recommendation of the conce rned technician.  \n(9a) 181 If it is found that any heavy machine has been used \ncontrary to the proviso to sub -rule (9), the contract concluded with \nsuch a users' committee or beneficiary community shall be canceled.  \n(10) The users' committee or beneficiary community itself \nshall complete the work obtained by it and cannot cause such work to \nbe executed by  a construction entrepreneur or sub-contractor. If, for \n \n179 Amended by the Fifth Amendment. \n180 Inserted by the Fifth Amendment. \n181 Inserted by the Fifth Amendment. \n127 \n \nany reason, such a committee or community itself cannot complete  \nthat work in time, it shall give a notice thereof to the public entity . \nUpon receipt of such a notice, the public entity  shall, after making \nnecessary inquiry into the matter , terminate the contract concluded \nwith such a committee or community and have th e remaining work \nexecuted  in accordance with  the Act and this Regulation.  \n(11) 182 After c ompleting the construction work , the users' \ncommittee or bene ficiary community shall cause such work to be \nfinally examined and accepted by a technical employee deputed by the \nconcerned public entity  and submit to that entity the statement s of the \ntotal expenditure including  the money received from such an entity \nand the cost of labor, cash or goods -in-kind provid ed or borne through \npublic participation. The concerned public entity  shall prepare a work \ncompletion report setting out, inter alia, the statements so received \nand the survey, design, cost estimate, supervision  of the construction \nwork and name and post of the person and official h aving performed \nthe work and keep the records thereof. \n(12) Once the construction  work is completed pursuant to s ub-\nrule (11), the public entity  shall transfer the ownership of the project \nto the users ' committee or beneficiary community , also specifying t he \nresponsibility of care , repair and maintenance thereof.  \n(13) If the  users' committee or beneficiary committee is found \nto have misused any  amount  received by it, the concerned public \nentity shall inquire into the matter and  recover such an amount as \ngovernment dues on pro -rata basis from the office -bearers of the \nusers' committee. It shall be the duty of the concerned Chief District \nOfficer to render  assistance to such an entity in making such recovery.  \n \n182 Amended by the Fifth Amendment. \n128 \n \n(13a) 183 If the users' committee or bene ficiary community is \nfound to have involved a construction entrepreneur in any work \nobtained by it, the public entity shall cancel the contract concluded \nwith that users' committee or beneficiary community, maintain \nrecords to the effect that any of such k ind of work will not be awarded \nto such a users' committee or beneficiary community in the future, and \nmake a recommendation to the Public Procurement Monitoring Office \nto blacklist the construction entrepreneur who has executed that work.  \n(14) The Public Procurement Monitoring Office may determine \nthe procedures to be followed by a public entity  in having a work \nexecuted by  the users' committee or beneficiary community with \nrespect to the following matters:  \n(a) Determination of labour -intensive  work,  \n(b) Method of  formation, and functions, duties and \npowers of the users' committee or beneficiary \ncommunity,  \n(c) Manner of increasing economy, quality , \nsustainability of the work or service ,  \n(d) Keeping the record s of income s and expenditure s,  \n(e) Supervision and monitoring  of the work or service ,  \n(f) Settlement and final  examination and  acceptance of \nthe construction work, and  \n(g) Other necessary matters.  \n(15) The users' committee or beneficiary community may fix \nthe service charge to be paid by the  users for using the service of the \nproject transferred pursuant to s ub-rule (12) and shall establish a fund \n \n183 Inserted by the Fifth Amendment. \n129 \n \nconsisting of  such charges and operate, repair and maintain such \nconstruction work from such fund.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "98", "title": "To have construction w ork executed through force a ccount : (1) A", "content": "public entity  shall obtain prior approval of one level higher authority \nfor the  execution of  a work through force account.  \n(2) If the public entity  is required to execute a work through \nforce account , it shall execute  the work on wage basis by procuring \nthe technical service and construction materials  required for that work  \nin accordance with the process set forth in the Act and this \nRegulation.  \n(3) If a construction work is to be executed  through force \naccount pursua nt to this Regulation, such a work may be caused to be \nexecuted through negotiation after breaking it into piece s not \nexceeding one hundred thousand rupees  or be awarded on wage basis \nby making available the necessary construction materials.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "99", "title": "Provision s relating to  execution of work by a non -governmental", "content": "organization : (1) In order to have a work executed by  a non -\ngovernmental organization pursuant to Section 46 of the Act, the \nterms of reference specifying the requirement, type, period, quality of \nwork, human resource, operational modality of such work and a \ntentative estimate of the required amount shall be prepared.  \n(2) In order to have the work of up to one million rupees ,184 \nthe public entity  shall request proposal s from non-government \norganization s registered pursuant to the law in force with the \nobjective of carrying out such work and included in the standing list \n \n184 Amended by the Sixth Amendment. \n130 \n \nreferred to in Rule 18, by publishing a notice  in a daily newspaper of \nnational or local circulation ,185 giving a period at l east of f ifteen days .  \n(3) The following matters shall be set out in the notice \nreferred to in s ub-rule (2 )186:  \n(a) Name and address of the public entity  inviting proposal s, \n(b) Nature, quantity and other necessary details of the \nproposed work,  \n(c) Place for the  performance and period for the completion \nof the proposed work,  \n(d) Deadlin e and place for submission of proposal s,  \n(e) Format of the proposal,  \n(f) Documents to be subm itted by the proponent along with \nthe proposal,  \n(g) Conditions of payment and tax deduction, and  \n(h) Such o ther matters as the Public Procurement Monitoring \nOffice considers  necessary .  \n(4) The public entity  shall open the proposals received \npursuant to t he invitation referred to in sub-rule (2 ) 187 in the presence \nof the proponents and prepare a record ( Muchulka ) thereof .  \n(5) The eva luation committee shall recommend the proposal \nof a proponent who offers  the lowest amount after fulfilling the terms \nof reference referred to in sub -rule (1) to the public entity for \nacceptance.   \n \n185 Inserted by the Fourth Amendment. \n186 Amended by the Fourth Amendment. \n187 Amended by the Fourth Amendment. \n131 \n \n(6) If the pr oposal recommended pursuant to s ub-rule (5) \nappears  to be appropriate, the public entity  shall accept such a  \nproposal and give a notice specifying the  date to the concerned \nproponent to appear to conclude a contract , and conclude the contract \nwith him or her if he or she appears on such date.  \n(7) If the proponent whom the notice was given to pursuant \nto sub-rule (6) fails to appear to conclude the contract, a contract may \nbe concluded with the proponent who offers the next lowest amount to \nhim or her after fulfilling the terms of reference referred to in s ub-rule \n(1). \n(8)188 Notwithstanding anything contained elsew here in this \nRule, for the execution of a work the cost estimate of which exceeds \none million rupees, open letters of intent shall be invited pursuant to \nRule 70 and the process applicable for procurement of a consultancy \nservice shall be followed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -10", "title": "Chapter -10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "100", "title": "Matters to be specified in a pplication to be made to the c hief of public", "content": "entity: A bidder or proponent desiring to make an application  to the \nchief of public entity pursuant to Section 47 of the Act for the review \nof procurement action  or decision shall specify the following matters \nin such an  application and sign it:  \n(a) Name, address, telephone, fax number and e -mail of the \napplicant,  \n(b) If the applicant is a cor porate body, power of attorney \ngiven by that body to make such an application,  \n(c) Bid number,  \n \n188 Inserted by the Sixth Amendment. \n132 \n \n(d) Factual and legal grounds for making application,  \n(e) Copy of the relevant document.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "101", "title": "189 Ceiling  of the amount: (1) For the purpose of s ub-section (8) of", "content": "Section 47 of the Act, no application may be made to the review \ncommittee in respect of the procurement action  of less than twenty  \nmillion r upees.190  \n  (2) Notwithstanding anything contained in sub -rule (1), \napplication may be made to the review committee against the \nevaluation of bids or proposals of such nature that the price  cannot be \nset out such as prequalification or technical proposals.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "102", "title": "191 Details to b e s ubmitted : The chairperson and member of the", "content": "review c ommittee shall  submit to the Office of the Prime Minister and \nCouncil of Ministers through the Public Procurement Monitoring \nOffice the details referred to in clauses (a) and (b) prior to assuming \ntheir respective office, and the details referred to in clause (c) after \nthe assumption of their respective office:  \n(a) Biodata including educational qu alification  and \nexperience in the concerned field,  \n(b) In the event of involvement in any tr ade, business, \ndetails thereof,  \n(c) Details of the property in his or her name and \nfamily's name not later than thirty -five days of the \ndate of assumption of office for the first time and \nsixty days of the expiry of each fiscal year.  \n \n189 Amended by the Sixth Amendment. \n190 Amended by the Eighth Amendment. \n191 Amended by the Fourth Amendment. \n133", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "103", "title": "Matters to be set out in application to be made for r eview….192: (1) A", "content": "bidder or proponent who wishes  to make  an application  for review \n………. 193 pursuant to Section 49 of the Act  shall set out  the \nfollowing matters in , and sign,  the application : \n(a) Name, address, telephone number, fax number and \ne-mail address of the applicant,  \n(b) If an application is to be filed on behalf of a \ncorporate body, documen t providing authority to so \nmake application,  \n(c) Brief description of the procurement action ,  \n(d) Where the procurement contract has already been \nconcluded, the date of its conclusion and the \nsupplier, construction entrepreneur, consultant or \nservice provider who has obtained  such a contract,  \n(e) Factual and legal grounds that the applicant should  \nhave obtained the  procurement contract,  \n(f) Factual and legal grounds that one who has \nobtained the procurement contract should not have \nobtained  such a contract,  \n(g) If the review committee has to take  any special \nmeasure to protect the proprietary, trade and \nconfidential information of the applicant, such \nspecial measure , and  \n(h) The actual loss and damage  caused to or likely to \nbe caused to the applicant as a result of his or her \nfailure to obtain  the con tract.  \n \n192 Deleted by the Third Amendment. \n193 Deleted by the Third Amendment. \n134 \n \n(2) The applicant sha ll, along with the application referred to \nin sub-rule (1), attach copies of the  document  substantiating the claim \nmade by him or her. If  the document is of such nature that it cannot be \nin his or her possession, he or she may r equest the review c ommittee \nto cause the concerned public entity  to produce such document . \n(3) If the applicant wishes  to make hearing as to the matter \nstated in the application referred to in sub -rule (1) before the review \ncommittee,  he or she shall set out the reason  and ground for it.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "104", "title": "Security to be furnished : (1) An applicant  who makes an application", "content": "pursuant to Section 50 of the Act shall submit cash amount or bank \nguarantee having the validity period of at least of ninety days \nequivalent to  0.1 (zero decimal  one) percent 194 amount of the amount \nquoted by him or her in the  bid or proposal.  \n  (1a) 195 In making an application to the review committee \nagainst the evaluation of a proposal of such nature as the price cannot \nbe set out such as a prequalification or technical proposal, there shall \nbe furnished a security equivalent to a lump sum amount specified \nsubject to the proviso to sub -section (1) of Rule 53  in the case of the \nprequalification proposal and equivalent to the amount to be set b y ten \npercent of the bid security in the case of the technical proposal.   \n(2) If the cash amount or bank guarantee referred to in s ub-\nrule (1) is not furnished, the review c ommittee shall not take action on \nthe application made to  it.  \n(3) If the claim mad e in the application is sustained in \nmaking a decision pursuant to th e Act and this Regulation, the review \ncommittee shall return such security to the applicant within seven \ndays of such a decision being made.  \n \n194 Amended by the Eighth Amendment. \n195 Inserted by the Fourth Amendment. \n135", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "105", "title": "Method of sending application for r eview: (1) A bidder or proponent", "content": "may himself or herself deliver or send by post, courier service or \nelectronic means the application to be made for review to the chief of \npublic entity  or review c ommittee.  \n(2) If the application sent by post, courier serv ice o r \nelectronic means pursuant to s ub-rule (1) does not reach the review \ncommittee within the time period specified in the Act or this \nRegulation, no action shall be taken upon such an application.  \n(3)196 Upon receipt of the application for review pursuant to \nsub-rule (1), the public entity shall withhold the procurement contract \nuntil decision is made by the review committee.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "106", "title": "Matters to be stated in information and c omments : (1) The", "content": "information and comments to be given by a public entity  pursuant to \nsub-section (3) of Section 50 of the Act shall contain the factual \nstatement of the claim, legal grounds of procurement action and \ncopies of the relevant documents.  \n(2) The review c ommittee may order the public entity  to \nsubmit the appropriate docum ent or portion thereof out of the \ndocument s relating to procurement.  \n(3) The r eview committee may, if it considers necessary, \ngrant permission to the bidder or proponent who has not submitted the \napplication for review  to submit the relevant document and evidence.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "107", "title": "Hearing concerning r eview: (1) The review c ommittee may, if it", "content": "conside rs necessary to inquire into both the applicant and the \nconcerned public entity , make such inquiry  after the public entity  has \nsubmitted  the information, comments and documents referred to in  \nRule 106.  \n \n196 Inserted by the Fifth Amendment. \n136 \n \n(2) If inquiry has to be made pursuant to sub-rule (1), the \nreview c ommittee shall notify the concerned party to make \nappearance, by specifying the period . \n(3) The review committee shall keep records of the actions  \nreferred to in  this Rule , and the concerned party may take copy \nthereof upon paymen t of the applicable charges.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "108", "title": "Records of decisions on c omplaint s: The concerned public entity  shall", "content": "maintain records of the decision made by it, review c ommittee or \nother body with respect to the review and remedial measures taken  \nwith respect  to such decision, and give information thereof to the \nPublic Procurement Monitoring Office each year .197", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter - 11", "title": "Chapter - 11", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "109", "title": "Budget code to be m entioned : A public entity  shall mention the", "content": "budget code in the procurement contract.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "110", "title": "Performance security to be furnished for conclusion of c ontract : (1) A", "content": "bidder whose bid is accepted shall, while  furnishing the  performance \nsecurity pursuant to s ub-section (4) of Section 27 of the Act, furnish  \nthe pe rformance security issued by a commercial bank in the format  \nspecified in the bidding documents within the time referred to in s ub-\nsection (3) of Section 27 of the Act  \n(2)198 In submitting the performance security  referred to in sub -\nrule (1) , the amount referred to  in sub -section (4) of Section 27 of the \nAct shall be set out . \n(3) In the case of a procurement contract which does not set \nout the amount pursuant to s ub-rule (2), such a performance security \n \n197 Amended by the Fifth Amendment. \n198 Amended by the Fourth Amendment. \n137 \n \nas stipulated in the bidding documents by the public entity  shall be \nfurnished.   \n(4) Unless otherwise provided  for in the procurement \ncontract, the validity period of the performance security referred to in \nsub-rule (1) shall exceed at  least one month  beyond the last period of \ntime for the supply or delivery of the goods or the warranty period or \nthe defects liabil ity period of the construction work referred to in such \na contract.  \n(5) The performance security issued by a foreign bank s hall \nbe valid only if it is counter -guaranteed by a commercial bank \nestablished in Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "111", "title": "Provisions c oncerning implementation  of contract : (1) A public entity", "content": "shall, while implementing  a procurement contract, carry out the \nfollowing acts,  as required:   \n(a) To hold , if necessary, a post-bid conference with \nthe concerned supplier s, consultant s, service \nprovider s or construction entrepreneur s, \n(b) To prepare a work plan and work schedul e relating \nto contract implementation ,  \n(c) To make  arrangement for opening a letter of credit \nwithin the time as per the conditions of the \ncontract,  \n(d) To form a contrac t implementation  team, if \nnecessary,  \n(e) To monit or the progress of the implementation  of \nthe procurement contract in accordance with t he \nprocurement administration work plan and to \ninspect and test quality aspects,  \n138 \n \n(f) To hand over the possession of the construction \nsite to the construction entrepreneur and to make \narrangements for access thereto, to manage \nprocurement contract modifica tion, variation order, \nprice adjustment, suspe nsion or termination of the \nprocurement contract, work completion  \ncertification, payment etc,  \n(g) If any dispute arises between the public entity  and \nthe supplie r, consultant, service provider  or \nconstruction entrepreneur, to have recourse to the \nmechanism for dispute settlement referred to in \nsuch a contract; where the contract is breached, to \ninstitute  action  as per the provision s relating to \nremedies  referred to in the contract,  \n(h) To manage the financial aspects of the contract \nimplementation including the budget and cost \naccounting aspect,  \n(h1) 199 To make provision requiring that the construction \nentrepreneur mandatorily post the details referred \nto in Schedule -8 on its notice board at the \nconstruction site,  \n(i) To keep the documents relating to contract \nimplementation orderly and systematically,  \n(j) To approve the performed work, and  \n(k) To submit periodic reports  of contract \nimplementation to one level higher authority.  \n \n199 Inserted by the Fourth Amendment. \n139 \n \n(2) Notwithstandi ng anything contained elsewhere in this \nRegulation, a public entity  or other entity involved in supervising the \nimplementation  of the procurement c ontract may, without prejudice to  \nthe rights of the supplier, consultant, service provider or construction \nentrepreneur set forth  in the procurement contract, supervise whether \nthe procurement contract is implemented  in accordance with the \ndrawing, specifications and terms and conditions of the procurement \ncontract or not.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "112", "title": "Insurance to be m ade: (1) Except as otherwise provided in the", "content": "procurement contract, a construction entrepreneur executing a \nconstruction work  the price of which exceeds one million r upees shall \ninsure the following matters:  \n(a) Full replac ement costs of the construction work  \nincluding construction materials, machine, \nequipment or plant to be used,  \nExplanation : For the purpose of this clause , \"costs\" \nincludes the profit  as well .  \n(b) Fifteen percent amount of the replacement cost s \nreferred to in clause (a) or additional amount  as set \nout in the procurement contract , in order  to cover \nprofessional charges, expenses to be incurred in the \ndemolition, removal of any portion of the \nconstruction work, in the removal of debris or \nwasted materials, expenses for loss or damage \noccurred or i ncidental cost relating thereto,  \n(c) Adequate amount required for the replacement in \nthe construction site of the equipment and other \nthings brought onto the construction site by a \nconstruction entrepreneur,  \n140 \n \n(d) Every loss and damage caused t o any part or \nportion of the construction work by whatsoever \nreason other than that referred to in s ub-rule (2), \narising from the date of the handing over of the \nconstruction site till the date of issuance of the \ntaking over c ertificate to the construction  \nentrepreneur,  \n(e) The following liabilities of the construction \nentrepreneur:  \n(1) Loss and damage caused in the course \nof discharging construction \nentrepreneur's obligation during th e \ndefects liability period, and  \n(2) Loss and damage caused during the \ndefects liability period by any reason \narisen prior to the commencement o f \nthe defects liability period.  \n(2) Notwithstanding anything contained  elsewhere in this \nRegulation, the  construction entrepreneur shall not bear the obligation for \nthe loss and  damage from the insurance referred to in clause (d) of s ub-rule \n(1) caused from the following reasons:  \n(a) War, enmity or invasion,  \n(b) Rebellion, revolution, insurrection or milita ry r ule or \ncivil war,  \n(c) Ionizing radiation , radiation of nuclear fuel or nuclear \nwaste originated from the combustion of nuclear fuel or \nexplosion of radioactive toxic or explosion of other \n141 \n \nhazardous elements or nuclear assembly or pollution of \nnuclear portion thereof, and  \n(d) Pressure wave caused by an aircraft or aerial device  that \nflies at a sonic or supersonic speed .  \n(3) Except as otherwise provided  for in the procurement \ncontract, the construction entrepreneur shall bear the claims for \ncompensation  for the following loss and damage caused from the \nexecution of  construction work  or correction of any defect underlying \ntherein or resulted from such work and the costs and charges  incurred \nin the institution of action relating to such claims:   \n(a) If any person suffers injury  or dies or,  \n(b) Loss and damage caused to any property except the \nconstruction work in the course of work operation \nand comp letion.  \n(4) In procuring go ods, insurance shall be so made  from \nwarehouse to warehouse  as to cover all risks  including war, strike and \nfire of an amount equal to at  least 110 percent of the CIP (C arriages \nand Insurance Paid to) price.  \n(4a) 200 In the case of procurement of a consultancy service, \nprofessional liability insurance of the total co ntract price  covering all \nkinds of risks and payable unconditionally to the public entity shall be \nmade by the consultant not later than thirty days of the conclusion of \nthe contract . \n(5) The conditions of insura nce cannot be changed without \nwritten approval of the chief of the concerned public entity . \n \n200 Inserted by the Fourth Amendment. \n142 \n \n(6)201 If approval given to modify the conditions of insurance \ncontrary to the provisions set forth in this Rule and it results in any \nloss and damage, the employee i nvolved in the giving of such \napproval and the chief of the public entity shall be responsible \ntherefor.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "113", "title": "Provisions on payment and s ettlement  of advance : (1) 202 Advance", "content": "payment  may be made to a supplier, construction entrepreneur, \nservice provider or consultant as provided  for in the procurement \ncontract, subject to Section 52A. of the Act.  \n  (2) 203 The supplier, construction entrepreneur, service provider \nor consultant shall regularly provid e monthly statements setting out \nthe bank account to which amounts of advance paid pursuant to sub -\nrule (1) and purposes of expenses to the public entity.  \n(3) 204 In making payment of advance pursuant to s ub-rule (1), \nsuch advance payment shall be made after obtaining from the \nsupplier, construction entrepreneur, service provider or consultant  a \nbank guarantee so issued by a commercial bank that it covers such an \nadvance and is payable to that entity immediately upon a reque st \nmade by such entity  if he or she fails to perform the work  in \naccordance with the contract and a counter -guarantee issued by a \ncommercial bank within Nepal if such a bank guarantee is issued by a \nforeign bank.  \n(4) The validity period of the bank guarant ee referred to in \nsub-rule (3) shall be more than at least one month beyond such period \nwithin which the settlement of advance has to be made as set forth in \nthe procurement contract.  \n \n201 Inserted by the Sixth Amendment. \n202 Amended by the Fourth Amendment. \n203 Amended by the Fourth Amendment. \n204 Amended by the Fourth Amendment. \n143 \n \n(5) The public entity  shall deduct the advance paid pursuant \nto sub -rule (1) from e very running bill or other bill, invoice as \nprovided for in the procurement contract.  \n(6) If the advance payment referred to in this Rule cannot  be \nsettled due to failure of the suppl ier, construction entrepreneur or \nservice provider 205 to perform  the work un der the procurement \ncontract  within the period set forth in such a contract, the public entity  \nshall settle the advance by obtaining the bank guarantee amount \nreferred to in s ub-rule (3) from the concerned bank and also recover \nfrom him or her an interest at the rate of  ten percent on such advance . \n(7) The public entity  shall, while importing g oods through a \nletter of credit,  settle the advance amount applied for opening the \nletter of credit, within thirty days of the receipt of goods by  its office.  \n(8) If the concerned supplier who is to supply the goods \ncannot supply the goods or goods cannot be obtained within the time \nspecified  for their delivery , the letter of credit shall generally be \ncancelled and the advance for the opening of the letter of credit shall \nbe settled by taking back the amount collected in the bank for it .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "114", "title": "Pre-shipment i nspection : (1) If it is require d to make pre-shipment", "content": "inspection of the goods to be procured from a foreign country, the  \npublic entity  may have such inspection by appointing its agent in that \ncountry.  \n(2) In appointing an agent pursuant to s ub-rule (1),  \nappointment shall be made by following  the procedures referred to in  \nthe Act and this Regulation .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "115", "title": "Inspection and acceptance of g oods: (1) The public entity  shall inspect", "content": "or examine , or cause to be inspected or examined , whether the \n \n205 Amended by the Third Amendment. \n144 \n \nsupplied goods conform to the technical specifications and quality  set \nout in the contract  or not.  \n(2) The inspection or examination under s ub-rule (1) shall be \nmade or cause to be m ade pursuant to the prevailing law  relating to \ninspection or examination of goods, if any, and, failing such law,  in \naccordance with the procedure set forth in the procurement contract. \nIf there is no even such procedure, it shall be made in accordance with  \nsuch procedure as the public ent ity consider s appropriate.  \n(3) For the purpose of s ub-rule (1), the concerned public \nentity may, for the purpose of such inspection or examinati on, \ndesignate one or more entities or authorities  or form a committee \nconsisting of a maximum of three experts i n the field of concerned \ngoods.  \n(4) The entity, authority or committee referred to in s ub-rule \n(3) shall, while inspecting or examining the supplied goods, inspect or \nexamine the goods by comparing with the sample and  characteristics  \nkept sealed, if any, b y such public entity . In so examining those goods \nwhich are consistent with such sample and specialties shall be \naccepted and those which are not consistent with the sample and \nspecialties shall be returned back to the supplier.  \n(5) In making inspection  or examination pursuant to s ub-rule \n(4), all goods or selected sample thereof may be inspected or \nexamined , as required.  \n(6) Once the inspection or e xamination is made pursuant to \nsub-rules (4) and (5), the inspecting or examining entity, authority or \ncommittee shall prepare an inspection report containing the \ndescription of the accepted and the rejected goods. Such a report shall \ncontain the name, percentage, sp ecifications, the result of inspection \n145 \n \nor ex amination of the examined goods,  and the public entity  shall \nkeep such a report as the record of the procurement proceeding .  \n(7) If any dispute arises between the inspecting or examining \nentity, authority or committee and the supplier in in specting or \nexamining the goods pursuant to this Rule, such a dispute shall be \nsettled in accordance with the dispute settlement  mechanism as set out \nin the procurement contract.  \n(8) Notwithstanding anything contained elsewhere in this \nRule, the chief of the store section of the public entity  may take  over \nthe goods the value of which does not exceed twenty -five thousand \nrupees after making necessary inspection or examination.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "116", "title": "Auction of goods and recovery of a mount: (1) If the supplier does not", "content": "immediately  take back the goods rejected pursuant to s ub-rule (4) of \nRule 115, the public entity  shall give inform ation in writing to the \nsupplier to take back such goods within the period  specified  in the \nprocurement cont ract and supply, in lieu thereof, the goods \nconforming to  the specifications.  \n(2) If the public entity  sends the information referred to in \nsub-rule (1) by  post or courier service, it shall send a letter along with \nthe return receipt.  \n(3) If the supplier ref uses to take over the goods within the \nperiod of the notice referred to in s ub-rule (1) or does not remove the \ngoods within the period specified in the procurement contract, the \nconcerned public entity  shall sell such goods by public auction and \nreturn bac k the amount remaining  after deducting from the auction \nsale amount the cost incurred in the  storage of the goods and other \nincidental expense s related thereto, the outstanding advance amount, \nliquidated damages and also other am ount, if any, to be paid by him \nor her to the public entity .  \n146 \n \n(4) The amount that is not recovered also from the proceeds \nof the auction referred to in s ub-rule (3) shall  be recovered from the \nsupplier as government dues according to the prevailing law .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "117", "title": "Work acceptance r eport: (1) A public entity  shall, in accepting a", "content": "completed construction work, goods delivere d or services rendered, \nprepare a report thereof.  \n(2) The report referred to in s ub-rule (1) shall contain the \nfollowing matters:  \n(a) Procurement contract number,  \n(b) Details of the construction work completed, goods \nor services received,  \n(c) Date of completion of the construction work  or \nreceipt of the goods or services,  \n(d) Date of acce ptance of the construction work  \ncompleted, goods or services received.  \n(3) Once the report referred to in s ub-rule (2) is prepared, the \npublic entity  shall, upon completing the necessary process, ask, \nwithout any delay , the concerned financial administration section or \nbody for the  payment.  \n(4)206 Notwithstanding anything contained in t his Rule, no \nstructure built shall be accepted unless  it is proved, upon conducting \nexamination of appropriateness of the structure, that such structure is \nappropriate for operation in consonance with its objective.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "118", "title": "207 Procedures relating to variation : (1) If, in the course of", "content": "implementation of a procurement contract, there arises a circumstance \nthat could not be foreseen at the time of conclusion of the contract and \n \n206 Inserted by the Sixth Amendment. \n207 Amended by the Fourth Amendment. \n147 \n \nthe public entity has to issue a variation order pursuant to Section 54 \nof th e Act , the entity shall issue it upon completing the process \nreferred to in this Regulation.  \n  (2) If it is required to issue a variation order of a construction \nwork pursuant to sub -rule (1), the order shall set out the following \ndetails and be certified by the chief of public entity who has authority \nto approve such variation pursuant to Section 54 of the Act:   \n(a) Whether  the drawing, design and specifications etc. \nof the construction work need to be changed or not, \nand where such change is to be made, w hether the \nbasic nature or scope of the construction work will \nbe changed or not,  \n(b) Technical justification and reason for the variation \nquantity of work,  \n(c) If it affects the cost estimate pursuant to sub -\nsection (2) of Section 5A. of the Act,  percenta ge \nthereof,  \n(d) Whether it is included in the approved budget and \nprogram or not.  \n(3) If it is required to issue a variation order of goods or \nother service pursuant to sub -rule (1), the order shall set out the \nfollowing details and be certified by the chief of public entity who has \nauthority to approve such a variation pursuant to Section 54 of the \nAct:  \n(a) Whether the drawing, design and specifications etc. \nof the goods or other service need to be changed or \nnot, and where such change is to be made, whether \n148 \n \nthe basic nature or scope of the goods or service \nwill be changed or not,  \n(b) Technical justification and reason for the variation \nquantity , \n(c) If it affects the cost estimate pursuant to sub -\nsection (2) of Section 5A. of the Act, percentage \nthereof,  \n(d) Whether it is included in the approved budget and \nprogram or not.  \n(4) If it is required to issue a variation order of a consultancy \nservice pursuant to sub -rule (1), the order shall set out the following \ndetails and be certified by the chief of public entity who has authority \nto approve such a variation pursuant to Section 5 4 of the Act:  \n(a) Whether the scope, requirements, terms of \nreference, qualification, expertise etc. of the \nconsultancy service need to be changed or not, and \nwhere such change is to be made, whether the basic \nnature or scope of such service or proposed e xpert \nor specialist will be changed or not,  \n(b) Technical justification and reason for the variation \nquantity,  \n(c) If it affects the cost estimate pursuant to sub -\nsection (2) of Section 5A. of the Act, percentage \nthereof, and  \n(d) Whether it is included in the approved budget and \nprogram or not.  \n149 \n \n(5) In issuing a variation order pursuant to sub -rule (1), the \npublic entity  may issue such order only upon having necessary inquiry \ninto the matter by a group of experts and on the basis of the \nrecommendation by suc h a group.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "119", "title": "Price a djustment : (1) The public entity  shall set out in in the", "content": "procurement contract  that price adjustment may be made.  \n(2) In providing for the price adjustment in the procurement \ncontract, the following matters shall also be set out : \n(a) Circumstances i n which price adjustment may be \nmade,  \n(b) The formula to determine it,  \nIn determining a formula pursuant to this clause, \nthe formula shall be so determined  as to adjust the \nprice only of the labor, materials and equipment \nused in the work completed,  \n(c) Maximum amount of price adjustment,  \n(d) Component of price to be used in the formula \nunder clause (b) (the price of labor, equipment, \nmaterials, fuel etc.),  \n(e) The relevant price indices to be used to adjust each \nprice component,  \n(f) The manner of measuring the fluctuation of \nexchange rate between the currency to be used to \nmention  price ind ices and the currency to be used \nfor making payment,  \n(g) Baseline date to be taken for the application of the \nprice adjustment formula,  \n150 \n \n(h) Interval of time for the application of the price \nadjustment formula, and  \n(i) Minimum price escalation to be demonstrated by \nthe application  of the price adjustment formula and \nother conditions and restrictions to be fulfilled for \nthe application of the provision relating to price \nadjustment.  \n(3) The maximum amount of price adjustme nt to be made \npursuant to this Rule shall not generally be more than twenty five \npercent of the original  contract price . The procurement contract may \nprovide that if the amount  of price adjustment exceeds that price, the \npublic entity  may terminate the pro curement  contract or negotiate \nwith the construction entrepreneur, supplier, service provider or  \nconsultant  in order to limit the contract price within the approved \nbudget or may pursue other measures or that additional budget shall \nbe arranged.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "120", "title": "Period of procurement contract may be e xtended : (1) If the work", "content": "under the procurement contract cannot be completed within the period \nof such a contract because of the occurrence of the circumstance  set \nout in Section 56 of the Act, the concerned construction entrepreneur, \nsupplier,  service provider or consultant  shall make an application,  \nstating the reason therefor , to the concerned public entity  for the \nextension of the period, at least  twenty -one days 208 before the \nexpiration of the term of such contract.  \n  (1a) 209 Notwithstanding anything contained in sub -rule (1), in \nthe case of a procurement contract which has been concluded and of \nwhich term has expired prior to the commencement of this sub-rule, \n \n208 Amended by the Sixth Amendment. \n209 Inserted by the Seventh Amendment. \n151 \n \nthe concerned construction entrepreneur, supplier, service provider or \nconsultant shall make an application for the extension of term , not \nlater than twenty -one days of the commencement of this sub -rule. \n(2) Upon receipt of an application pursuan t to sub-rules (1) \nand (1a) ,210 the concerned competent authority may make, or cause to \nbe made, necessary inquiry in to the matter.  In so making  or causing to \nbe made inquiry , the authority  shall have regard to  the following \nmatters:  \n(a) Whether the concerned construction entrepreneur, \nsupplier, service provider or  consultant has made \nbest efforts  to complete the work under the \nprocurement contract i n time or not,  \n(b) Whether the concerned public entity  has provided  \nthe construction entrepreneur, supplier, service \nprovider or consultant  with the matters required to \nbe provided  under the contract or not , ……. 211 \n(b1) 212 Whether the delay in work has been made because \nof the  requirement  of documents pursuant to \nSection 67A. of the Act or not,  \n(c) Whether the delay in work has been made  because \nof a force majeure event or not,  \n(3)213 If, upon inquiry made pursuant to s ub-rule (2), the reason  \nreferred to in the application appears  to be reasonable, the authority \naccepting the bid may extend the term if it is required to extend the \nterm not exceeding  fifteen percent of the original period of the \n \n210 Amended by the Seventh Amendment. \n211 Deleted by the Fourth Amendment. \n212 Inserted by the Fifth Amendment. \n213 Amended by the Sixth Amendment. \n152 \n \ncontract, and the head of department may extend the term if it is \nrequired to extend the  term exceeding the said period but not \nexceeding twenty -five percent period of the term. \n(4)214 If there is a reasonable for extending the term of a period \nexceeding the period set forth in sub -rule (3), the secretary of the \nconcerned Ministry or entity  215may extend the term.  \n(5) 216 The decision on extension of the term referred to in sub -\nrules (3) and (4) shall be made within the period of the contract.  \n(6) 217 Notwithstanding anything contained in this Rule, no \nextension of term shall be so made as to exceed fifty percent of the \noriginal term of the contract.  \n218Provided that if, in the case of any procurement contract  \nconcluded  prior to  6 June 2019 ( 23 Jesta 2076 ) and for the extension \nof the period of which an application has been made, it appears on th e \nbasis of, inter alia , the technical report and upon an analysis of the \nwork progress and remaining work that  the work under the contract \ncan be completed if the period is extended , the special class or \nequivalent offi cer of the concerned Ministry or  entity  may so extend \nthe period not exceeding one year that such extension does not result \nin any additional financial burden on the public entity or project.  In \nthe case of one who fails to complete the work under the contract even \nwithin the period so ex tended, the performance security and other \nsecurity or guarantee, if any, furnished by such a person shall be \nforfeited and the loss and damage resulted from such failure to \ncomplete the work shall be recovered in accordance with the \n \n214 Inserted by the Sixth Amendment. \n215 Amended by the Seventh Amendment. \n216 Inserted by the Sixth Amendment. \n217 Inserted by the Sixth Amendment. \n218 Amended by the Eighth Amendment. \n153 \n \nprevailing law and suc h person shall be blacklisted and subject to \naction under the prevailing law.  \n(7) 219 If the term is not extended pursuant to sub-rules (3), (4) \nand (6) ,220 the contract shall be terminated.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "121", "title": "Liquidated d amages : The following provisions may be made in the", "content": "procurement contract in regard to the liquidated damages:  \n(a) If the work under the procurement contract could \nnot be completed within the time specified in the \ncontract due to the delay on the part of  the \nsupplier, consultant, service provider or \nconstruction e ntrepreneur,  he or she shall pay to \nthe public entity  liquidated damages, generally of \nzero decimal zero five (0.05) percent of the \ncontract price per day not exceeding ten percent of \nthe contrac t price; however, he or she is not \nrequired to pay liquidated damages if the \nperformance of work or delivery of go ods is \ndelayed due to the occurrence of  a force majeure \nevent or without  any fault or negligence on his or \nher part,  and \n(b) The concerned construction entrepreneur, supplier, \nservice provider or  consultant  shall not be released \nfrom the obligation of perf orming the work under \nthe procurement contract even upon payment of the \nliquidated damages referred to in  clause (a).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "122", "title": "Matters to be set out in bills or i nvoice s: (1 ) The  construction", "content": "entrepren eur, supplier, service provider  or consultant  shall set out at \n \n219 Inserted by the Sixth Amendment. \n220 Inserted by the Seventh Amendment. \n154 \n \nleast the following matter s in a running bill, any other bill or  invoice \nto be presented by him or her for payment pursuant to  this Rule:  \n(a) Date of the bill or invoice,  \n(b) Name, address of the supplier, construction \nentrepreneur, service provider or  consultant,  \n(c) Procurement contract,  \n(d) Details of the goods or services  supplied  or \nmeasurement, size, quantity and price of the \nconstruction work completed,  \n(e) Conditions of shipment and payment,  \n(f) Necessary documents to be submitted along with \nthe bill or invoice as per the procurement contract,  \n(g) In the case of procurement of goods, the bill or \ninvoice is to be accompanied by shipping or other \nrequired documents in the format prescribed by the \npublic entity , in accordance with the instructions \nprovided in the procurement order, letter of \nacceptance of bi d or procurement contract, and  \n(h) His or her contact address.  \n(2) Upon receipt of t he bill or invoice pursuant to s ub-rule \n(1), the public entity  shall examine whether the bill or invoice \nconforms to the provision s referred to in the procurement contract, \nand if it fails to so conform, the entity  shall forthwith give \ninformation thereof to the concerned supplier, construction \nentrepreneur, service provider or  consultant .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "123", "title": "Payment of b ills or i nvoices: (1) The  procurement contract may", "content": "provide that in m aking payment of a running bill or  any other bill or \n155 \n \ninvoice, the public entity  may, as per the conditions of contract, make \npayment on any  or all of the following base s:  \n(a) On monthly basis,  \n(b) On the basis of the actual work performed as \ntechnically measured and recorded in the \nmeasurement book,  \n(c) If the procurement contract sets out the work \nperformance indicator , upon achievement  of such \nindicator , and if no such indicator  is set out, on t he \nbasis of the work performed,  \n(d) On the basis of the quantity of the work handed \nover or completed, and \n(e) Pursuant to s ub-rule (1) of Rule 122 or on the basis \nof conditions of the letter of credit.  \n(2) In order to re ceive payment of a running bill or  any other \nbill or invoice, the supplier, construction entrepreneur, service \nprovider or c onsultant shall s ubmit such documents as may be \nrequired by the procurement contract.  \n(3)221 The concerned authority shall, not later than thirty (30) \ndays, approve the running bill or any other bill, invoice and \ndocuments submitted pursuant to sub -rule (1), and t he public e ntity \nshall make payment of  such a bill or invoice as per the procurement \ncontract within that period.  \n(4) The public entity  shall, in making payment pursuant to \nsub-rule (1), deduct, for retention money, five percent of the amount \nspecified in the running bill or  other bill or invoice .  \n \n221 Amended by the Third Amendment. \n156 \n \n222Provided that if the procurement contract, in view of any \nspecific nature of procurement except a construction work ,223 provides \nthat retention money is not required to be deducted, such an amount \nshall not be deducte d. \n(5) If the  procurement contract provides that where prompt \npayment of the bill or invoice is made by the public entity , the \nsupplier, construction entrepreneur, service provider or consultant  \nshall provide discount of a certain amount or percentage of such \npayment, the public entity  shall make such payment only after \ndeducting such discount . \n(6) The public entity  may provide the following  provisions  in \nthe procurement contract : \n(a) That if  amount of  payment requires to be corrected \nfor the reason that anything written in a ny previous \nrunning bill or any other bill , invoice has been  \nwritten erroneously  or otherwise , the public entity  \nmay itself or at the request of the concerned \nsupplier,  construction entrepreneur,  service \nprovider or consultant  correct or alter such amount \nof payment in the subsequent running bill s or any \nother bill s or invoices , and  \n(b) That if the supplier, construction entrepreneur, \nservice provider or  consultant  does n ot perform the \nwork in accordance with the conditions of the \nprocurement contract, the public entity  may deny \nor deduct the payment under a running bill or any \nother bill , invoice.  \n \n222 Inserted by the Third Amendm \n223 Inserted by the Sixth Amendment. \n157 \n \n(7) The public entity  shall make the payment referred to in \nsub-rule (1) wi thin the period specified in the procurement contract. If \nit does not make payment within that period, it shall pay interest \nthereon as per the procurement contract.  \n(8) While making payment  of more than twenty -five \nthousand rupees to the supplier, construction entrepreneur, service \nprovider or  consultant  ……….,224 it shall be made thr ough the  account \npayee cheque.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "124", "title": "Final p ayment : (1) Once the public entity has accepted the  work", "content": "completed as  per the procurement contract, the final payment shall be \nmade to the supplier, construction entrepreneur,  service provider or \nconsultant  as per the conditions of the contract.  \n(2) In making final payment pursuant to s ub-rule (1), in the \ncase of a construction work, the performance security and fifty \npercent amount of the retent ion money deducted pursuant to s ub-rule \n(4) of Rule 123 shall be returned after the expiry of the defects \nliability period. The remaining fifty percent amount of the retentio n \nmoney shall be paid after the concerned supplier, construction \nentrepreneur or servic e provider has submitted  documentary evidence \nshowing the  submission by him or her of tax  returns to the concerned \nInland Revenue Office .225  \nProvided that if the concerne d construction entrepreneur does \nnot rectify  the defects within the defects liability period, the public \nentity may rectify the defects by using the retention mo ney or the \namount for security.  \n \n224 Deleted by the Third Amendment. \n225 Amended by the Third Amendment. \n158 \n \n(2a) 226 Notwithstanding anything contained elsewhere in this \nRule, payment of retention money shall, in the case of a joint venture, \nbe made after the submission of document showing the submission of \ntax returns in the Inland Revenue Office.  \n(3) The procurement contract may provide that the \nconstruction entrepren eur, supplier, service provider  or consultant  \nshall, for getting the  final payment, not make any clai m other than the \nfollowing with the public entity :  \n(a) Special claim,  \n(b) The liability of the construction entrepreneur, \nsupplier, service provider or  consultant  towards a \nthird party that has arisen or may arise i n carrying \nout the procurement , and  \n(c) Claim for the reimbursement relating to the \nliability borne by the construction entrepreneur, \nsupplier, service provider or consultant in respect \nof a third party while performing the procurement \ncontract, but which has not been  claimed with the \npublic entity  and which has not been informed  in \ntime.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "125", "title": "Work completion report to be s ubmitted : (1) The concerned", "content": "construction entrepreneur s hall submit as -built drawing  to the public \nentity within thirty days of the completion of the construction work as \nper the procurement contract.  \n  (1a) 227 After the completion of the construction work as per the \nprocurement contract, if any defect is seen prior to the expiry of the \n \n226 Inserted by the Third Amendment. \n227 Inserted by the Sixth Amendment. \n159 \n \ndefects liability period of the construction work as per the contract, \nthe public entity shall  ascertain such defect and make claim in time. In \nmaking such a claim, the concerned public entity shall prepare records  \nshowing w ork progress of each month and have the records certified \nby the concerned authority.  \n  (1b) 228 The public entity shall give information of the records \nreferred to in sub -rule (1a) to the Public Procurement Monitoring \nOffice, and such records shall also be made public through the e -\nprocurement system, website of the Public Procurement Monitoring \nOffice or other appropriate means.  \n(2) The chief of  public entity  shall, after expiry of the defects \nliability period o f a completed construction work , cause such \nconstruction work to be examined by a technical employee as to \nwhether it conforms to the approved drawing, design or specifications \nand a work completion report to be prepared.  \n(2a) 229 In preparing the work completion certificate pursuant to \nsub-rule ( 2), the records referred to in sub -rule (1a) shall also be \nattached therewith.  \n(3) The technical employee making examination pursuant to \nsub-rule (2) shall examine whether the completed work has been \ncompleted as per the approved drawing, design or specifi cations or \nnot and submit a report thereof to the public entity .  \n(4) The concerned public entity  shall submit the as -built \ndrawing  referred to in s ub-rule (1) and the work completio n report \nsubmitted pursuant to s ub-rule (3) to the bid accepting authority , and \nin cases where the chief of the public entity  and the bid accepting \n \n228 Inserted by the Sixth Amendment. \n229 Inserted by the Sixth Amendment. \n160 \n \nauthority are the same person, to on e level higher authority to him or \nher.  \n(5) If the authority referred to in sub -rule (4) considers \nnecessary, he or she himself or herself may examine  the matter \nreferred to in the work completion report,  or cause the same to be \nexamined by any technical employee  or a team of technical \nemployees . \n(6) If, in making examination pursuant to s ub-rule (5), the \ncompleted construction work is fou nd to conform to the approved \ndrawing, design or specifications,  such an  authority shall accept  such \nconstruction work .  \n(7) Notwith standing anything contained in s ub-rule (6), if the \nexamination pursuant to s ub-rule (5 ) is not completed within forty-\nfive days of the date of submission of the work completion report \npursuant to s ub-rule (4 ), such construction work shall  be deemed to \nhave ipso facto  been accepted . \n(8) Notwithstanding anything contained elsewhere in this \nRule, where the work completion report submitt ed pursuant to s ub-\nrule (3) is in respect of a construc tion work the value of which does \nnot exceed one million r upees, the chief of the concerned public entity  \nmay examine it himself or herself, if he or she is a technical \nemploye e, and if he or she is not a technical employee, he or she may \ncause it to be examined by another tech nical employee.  In so \nexamining or causing to be examined, if such a construction work is \nfound to have been constructed as per the approved drawing, desi gn \nor specifications, he or she shall approve the work completion report, \nand give information of the work completion  to one level higher \nauthority.  \n161 \n \n(9) Once the wo rk completion report is accepted  pursuant to \nthis Rule, the public entity  shall issue the work completion certificate \nto the concerned construction entrepreneur.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "126", "title": "Reward may be given to those who complete work prior to t ime: (1) It", "content": "may be provided that the p ublic entity  may reward the construct ion \nentrepreneur who completes the  work prior to the  period  specified in \nthe procurement contract.  \n(2) The amount of reward referred to in s ub-rule (1) shall  be \ndetermined on the basis of s ub-rule (3) for such a number of days by \nwhich the work was completed before the  period specified in  the \nprocurement contract.  \n(3) While determining the rate referred to in s ub-rule (2), the \nrate shall be so determined as equivalent to the same amount that the \nconstruction entrepreneur has to pay as liquidate damages to the \npublic entity  on daily basis for failure to complete the work within the \nperiod specified in the procurement contract.  \n(4) Notwithstanding anything contained elsewhere in this \nRule, the total amount of reward shall not exceed te n percent of the \ncontract price .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "127", "title": "Payment to be m ade in case of t ermination of procurement c ontract on", "content": "ground of convenience : (1) Where the p ublic entity  has terminated the \ncontract on the ground  of convenience f or public interest pursuant to \nsub-section (4) of Section 59 of the Act, it shall pay the following \namount to the concerned supplier, construction entrepreneur, \nconsultant or servi ce provider.  In making  such payment , payment \nshall be made only after deducting the advance  amount, if any, paid to \nhim or her:   \n162 \n \n(a) Payment of the amount, if any,  due and payable for the \nwork, supply or service that has been completed acceptably, \n(b) The price of the goods manufactured for the purpose \nof the public entity  as per the procurement contract, \nconstruction materials brought onto the constr uction \nsite,  \n(c) A reasonable cost to be incurred for the removal of \nequipment from the construction site,  \n(d) Repatriation expense for expatriate employees \nemployed only in the construction work, and  \n(e) If necessary, cost for safety and  protection of the \nconstruction work.  \n(2) Notwithstanding anything contained in s ub-rule (1), the \npublic entity  shall accept the goods prepared and to be prepared for \nshipment within seven days of the receipt by the supplier of the notice \ngiven by it for termination of the procurement contract on the ground of \nconvenience subject to the conditions and price of such a contract.  \n(3) In respect of the goods other than those ref erred to in s ub-\nrule (2), the public entity may do the following: \n(a) To get any p ortion of the goods to be completed and \nobtain the same on the conditions and at the price set \nout in the procurement contract, or  \n(b) To c ancel the supply order of remaining goods, and \nmake payment of an amount agreed by mutual \nconsent to the supplier for the goods or services \npartially prepared by him  or her and materials or \nspare parts purchased by him  or her prior to \ntermination of contract. \n163", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "128", "title": "Remedies to be available in event of b reach of  procurement contract :", "content": "(1) The procurement contract shall contain a provision of remedy to \nbe available to the public entity  in the event of breach of the \nprocurement contract by the supplier, construction entrepreneur, \nconsultant or service provider.  \n(2) The remedy referred to in  sub-rule (1)  may be as follows,  \nin addition to the remed y referred to in Section 59  of the Act:  \n(a) To reject a defective work,  \n(b) To remov e the defective goods  at one  and to cause the \nconcerned supplier, construction entrepreneur, consultant \nor service provider to replace them,  \n(c) To obtain liquidated damages for the failure  to complet e \nthe work in time,  \n(d) To terminate the contract and to have such work \ncompleted a t the cost of the supplier, construction \nentrepreneur, service provider or consultant  who has not \nperform ed the work under the contract,  \n(e) To recover consequential damages,  \n(f) Other remedies to be available under the prevailing law \nor the procurement contract.  \nChpater -12 \nProvision s Relating to Dispute Resolution", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "129", "title": "230 Dispute resolution : (1) The procurement contract  shall set forth , inter", "content": "alia, the matters of dispute to be resolved through mutual consent, \nprocess for making application for the settlement of a dispute, \n \n230 Amended by the Fourth Amendment. \n164 \n \nmeeting to be held for mutual consent and process of making \ndecisions, and such a dispute shall be settled accordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "130", "title": "231 ……..", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "131", "title": "232 ……..", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "132", "title": "233 ……..", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "133", "title": "234 ……..", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "134", "title": "235……..", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "135", "title": "236 Resolution of d ispute by a rbitration : If any dispute that has arisen", "content": "between the public entity and the construction entrepreneur, \nconsultant or service provider in relation to the implementation of the \nprocurement contract cannot be resolved through the process referred \nto in Rule 1 29,  action sh all be initiated for the resolution of such a \ndispute by arbitration in accordance with the prevailing law.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -13", "title": "Chapter -13", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "136", "title": "Documents relating to procurement proceeding  to be provided : If the", "content": "entity competent to carry out audit, monitor ing, investigat ion or \ninspect ion under the prevailing law  asks for any document relating to \nprocurement proceeding , the concerned public entity  shall provide  \nsuch documents within a reasonable time.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "137", "title": "Public notice of procurement contract : (1) 237The concerned public", "content": "entity shall, not later than three days of the conclu sion of the  \n \n231 Repealed by the Fourth Amendment. \n232 Repealed by the Fourth Amendment. \n233 Repealed by the Fourth Amendment. \n234 Repealed by the Fourth Amendment. \n235 Repealed by the Fourth Amendment. \n236 Amended by the Fourth Amendment. \n237 Amended by the Sixth Amendment. \n165 \n \nprocurement contract, put in the electronic procurement system of the \nPublic Procurement Monitoring Office a notice containing the name, \naddress of the contracting party, work under the contract, objective, \namount, period and other necessary de tails with respect to \nprocurement with the following cost estimate:  \n(a) Other service and goods exceeding two million \nrupees,  \n(b) Consultancy service exceeding two million rupees,  \n(c) Public construction work exceeding twenty million \nrupees.  \n(2)238 The concerned public entity  shall make arrangements for \nputting the description referred to in s ub-rule (1) on its website, if \nany, and also affixing  the same on the notice -board of the District \nCoordination Committee, District Administration Office, Province \nComptroller General Office, District Treasury Controller Office and \nalso of the concerned Local Level.  \n(2a) 239 The concerned  public entity shall so display the notice \nreferred to in sub -rule (2) on a notice board at the construction site in \nthe case of a construction work that it is conspicuous to all.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "138", "title": "Consultant to avoid conflict of interest : (1) The consultant shall", "content": "provide professional, objective and impartial consultancy service in a \nmanner to serve the  best interest s of the public entity  taking \nconsultancy service.  \n(2) The consultant shall,  while providing the consultancy \nservice, not so serve as  to conflict interest with his  or her other \npresent or future work.  \n \n238 Amended by the Sixth Amendment. \n239 Inserted by the Sixth Amendment. \n166 \n \n(3) If the nature of the work relating to consultancy service is \nof the type of conflicting interest with his  or her past or present \nobligation towards any other client or of preventing h im or her from \ncomplet ing the work as to serve the best interest s of the concerned \npublic entity , he or she may not be appointed as a consultant.  \nExample : A consultant who is appointed for the preparation of \nengineering design of a project cannot be appointed as a consultant \nfor environmental assessment  of the same project or a consultant \nrelating to privatization of any government owned body cannot be \nappointed as a consultant of the person pur chasing such property nor \npermission can be granted to him  or her or his or her near relative or \nthe partner of his  or her organization to procure such property.  \nProvided that this provision shall not appl y to a turn key \ncontract or design and construction  contract.  \n(4) No firm supplying goods or executing  construction works \nfor a ny project  and other body or person associated with it may \nprovide consultancy service for the same  project , and no consultancy \nfirm appointed for the preparation or implementatio n of a project and \nany other  body or person association with it may supply goods for \nsuch a project.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "139", "title": "Information  as to inducement, corruption or fraudulent practice : If any", "content": "official of the public entity  is offered any inducement by a bidder or \nproponent or has the knowledge of the commission of any corrupt or \nfraudulent practice,  he or she shall give information thereof to the \nchief of such an entity or the Public Procurement Monitoring Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "140", "title": "Power to make s upervision and examinatio n: The superior office may", "content": "from time to time make supervision and examination as whether the \nofficial involved in the procurement proceeding  has complied with the \nprocedures referred to in the Act or this Regulation.  \n167", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "141", "title": "Blacklisting : (1) If it is require d to blacklist a ny bidder, proponent,", "content": "consultant, service provider, supplier, construction entrepreneur or \nother person, firm, organization or company pursuant to Section 63 of \nthe Act, the public entity  shall send a request in writing , along  with \nthe relevant details and the reason , as well as the  relevant document s, \nto the Public Procurement Monitoring Office.  \n(2)240 Upon receipt of the request pursuant to sub-rule (1), if, in \nexamining such details, reasons and documents, it appears that such a \nbidder, proponent, service provider, consultant, supplier, construction \nentrepreneur or other person, firm, organization or c ompany has to be \nimmediately prevented from participating in public procurement, the \nPublic Procurement Monitoring Office may so prevent from \nparticipating in new procurement  proceeding  until the process for \nblacklisting referred to in this Rule is complet ed. \n(3) If the Public Procurement Monitoring Office decides to \nprevent  pursuant to sub-rule (2), it shall give information  thereof to \nthe concerned bidder, proponent, consultant, service provider, \nsupplier, construction entrepreneur or other person, firm, organization \nor company and publish a notice publicly , within seven days of such a \ndecision.  \n(4) Upon receipt of the request pursuant to sub-rule (1), \nexcept in cases where prevention  is to be made immediately pursuant \nto sub-rule ( 2),241 the Public Procurement Monitoring Office shall \nsend a notice in writing  of thirty days , accompanied by a copy of the \nstatement, reason and document so received  to the  office or house of  \nthe concerned bidder, proponent, consultant, service provider, \nsupplier, construction entrepreneur or other person, firm, organization \n \n240 Amended by the Sixth Amendment. \n241 Amended by the Sixth Amendment. \n168 \n \nor company,  requiring him or her to  submit the grounds and \nclarification, if any, for not blacklist  him or her.  \n(4a) 242 If he or she is not found upon sending the written notice \nreferred to in sub -rule (4) to his or her office or house, ………. 243 a \npublic notice to that effect shall be published in a newspaper of \nnational circulation, and such a notice shall be deemed to have been \ngiven if the notice is so published.  \n(5) Upon receipt of the notice pursuant to  sub-rule (4), the \nconcerned bidder, proponent, consultant, service provider, supplier, \nconstruction entrepreneur or other person, firm, organization or \ncompany shal l submit to the Public Procurement Monitoring Office , \nclarificatio n, together with relevant documents, setting out the  reason \nand ground, if any, for not blacklisting.  \n(6) The concerned bidder, proponent, consultant, service \nprovider, supplier, construction  entrepreneur or other person, firm, \norganization or company may,  in submitting explanation pursuant to \nsub-rule (5), request the Public Procurement Monitoring Office that \njoint hearing be conducted in the presence of him  or her and the \nconcerned public en tity. \n(7) Where a request is made pursuant to sub-rule (6) for \nhearing and the Public Procurement Monitoring Office considers it \nappropriate to  conduct such hearing, it shall give a written notice as to \nthe time and place of such hearing to the concerned public entity  and \nthe bidder, proponent, consultant, service provider, supplier, \nconstruction entrepreneur or other person, firm , organization or \ncompany.  \n \n242 Inserted by the Fourth Amendment. \n243 Deleted by the Sixth Amendment. \n169 \n \n(8) The public entity  and the bidder, proponent, con sultant, \nservice provider, supplier, construction entrepreneur or other person, \nfirm, organization or company  receiv ing the notice referred to in  sub-\nrule (7) shall appear before the Public Procurement Monitoring Office \nwithin the period specified in that sub-rule.  \n(9) If both parties appear within  the period referred to in s ub-\nrule (8), the Public Procurement Monitoring Office shall provide both \nthe parties with an opportunity to present their respective written or \noral explanation and statement . \nProvided  that the hearing shall not be adjourned for the sole \nreason that any party has not appeared.  \n(10) The Public Procurement Monitoring Office shall, in \nconsideration of, inter alia,  the hearing , if any,  conducted  pursuant to \nsub-rule (9) , and failing such hearing, on the basis of the documents \nsubmitted by the public entity  and the concerned bidder, proponent, \nconsultant, service provider, supplier, construction entrepreneur or \nother person, firm, organization or company , make a decision to or \nnot to blacklist him or her.  \n(11) Where the Public Procurement Monitoring Office, while \nmaking a decision pursuant to sub-rule (10), decides to blacklis t him \nor her , it shall give information  thereof  in writing to the concerned \npublic entity  and the bidde r, proponent, consultant, service provider, \nsupplier, construction entrepreneur or other person, firm, organization \nor company and publish it in a newspaper of national circulation.  \n(12) Where the Public Procurement Monitoring Office, in \nmaking a decision pursuant to sub-rule (11), decides not to blacklist, \nthe prevention , if any,  made pursuant to sub-rule (2) shall, ipso facto , \nbe removed and the O ffice shall publicly publish  the matter  to that \neffect.  \n170 \n \n(13) Where a decision is made pursuant to sub-rule (10) to \nblacklist a bidder, proponent, consultant, service provider, supplier, \nconstruction entrepreneur or other person, firm, organization or \ncompany  who has been prevented  pursuant to sub-rule (2), the time of \nblacklisting shall be computed from the date on which such a \nprevention  has been  made.  \n(14) The Public Procurement Monitoring Office shall \ncomplete the  proceeding  of blacklisting pursuant to this Regulation \nwithin six months of the receipt of the reque st relating thereto.  \n(15) If any public entity  has blacklisted or decided to blacklist \na bidder, proponent, consultant, service provider, supplier, \nconstruction entrepreneur or other person, firm, organization or \ncompany prior to the commencement of this Regulation, such an \nentity shall  send information th ereof to the Public Procurement \nMonitoring Office within thirty days of the commencement of this \nRegulation.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "142", "title": "To r elease from blacklist : (1) The Public Procurement Monitoring", "content": "Office shall  prepare criteria for releasing from blacklist the bidder s, \nproponents, consultant s, service provider s, supplier s, construction \nentrepreneur s or other persons, firms, organizations or companies who \nare blacklist ed pursuant to Section 63 of the Act.  \n(2) If, pursuant to the criteria referred to in sub -rule (1),  any \nblacklisted bidder, proponent, consultant, service provider, supplier, \nconstruction entrepreneur  or other person, firm, organization or \ncompany has to be released from blacklist, the Public Procurement \nMonitoring Office shall release him or her pursuan t to the criteria.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "143", "title": "Records to be kept: The Public Procurement Monitoring Office shall", "content": "keep in its office and web -site the updated records of preventing \nbidders, proponent s, consultant s, service provider s, supplier s, \n171 \n \nconstruction entrepreneur s or other person s, firm s, organization s or \ncompanies from participating in the procurement proceeding , ipso \nfacto release from such prevention,  blacklisting and releas ing from the \nblacklist.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -14", "title": "Chapter -14", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "144", "title": "Functions, duties and powers of Public Procurement Monitoring", "content": "Office: The functions, duties and powers of the Public Procurement \nMonitoring Office  shall, in addition to the functions, duties and \npowers referred to in Section 65 of the Act, be as follows:  \n(a) To monitor the public procurement activities by \nmaking observation visit of procurement \nproceeding s of the concerned public entit ies or by \nasking report s and information relating to \nprocurement activities from public entities,  \n(b) To give direction to public entities in respect of the \ninformation, data to be incorporated in the report \nrelating to procurement activities and the period of \nsubmitting such a report,  \n(c) To operate such kinds of programs that assist  \npublic entities in conduct ing procureme nt activities  \nand bidder s, proponent s, sealed quotation bidder s, \nsupplier s in participat ing in procurement \nproceeding ,  \n(d) To simplify and facilitate procurement proceeding , \n(e) To maintain records of the performance of work \nrelating to contract implementation by establishing \na central data bank,  \n172 \n \n(f) To develop the methods of disseminating \ninformation relating to public procur ement,  \n(g) To conduct study, research on policy, law, \nexperience, practice relating to procurement  \nproceeding  of other countries, in order to improve \nthe public procurement system,  \n(h) To prepare a plan fo r management of  employees \nhaving capability or exp ertise and professional \nefficiency in procurement in public entities,  \n(i) To ascertain whether the persons to be appointed to \nthe procurement unit s of public entities, evaluation \ncommittee s and the Public Procurement \nMonitoring Office have acquired necess ary \nprofessional efficiency as per the plan  referred to \nin clause (h),  \n(j) To prepare the description of the functions, duties, \nand powers and responsibilities of the chief of \npublic entity, employees of the procurement unit of \nsuch entity and member of the evaluation \ncommittee,  \n(j1) 244 To monitor implementation of decisions of the  \nreview committee and submit a report thereof to \nthe Office of the Prime Minister and Council of \nMinisters,  \n(k) To render assistance to conduct training programs \nrequired to enhance the professional skill of the \n \n244 Inserted by the Fourth Amendment. \n173 \n \nemployee engaged in the procurement activiti es of \nthe Public entities, and  \n(l) To conduct training program required for \nenhancing professional expertise of employees.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter -15", "title": "Chapter -15", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "145", "title": "Provision concerning procurement in special circumstance : (1) A", "content": "public entity  shall, in making procurement pursuant to Section 66 of \nthe Act, prepare written details of the procurement requirements, \nquality, quantity,  conditions and period for the  completion of work \nand shall procure only the quantity and for the period required to  face \nthe emerging  circumstances by having competition made as far as \npracticable or by concluding negotiations for fair and proper price \nafter receiving written quotation or proposal from a single \nconstruction entrepreneur,  supplier, consultant or service  provider.  \n(2) Where procurement has been made pursuant to sub-rule \n(1), the documents  setting out  the following matters shall be kept in \nthe records referred to in Rule 149:  \n(a) Description relating to special circumstances,  \n(b) The crisis  that may occur  in public security, \ninterest and community health, if procurement is \nnot made immediately,  \n(c) The r eason and ground why t he other methods of \nprocurement  cannot be applied.   \n(3) Where a Public entity  has made a procurement \nexceeding one million Rupees pursuant to sub-rule (1) it shall \npublish a public notice of the details of the procurement so \n174 \n \nmade and send information thereof to the Public Procurement \nMonitoring Office.  \n(3a) In cases where the office referred to in sub -rule (1) \nhas not been established, the central level public entity referred \nto in sub -clause (1) of clause (b) of Section 2 of the Act may \nprocure essential pharmaceuticals  and such  Masalanda  or \nstationery required for the operation of the office through open \nbidding. Model of the bidding documents  relating to such \nprocurement proceeding  and framework  contract shall be as \napproved by the Public Procurement Monitoring Office.   \n145A. 245 Establishm ent of government procurement service office : (1) \nNotwithstanding anything contained elsewhere in this \nRegulation, the Government of Nepal may establish a \ngovernment procurement service office at the central level in \norder to ass it the public entities referred to in sub -clause (1) of \nclause (b) of Section 2 of the Act in selecting suppliers and \nprocuring goods.  \n  (2) The public entities referred to in sub -clause (1) of \nclause (b) of Section 2 of the Act shall, in understanding with \nthe governme nt procurement service office established pursuant \nto sub -rule (1), procure such goods as specified by the \nGovernment of Nepal by a notification in the Nepal Gazette \nfrom such suppliers as selected by that office.  \n  (3) The functions of the office establis hed pursuant to \nsub-rule (1) shall be as follows:  \n(a)  To collec t procurement requisitions along with \ndescription relating to the type, quality, quantity of \n \n245 Inserted by the Third Amendment. \n175 \n \nthe goods, time when goods will be required and \nbudget provision from the public entities referred \nto in sub -clause (1) of clause (b) of Section 2 of the \nAct and make understandings with such entities,  \n(b) To analyse procurement requisitions and prepare \nspecification of goods, cost estimate and bidding \ndocuments,  \n(c) To invite bids and select suppliers,  \n(d) To give notice to the concerned public entities to \nmake procurement in accordance with the \nprocurement terms concluded with the suppliers.  \n(4) The Public Procurement Monitoring Office shall issue \nseparate procurement guidelines for the operation of go vernment \nprocurement service.  \n(5) Notwithstanding anything contained elsewhere in this \nRule, if the market price is cheaper than the price determined by the \noffice established pursuant to sub -rule (1), nothing contained in this \nRule shall bar procurement f rom the market.  \n145B. 246 ………. 247", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "146", "title": "248 Use of electronic communication means: (1) The Public Procurement", "content": "Monitoring Office shall, for the purpose of Section 69 of the Act, \nestablish, operate and man age the electronic procurement system in a \nmanner that it has only one portal.  \n (2) …….. 249 \n \n246 Inserted by the Sixth Amendment. \n247 Repealed by the Seventh Amendment. \n248 Amended by the Fourth Amendment. \n249 Deleted by the Sixth Amendment. \n176 \n \n(3) A public entity  shall conduct procurement proceeding  \nupon being registered in the electronic procurement system \nestablished pursuant to sub -rule (1).  \n(4) The Public Procurement Monitoring Office shall, from \ntime to time, issue procedures, system of procurement through the \nelectronic procurement system and its inherent principles.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "147", "title": "Evaluation committee : The formation of the evaluation committee", "content": "referred to in Section 71 of the Act shall be as follows : \n(a) The chie f of the public entity or a senior \nofficer designated by him or her (a \ntechnical employee as far as possible)  \n-Chairperson  \n(b) Chief of the financial administration \nsection of the concerned public entity  \n-Member  \n(c) Technical expert concerned with the \nsubject matter (officer level as far as \npossible)  \n-Member  \n(d) Law officer of the public entity, where \nsuch a position exists in that public entity  \n-Member  \n (2) The chief of the procurement unit shall act as the \nsecretary of the committee referred to in sub-rule (1).  \n(3) The evaluation committee referred to in sub-rule (1) may, \nwith the approval of the chief of public entity , invite at its meeting a \nsubject  expert of the governmental or non -governmental sector.  \n(4) If the committee referred to in sub-rule (1) requires the \nassistance of a consultant, the public entity  may, subject to the \n177 \n \napproved program and budget, appoint a consultant by application of \nthe proce dure set forth in the Act and this Regulation.  \n(5) The committee referred to in sub-rule (1) may form a \nsub-committee to assist it in evaluati ng quotation s, bids or proposal s.  \n(6) The secretary of the evaluation committee shall prepare \nminutes of the meeting  of the committee  and keep a file  containing all \nmatters discussed in the meeting.  \n(7) The evaluation committee may determine its procedure s \non its own . \n(8) The evaluation commit tee shall submit an evaluation \nreport to the chief of the public entity  as provided for in this Rule.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "148", "title": "Rate fixation committee : (1) 250 There shall be a rate fixation", "content": "committee consisting of the following members  in each district  in \norder to fix the rate  of construction materials and  transportation , rent \nof machine s and equipment and the wage s of workers  to be applicable \nto the whole or any part of the district:  \n(a) Chief District Officer  -Chairperson  \n(b) One member of the District Coordination \nCommittee designated by the District \nCoordination Committee  \n-Member  \n(c) District Coordination Officer  -Member  \n(d) Chief, Treasury Controller Office  -Member  \n(e) Representative, Nepal Federation of \nConstruction Entrepreneurs  \n-Member  \n \n250 Amended by the Sixth Amendment. \n178 \n \n(f) Representative, Chamber of Commerce \nand Industry  \n-Member  \n(g) Chief, District Technical Office  \n \n-Member -\nsecretary  \n (2) The rate fixation committee shall  fix the rate of \nconstruction materials or transportation on the basis of the prevailing \nmarket rate. T he rate to be so fixed shall  be fixed within the last day \nof the month of Shrawan (mid July).  \nProvided that where the rate of construction materials or  \ntransportation  increase s in any fiscal year by more than ten percent of \nthe existing price, the committee may fix the rate accordingly.  \n(2a) 251 The rate shall be fixed pursuant to this Rule on the basis \nof, inter alia, the rate fixed by the rate fixation committee of the \ndistrict adjoining its boundary with that district.  \n(3) The rate fixation committe e shall  each year  also fix the \nrate of transportation of the means of transportation  in use in the \ndistrict.  \n(4) The concerned Chief District Officer shall send a notice \nof the rate fixed pursuant to this Rule to all offices in his  or her \ndistrict and give  an intimation  thereof to the Public Procurement \nMonitoring Office, Auditor General's Office and concerned Treasury \nController Office.  \n(5) The rules of procedure s of meeting of the meeting of the \nrate fixation committee shall be as determined by the committee itself.  \n \n251 Inserted by the Sixth Amendment. \n179", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "149", "title": "Records of procurement proceeding : (1) A public entity  shall maintain", "content": "a separate file for each procurement proceeding . \n(2) The public entity  shall keep, inter alia , the following \ndocuments in the file referred to in sub-rule (1):  \n(a) Index of the contract file,  \n(b) Notice on the invitation to bid or prequali fication,  \n(c) Documents relating to invitation to bid, pre -\nqualification or proposal,  \n(d) Request made by the bidder for clarification with \nrespect to the bidding documents, prequalification \ndocuments or proposal , and the answers sent by the \npublic entity  in respect thereof to all participating \nbidders or proponents,  \n(e) Minute of the pre -bidding conference held with the \nbidders or consultant s and the evidence  that the \npublic entity  has sent the copy of such minut e to all \nparticipating bidders or proponents,  \n(f) Minute of the opening of bids,  \n(g) Original copy of the bid,  \n(h) Questions asked to the bidder s or proponent s by \nthe bid evaluation committee in the course of bid \nevaluation and the answers sent by the co ncerned \nbidders or proponent s to the public entity , \n(i) Report of evaluation of the qualifications of the \npre-qualified bidder s, \n(j) List of the pre -qualified bidders,  \n(k) If negotiation  was held, minute s thereof,  \n180 \n \n(l) Copy of the preliminary notice of acceptance sent \nto the successful bidder,  \n(m) Copy of the notice sent to the unsuccessful bidders,  \n(n) All notices published in respect of procurement,  \n(o) Application made to  the chief of public entity  and \nthe review committee , and the opinion, comment \nand information submitted by the concerned public \nentity in respect thereof and decision made on it,  \n(p) Procurement contract,  \n(q) Documents relating to implementation of the \nprocurement contract such a s progress report, \ninvoice and inspection report,  \n(r) In the event of amendment to the procurement \ncontract , document relating thereto,  \n(s) Documents concerning receipt, inspection and \nacceptance of goods,  \n(t) All correspondences made with the construction \nentrepreneur, supplier, consultant or service \nprovider,  \n(u) Request made by the sub-contractor and answer \ngiven by the public entity  in respect thereof,  \n(v) Evaluation report and all documents relating \nthereto, and  \n(w) Documents relating to actions  taken to resolve \ndispute relating to the procurement contract.  \n181 \n \n(3) The record s referred to s ub-rule (1) shall be kept safely \nfor up to at least seven years of the completion of the procurement \nproceeding . \n(4) The records under this Rule shall be ke pt in the format \nspecified, if any, by this Regulation , if it is not so specified, in the \nformat as specified by the Public Procurement Monitoring Office.  \n(5) In keeping the records pursuant to this Rule, the Public \nentity shall keep records of every physical property.  \n(6) In keeping the records  pursuant to  rule (5), if the value of \nthe property exceeds five million rupees, the records shall state the \ndetails of such property along with its cost price, depreciation and \nmaintenance cost.  \n(7)252 After the implementation of the contract of procurement \nto be made through bidding, the public entity shall certify short \ndescription on the completion of that work and make it public by \nputting it on the website of the concerned publi c entity or Public \nProcurement Monitoring Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "150", "title": "Delegation of authority : (1) No power conferred by the Act and this", "content": "Regulation to amend the cost estimate, amend  the procurement \ncontract, extend the term of the procurement contract and issu e a \nvariation order may be delegated.  \n(2) Except the powers referred to in sub-rule (1), other \npowers conferred by this Regulation may be delegated by the \nauthority competent to exercise those powers to any officer \nsubordinate to him  or her.  \n(3) The authorit y delegating power pursuant to sub-rule (2) \nshall remain responsible in relation to  the powers so delegated.  \n \n252 Inserted by the Fourth Amendment. \n182 \n \n(4) The authority delegating power pursuant to sub-rule (2) \nshall obtain necessary information on the work carried out as per the \npower delegated by him  or her  from the concerned authority  from \ntime to time.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "151", "title": "To specify f ormat: The Government of Nepal may, on", "content": "recommendation of the Public Procurement Monitoring Office,  and by \na notification published in the Nepal Gazette, specify a format of any  \nmatter referred to in  this Regulation including that of the cost estimate \nof goods, cost estimate of consultancy service, cost estimate of other \nservice.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "152", "title": "Change or alteration in schedule s: The Government of Nepal may, by", "content": "a notification published in the Nepal Gazette, make necessary change \nor alteration in schedule s.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "153", "title": "Repeal and saving: (1) Chapters 7, 8, 13 and 17 of the Financial", "content": "Administration Regulation, 1999 are hereby repealed.  \n(2) Any acts and acti ons performed under the provisions \nrepealed pursuant to sub-rule (1) shall be deemed to have been \nperformed  under this Regulation.  \n253Schedule -1  \n(Relating to sub-rule (7) of Rule 10)  \nMethod of finding out cost estimate of construction work  \n(a) Method of finding out the rate of item:  \n Labor cost …………………………… (a)  \n Cost of construction materials …………………………… (b)  \n Machine, equipment fare (inc luding  oil and lubricants ) ……… (c)  \n \n253 Amended by the Sixth Amendment. \n183 \n \n  Rate of item (a + b+ c) = (d)  \n  Bidder’s o verhead  (15 percent of d) =0.15 (d)  \n  Total rate (e) = 1.15 (d)  \n(b) Method of finding out the cost estimate:  \nSN Item Unit Total rate \nof item  \nTotal \nquantity of \nitem \nTotal cost \nof item", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Item (1)   (f) (k) (f) X(k)", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Item (2)   (g) (l) (g) X(l)", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "Item (3)   (h) (m) (h) X(m)", "content": "Total= ( w)= (f x k + g x l + h x m +... .....) \nWork chart staff cost - by 2.5 percent of ( w)=0.025 x ( w) \nOther small cost s- by 2.5 percent of (w)=0.025 x (w)  \nTotal cost estimate figure  (p) =1.05 x ( w) \nNote: \n(a) In comparing the bid figure, figure ( w) shall be taken as the \ncost estimate figure.  \n(b) After the cost estimate has been prepared as stated above, cost \nestimate shall be fixed  by adding, according to the need, ten \npercent for price adjustment contingency  and ten percent for \nphysical contingency  to the total cost of project/program . \n(c) Procedure on w ork charge, staff expense, other petty expense \nand physical consultancy cost  has to  be approved by the \nconcerned Ministry or central entity.  \n184 \n \n(d) For the purpose of approval of the cost estimate of a \nproject/program and selection of the procurement method, the \ntotal cost estimate shall be found out by adding value -added tax \nand various contingencies to the addition (a).  \n  \n185 \n \nSchedule -1A. 254 \n(Relating to sub -rule (4) of Rule 12)  \nFormat of cost estimate of consultancy service  \n \nHeading of service \nexpenses (a)  \nUnit \n(b) \nRate of per \nunit of \nheading (c)  \nTotal \nquantity of \nheading (d)  \nTotal cost of \nheading (e)  \nHeading (1)  \nRemuneration of \nhuman resource (e1)  \nHeading (2)  \nReimbursable \nexpenses including \nvisit, accommodation \nor equipment or \nservice (e2)  \nHeading (3)  \nOther miscellaneous \nexpenses including \ntraining, symposium, \ndocument printing or \ntranslation (e3)  \n   (e1)= (c x d)  \n \n \ne2= (c x d)  \n \n \n \n \ne3= (c x d)  \nTotal cost estimate \n(f) \n   (f)= (e1+e2+e3)  \nOffice management \nexpense (four \npercent) (g)  \n   (g)=(f x 0.05) \n \nNote: \n(a) The total estimate figure for the comparison of bids shall be (f).  \n \n254 Amended by the Sixth Amendment. \n186 \n \n(b) Detail description of the remuneration expense (e1), reimbursable \nexpense (e2) and other miscellaneous expense (e3) shall be \nprepared and presented along this cost estimate form.  \n(c) After preparing the cost estimate as above, the total cost estimate \nshall be found out by adding amounts by ten percent for price \nadjustment contingency, by ten percent for various taxes and \nvalue-added tax to the total cost estimate, as per  the need, for \nbudget management.  \n(d) For the purposes of approving the cost estimate of the consultancy \nservice and selecting the procurement method, the total cost \nestimate shall be the estimate to be found out by adding value \nadded tax and various contingen cies and office management \nexpense to addition (f).  \n(e) Procedure on making office management expense has to be \napproved by the concerned or central entity and expense made \naccordingly.  \n  \n187 \n \n \nSchedule -2 \n(Relating to clause ( f)255 of sub-rule (3) of Rule 16)  \nGovernm ent of Nepal  \n......................Ministry  \n.....................Office  \nLedger of l etter of credit  \nLedger page No.  \nS\nN \nNa\nme \nof \nthe \nfirm \nfor \nwhi\nch \nlette\nr of \ncred\nit to \nbe \nope\nned \nNum\nber \nand \ndate \nof \nlette\nr of \ncredi\nt \n \nAmo\nunt \nSubj\nect \nPeri\nod \nNam\ne \nand \naddr\ness \nof \nthe \nban\nk \nwhe\nre \nlette\nr of \ncred\nit is \nope\nned \n \nDat\ne of \nclos\ning \nDate \nof \nexten\nsion \nof \nterm \nDat\ne \nwh\nen \nclos\ned \nAdva\nnce \nacco\nunt \npage \nNo. \nOrigin of \ngoods  \nRem\narks \n           Cou\nntry \nDate \nof \nprodu\nction \nand \n \n \n255 Amended by the Fourth Amendment. \n188 \n \nmodel  \n              \n \nEntry made by: Name and surname:     Certified by:  \nName and surname :     Name and surname:   \nSignature:        Signature:  \nDate:        Date: \n  \n189 \n \nSchedule -2A. 256 \n(Relating to sub -rule (1) of Rule 18)  \nFormat of application to be made for being registered in the standing list  \nDate: \nTo the chief of office,  \n…….office,  \n………. \nSubject: Application for being registration in the standing list . \nI hereby submit this application for being registering with the standing list, \nattaching herewith the documents establishing the following details, \npursuant to sub -rule (1) of Rule 18 of the Public Procurement Regulation, \n2007 (2064).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Details of the person, organization, supplier, construction", "content": "entrepreneur, consultant or service provider making application for \nthe standing list  \n(a)Name:  (b) Address  \n(c) Address for \ncorrespondence  \n(d) Name of main person:  \n(e) Telephone No.  (f) Mobile No.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Please, attach the following certificate for being registered in the", "content": "standing list  \n(a) Whether you have the association or firm registration \ncertificate: Yes.  No.  \n \n256 Inserted by the Fourth Amendment. \n190 \n \n(b) Whether it is renewed: Yes.  No.  \n(c) Whether you have the value added tax or permanent account \nregistration certificate: Yes.   No.  \n(d) Whether you have the tax clearance certificate: Yes.   No.  \n(e) Whether you have a copy of the license , if any, required for \nthe procurement for which have applied for being registered in \nthe standing list: Yes.  No.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "De scription of nature of procurement to be made by the public", "content": "entity for which the applicant wishes to be registered:  \n(a) Supply of goods (also \nmention nature of goods)  \n(b) Construction work  \n(c) Consultancy service (also \nmention the nature of \nconsultancy service)  \n(d) Other service (mention the nature \nof other service)  \nDate when \napplication \nmade: \nFiscal year:  \nSeal of the \nfirm: \n Applicant’s:  \nName: \nSignature:  \n \n  \n191 \n \nSchedule -2B. 257 \n(Relating to sub -rule (2) of Rule 18)  \n \nFormat of evidence of being registered in the standing list  \nGovernment of Nepal  \n…….Ministry  \n……..Department  \n……………………….office,  \n………………….  \nEvidence of being registered in the standing list . \nCertificate No.:  \nList registration No.:  \nWhereas, an application has been received from ……………… by this \noffice on….. (date) for being registered in the standing list for the purpose \nof executing or providing construction work/service/goods for fiscal \nyear…….. in the governmental offices situated in this district;  \nNow, therefore, this evidence is hereby provided upon registering him \nor her in the standing list.  \nRegistering authority’s:  \nName: \nPost: \nDate: \nSignature:  \n \n257 Inserted by the Fourth Amendment. \n192 \n \nSchedule -2C. 258 \n(Relating to sub -rule (3) of Rule 18)  \nFormat of records register of the standing list  \nGovernment of Nepal  \n…….Ministry  \n……..Department  \n……………………….office,  \n………………….  \nRegister of records of the standing list . \nSN Registration \nNo. \nDate of \nregistration  \nDescription of person/firm  Description \nof work \n(construction, \ngoods, \nconsultancy \nservice, \nNGO, other \nservice)  \nNature of \ngoods/service  \nRemarks  \nName Address  Contact  \nPerson  \nContact  \nNo. \n          \n          \n          \n \n  \n \n258 Inserted by the Fourth Amendment. \n193 \n \nSchedule -3 \n(Relating to sub-rule (1) of Rule 21)  \nProcurement contract of goods or other service  \nIn procuring g oods or other service , procure ment may be made  by \nconcluding any of the following contracts:  \n(a) Contract for the s upply of specific goods or other service : The \ncontract for the supply of specific goods or o ther service may be \nconcluded to procure raw materials, equipment, pharmaceuticals, \nmedicines, tools or other specific goods of similar nature required \nfor a specific work.  \n(b) Framework or unit rate contract : The framework or unit rate \ncontract may be con cluded to make arrangement for obtaining the \ngoods or other service set out in the procurement contract at the \ntime when the demand is made by a  public entity  from one or \nmore suppliers as per the rate and conditions set forth in the \nprocurement contract.  \nThis contract shall specify the minimum and maximum \nquantity of the goods or other service to be procured by the public \nentity.  \nThe period of this contract shall not generally be more than \none year.  \n(c) Multi-year contract : The multi-year contract may b e concluded in \nthe following circumstance s:  \n(a) If the public entity  obtains substantial benefit in \nprocuring by making multi-year contract rather than an \nannual procurement contract,  \n194 \n \n(b) If the quantity of procurement will not be substantially \naltered du ring the procurement contract period,  \n(c) If the design of the goods to be procured will not be \nchanged during the procurement contract period, and  \n(d) If the technical risk relating to the supply of goods is not \nhigher.  \n(d) Design, supply and installati on contract : The design, supply and \ninstallation contract may be concluded for making arrangement for \ndesigning goods of  high or complex technology such as large \npower plant or pumping station, supplying to construction site, \ninstalling, testing, operating  and providing training, according to  \nthe need , to the employees of the concerned public entity  to \noperate such goods. Such a contract may also be concluded to \ncarry out any two works out of the design, supply and installation \nwork.  \n(e) Turn key contract : The turn key contract may be concluded for \nmaking arrangement for completing the work of design, supply \nand installation of an industrial plant of high technology such as \nfertilizer production plant, milk processing as provided for in the \nprocure ment contract by mentioning the performance capacity of \nsuch a plant and transfer the same to the public entity  Note: The \ncontract s referred to in  clause s (a), (b), (d) and (e) may also be \nmulti-year contract . \n(f)259 Design, supply, installation and maintena nce contract : The design, \nsupply, installation and maintenance contract may be concluding \nfor designing goods with high or complex technology such as a \nbig boiler, big power plant, pumping station, turbine, ropeway, \n \n259 Inserted by the Fourth Amendment. \n195 \n \nrailway, cable car, assembly line and industrial plant, supply ing \nthem to the construction site and install ing them, conducting \ntesting, giving  training, as required, to the employees of the \nconcerned public entity for the operation of such goods and also \nmaintaining such structure.  \n  \n196 \n \n \nSchedule -4 \n(Relating to Rule 22)  \nProcurement contract of construction work  \nA public entity  may, in order to carry out a construction work, conclude any \none of the following contracts:  \n(a) Unit rate contract : A unit rate contract may be concluded  to \nexecute  a construction work the quantity of which is not \nascertained at the time of conclusion of the procurement contract \nor to provide the per unit activity of a construction work at the rate \nreferred to in the Bill of Quantities.  In such a unit rate , the bidder \nshall include the materials, labor and other things required to \ncomplete the proposed construction work.  \nIn making payment for the work done pursuant to this contract, \npayment shall be made of the amount to be found from computing \nthe quantity of construction work as ascertained from measurement \nof construction site by the per unit rate.  \n(b) Lump sum contract : A lump sum contract may be concluded to \ncarry out a construction work which is difficult to measure such as \ninstallation of underground water  pipeline or a construction work \nthat can be measured such as structure of a bridge. This contract \nshall be so concluded that all risk s and liabilit ies relating to the \nconstruction work remain with the  construction entrepreneur.  \nProvided that if the finan cial liability of the construction work \nis increased for the reason that the public entity  has ordered to \nmake a change of any type in the construction after the \ncommencement  of the construction work upon conclusion of the \nprocurement contract, the public entity  shall bear such liability.  \n197 \n \n(c) Cost-reimbursement contract : The cost-reimbursement contract \nmay be concluded to execute a construction work nature of which \nis high risky and unpredictable conditions of work and a \nconstruction entrepreneur does not agree to execute  or cannot \nexecute it  under the unit rate contract. In making payment to the \nconstruction entrepreneur for the c onstruction work to be executed  \nby concluding this contract, payment may be made for the actual \ncost incurred in executing such a construction work, overhead cost \nthereof , in addition to the profit as stated in the approved cost \nestimate. In having a const ruction work executed  by concluding \nthis contract, the chief of the public entity  shall fix the maximum \namount of cost -reimbursement and if an amount exceeding such \nlimit is to be paid , he or she shall obtain the prior approval of the \nhead of department.  \n(d) Time and material rate contract : The time and material rate \ncontract may be concluded to carry out a work by computing the \nlabor on the basis of time and the materials as per the unit rate due \nto unpredictability at the time of conclusion of the procure ment \ncontract of the labor and materials required for the repair and \nmaintenance of a construction work. This contract shall clearly \nmention that payment shall be made to the construction \nentrepreneur as follows:  \n(a) The amount found out after adding to the overhead cost \nand the profit referred to in the approved cost estimate to \nthe sum f ound out by dividing the labor of the \nconstruction entrepreneur on the basis of per hour or per \nday or per month, and  \n198 \n \n(b) The paid amount of the price of the material used for \nmaintenance, subject to the limitation of the amount \nreferred to in the procureme nt contract.  \n(e) Design and build contract : The design and build contract may be \nconcluded to have a design and construction of a construction \nwork to be executed by the same construction entrepreneur. The \npublic entity  shall start the work under this cont ract only after \ncausing the design of construction work to be examined and \napproved by a technician or a team of technicians. The technician \nor team of technicians who so examines the design shall  examine \nand approve such design, drawing and cost estimate by following \nthe procedure set forth in this Regulation for examination and \napproval.  \n(f) Management contract : The management contract may be \nconcluded to have a construction work executed  by different sub -\ncontractors subject to the conditions that legal and contractual \nobligation relating to the quality and completion period of the \nconstruction work shall be undertaken by the construction \nentrepreneur himself  or herself with whom the public entity  \nconcludes the procurement contract and such work is executed  \nunder his  or her management and supervision. Payment for the \nwork under this contract shall be made only to the construction \nentrepreneur who has concluded the procurement contract with the \npublic entity .  \n(g) Performance -based maintenance or management contract : The \nperformance -based maintenance or management contract may be \nconcluded to execute  a construction work without mentioning the \nequipment required to maintain and manage the construction work \nand item wise work and by mentioning only the final performance.  \n199 \n \n(h) Piecework contract : To execute a construction work related to \nsmall scale maintenance and repair required  to be executed  \nfrequently as and when required, the piecework contract may be \nconcluded by establishing the list of price of such work.  \nGenerally, the period of this contract shall not exceed one \nyear. \n(i)260 Build and maintenance contract : The build and maintenance \ncontract may be concluded t o build a big f ast track, power plant \nwith a big reservoir or pumping station or turbine, ropeway,  \nrailway cable car or similar other physical structure with \nsophisticated or complex technology, conduct testing, give \ntraining, as required, to the employees of the concern ed public \nentity for operating such structure and also to repair and maintain \nsuch structure.  \n(j)261 Turnkey contract : The turnkey contract may be concluded to build \na big fast track, power plant with a big reservoir or pumping \nstation or turbine, ropeway, railway cable car, bridge or road with \nsophisticate technology or similar other physical structure with \nsophisticated or complex technology, conduct testing, complete \noperation of such structure and hand it over to the public entity.   \n \n260 Inserted by the Fourth Amendment. \n261 Inserted by the Fourth Amendment. \n200 \n \nSchedule -5 \n(Relating to Rule 23)  \nProcurement contract of consultancy service  \nA Public entity  may procure a consultancy service by concluding any of the \nfollowing contracts:  \n(a) Lump sum contract : To acquire  consultancy service for a work \nclearly identified, having low risk to the consultant and the \nquality of which can be easily measured such as feasibility \nstudy, project design, preparing bidding documents, the lump \nsum contract may be concluded. This contract shall provide that \nthe consultant shall submit a report to the public entity  within a \nspecified time upon concluding a work having technic al \ncharacteristics as referred to in the terms of reference and for \nthat he  or she shall be entitled to the service fee.  \n(b) Time-based contract : If the period of consultancy service such \nas supervisi ng construction work, manag ing large professional \norganization or design ing complex structure such as a dam, \ntunnel cannot be anticipated , the time-based contract may be \nconcluded for such a work. This contract shall provide that the \nconsultant's service fee shall be determined as follows:  \n(a) The amount to be found out after multiplying the \nrate of remuneration referred to in the procurement \ncontract by the time actually  taken by the \nconsultant to do the work under the procurement \ncontract,  \n(b) Reimbursement amount of the actual miscellaneous \nexpense as sup ported by the bill or receipt.  \n201 \n \n(c) Performance -based fee payment contract : Where a consultancy \nservice is to be  acquired  on the condition that the consultant \nshall be called to do the  work as and when required or that the \nservice fee shall be provided on t he basis of the work he  or she  \nhas completed,  the performance -based fee paying contract may \nbe concluded. The service fee of such a consultant shall be as \nspecified  in the procurement contract.  \n(d) Percentage -based contract : The percentage -based contract may \nbe concluded to procure such service as inspection of goods, \narchitect's service, supervision or monitoring service or other \nservice of similar nature. This contract shall provide that \npayment to the consultant shall be made according to  the \npercentage of the estimated or actual cost of the concerned \nconstruction work or project or the cost of goods procured or \ninspected.  \n(e) Indefinite service period contract : The indefinite service period \ncontract may be concluded to acquire consultancy service in \nrespect of specific work as and when basis and service period of \nwhich is not definite such as a consultant required from time to \ntime to bring a construction work into operation, a adjudicator or \narbitrator of a dispute relating to procuremen t contract, consultant \nfor institutional reform or procurement, technical trouble shooter. \nThis contract shall provide the following matters: \n(a) The consultant shall carry out the work referred to \nin the contract as and when necessary for the \npublic entity  at the rate set out  in the procurement \ncontract.  \n(b) Remuneration shall be paid on the basis of actual \ntime taken by the consultant to carry out the work.  \n202 \n \nSchedule -5A. 262 \n(Relating to sub -rule (2) of Rule 87A.  \nPublic entities doing business transacti on in competition with private sector", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "1", "title": "Nepal Telecom Company Limited", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Nepal Food Corporation", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "3", "title": "National Trading Limited", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Nepal Airlines Corporation", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Janak Siksha Samagri Kendra Limited", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Nepal Drugs Limited", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Singhadurbar Vaidhyakhana  Development Board", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Herbs Production and Processing Company Limited", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Such other public entities as designated by the Government of Nepa